package com.mylosis.roster.model;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class AccountTest
{
    @Test
    public void searchHaystackContainsLowercaseAliasUsernameCharacterNameAndNotes()
    {
        Account account = Account.builder()
            .alias("MyAlias")
            .username("MyUsername")
            .characterName("MyCharacter")
            .metadata(AccountMetadata.builder().notes("MyNotes").build())
            .build();

        String haystack = account.getSearchHaystack();

        assertTrue(haystack.contains("myalias"));
        assertTrue(haystack.contains("myusername"));
        assertTrue(haystack.contains("mycharacter"));
        assertTrue(haystack.contains("mynotes"));
    }

    @Test
    public void setAliasInvalidatesCache()
    {
        Account account = Account.builder().alias("Old").username("user").build();
        account.getSearchHaystack();

        account.setAlias("NewAlias");

        assertTrue(account.getSearchHaystack().contains("newalias"));
    }

    @Test
    public void setUsernameInvalidatesCache()
    {
        Account account = Account.builder().alias("alias").username("OldUser").build();
        account.getSearchHaystack();

        account.setUsername("NewUser");

        assertTrue(account.getSearchHaystack().contains("newuser"));
    }

    @Test
    public void setCharacterNameInvalidatesCache()
    {
        Account account = Account.builder().alias("alias").username("user").characterName("OldChar").build();
        account.getSearchHaystack();

        account.setCharacterName("NewChar");

        assertTrue(account.getSearchHaystack().contains("newchar"));
    }

    @Test
    public void setMetadataInvalidatesCache()
    {
        Account account = Account.builder().alias("alias").username("user")
            .metadata(AccountMetadata.builder().notes("OldNotes").build())
            .build();
        account.getSearchHaystack();

        account.setMetadata(AccountMetadata.builder().notes("NewNotes").build());

        assertTrue(account.getSearchHaystack().contains("newnotes"));
    }

    @Test
    public void displayNameReturnsAliasWhenNonEmpty()
    {
        Account account = Account.builder().alias("MyAlias").username("MyUsername").build();

        assertEquals("MyAlias", account.getDisplayName());
    }

    @Test
    public void displayNameReturnsUsernameWhenAliasEmpty()
    {
        Account account = Account.builder().alias("").username("MyUsername").build();

        assertEquals("MyUsername", account.getDisplayName());
    }
}

package com.mylosis.roster.storage;

import com.google.gson.Gson;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountData;
import com.mylosis.roster.model.ProfileGroup;
import org.junit.After;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.stream.Collectors;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class AccountStorageTest
{
    @Rule
    public TemporaryFolder folder = new TemporaryFolder();

    // Test-only Gson; the plugin itself always uses RuneLite's injected instance.
    private final Gson gson = new Gson();
    private ScheduledExecutorService executor;
    /** Stands in for the ConfigManager "roster.data" value. */
    private String configValue;
    private int configWrites;

    @Before
    public void setUp()
    {
        executor = Executors.newSingleThreadScheduledExecutor();
    }

    @After
    public void tearDown()
    {
        executor.shutdownNow();
    }

    private AccountStorage newStorage()
    {
        return new AccountStorage(gson, () -> configValue, json -> {
            configValue = json;
            configWrites++;
        }, new RosterFileMirror(gson, folder.getRoot(), executor));
    }

    private static Account account(String id, String groupId)
    {
        Account account = Account.createNew(null, id + "@example.com");
        account.setId(id);
        account.setGroupId(groupId);
        return account;
    }

    private static List<String> ids(List<Account> accounts)
    {
        return accounts.stream().map(Account::getId).collect(Collectors.toList());
    }

    @Test
    public void savingAnExistingAccountKeepsItsPositionAndSortOrder()
    {
        AccountStorage storage = newStorage();
        storage.saveAccount(account("a", null));
        storage.saveAccount(account("b", null));
        storage.saveAccount(account("c", null));

        Account a = storage.getAccount("a");
        a.setAlias("renamed");
        storage.saveAccount(a);

        assertEquals(Arrays.asList("a", "b", "c"), ids(storage.getAccounts()));
        assertEquals(0, storage.getAccount("a").getMetadata().getSortOrder());
    }

    @Test
    public void replacingAnAccountWithACopyKeepsItsPosition()
    {
        AccountStorage storage = newStorage();
        storage.saveAccount(account("a", null));
        storage.saveAccount(account("b", null));

        Account copy = account("a", null);
        copy.setAlias("copy");
        storage.saveAccount(copy);

        assertEquals(Arrays.asList("a", "b"), ids(storage.getAccounts()));
        assertEquals("copy", storage.getAccount("a").getAlias());
    }

    @Test
    public void newAccountsAppendToTheEndOfTheirCategory()
    {
        AccountStorage storage = newStorage();
        ProfileGroup group = ProfileGroup.createNew("Mains");
        storage.saveGroup(group);
        storage.saveAccount(account("g1", group.getId()));
        storage.saveAccount(account("u1", null));
        storage.saveAccount(account("g2", group.getId()));

        assertEquals(0, storage.getAccount("g1").getMetadata().getSortOrder());
        assertEquals(1, storage.getAccount("g2").getMetadata().getSortOrder());
        assertEquals(0, storage.getAccount("u1").getMetadata().getSortOrder());
    }

    @Test
    public void newCategoriesAppendAfterExistingOnes()
    {
        AccountStorage storage = newStorage();
        ProfileGroup first = ProfileGroup.createNew("First");
        ProfileGroup second = ProfileGroup.createNew("Second");
        storage.saveGroup(first);
        storage.saveGroup(second);

        // Renaming (or collapsing) must not move a category.
        first.setName("Renamed");
        storage.saveGroup(first);
        ProfileGroup third = ProfileGroup.createNew("Third");
        storage.saveGroup(third);

        List<ProfileGroup> groups = storage.getGroups();
        assertEquals(first.getId(), groups.get(0).getId());
        assertEquals(second.getId(), groups.get(1).getId());
        assertEquals(third.getId(), groups.get(2).getId());
    }

    @Test
    public void deletingACategoryAppendsItsAccountsToUncategorized()
    {
        AccountStorage storage = newStorage();
        ProfileGroup group = ProfileGroup.createNew("Alts");
        storage.saveGroup(group);
        storage.saveAccount(account("u1", null));
        storage.saveAccount(account("g1", group.getId()));

        storage.deleteGroup(group.getId());

        Account moved = storage.getAccount("g1");
        assertNull(moved.getGroupId());
        assertEquals(1, moved.getMetadata().getSortOrder());
    }

    @Test
    public void ownWritesAreRecognized()
    {
        AccountStorage storage = newStorage();
        storage.saveAccount(account("a", null));

        assertTrue(storage.isOwnWrite(configValue));
        assertFalse(storage.isOwnWrite("{\"accounts\":[]}"));
        assertFalse(storage.reloadIfChangedExternally());
    }

    @Test
    public void externalConfigChangeReplacesTheCache()
    {
        AccountStorage storage = newStorage();
        storage.saveAccount(account("a", null));

        // e.g. RuneLite switched to a profile holding different roster data
        AccountData other = AccountData.createEmpty();
        other.addAccount(account("z", null));
        configValue = gson.toJson(other);

        assertTrue(storage.reloadIfChangedExternally());
        assertEquals(Collections.singletonList("z"), ids(storage.getAccounts()));

        // The next save must not resurrect the old data.
        storage.saveAccount(account("y", null));
        assertTrue(configValue.contains("\"z\""));
        assertFalse(configValue.contains("\"a\""));
    }

    @Test
    public void shutdownFlushesTheFileAndReloadsOnNextUse() throws Exception
    {
        AccountStorage storage = newStorage();
        storage.saveAccount(account("a", null));
        storage.shutdown();

        File file = new File(folder.getRoot(), "roster.json");
        assertTrue(file.exists());
        assertTrue(new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8).contains("\"a\""));

        configValue = gson.toJson(AccountData.createEmpty());
        assertTrue(storage.getAccounts().isEmpty());
    }

    @Test
    public void emptyConfigIsReseededFromTheFileBackup()
    {
        AccountStorage first = newStorage();
        first.saveAccount(account("a", null));
        first.shutdown();

        configValue = null;
        configWrites = 0;
        AccountStorage second = newStorage();

        assertEquals(Collections.singletonList("a"), ids(second.getAccounts()));
        assertEquals(1, configWrites);
    }

    @Test
    public void unreadableFileIsQuarantinedAndBackupUsed() throws Exception
    {
        AccountStorage first = newStorage();
        first.saveAccount(account("a", null));
        first.shutdown();
        first.saveAccount(account("b", null));
        first.shutdown();

        File data = new File(folder.getRoot(), "roster.json");
        Files.write(data.toPath(), "{ not json".getBytes(StandardCharsets.UTF_8));
        configValue = null;

        List<Account> recovered = newStorage().getAccounts();

        assertEquals(Collections.singletonList("a"), ids(recovered));
        assertTrue(new File(folder.getRoot(), "roster.json.corrupt").exists());
    }
}

package com.mylosis.roster.storage;

import com.google.gson.Gson;

import java.io.File;
import java.util.concurrent.ScheduledExecutorService;

/**
 * Builds an {@link AccountStorage} backed by an in-memory config value and a
 * file mirror in {@code directory}, for tests outside this package.
 */
public final class TestStorage
{
    private TestStorage() {}

    public static AccountStorage create(File directory, ScheduledExecutorService executor)
    {
        // Test-only Gson; the plugin itself always uses RuneLite's injected instance.
        Gson gson = new Gson();
        String[] config = new String[1];
        return new AccountStorage(gson, () -> config[0], json -> config[0] = json,
            new RosterFileMirror(gson, directory, executor));
    }
}

package com.mylosis.roster.storage;

import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountData;
import com.mylosis.roster.model.AccountMetadata;
import com.mylosis.roster.model.ImportDuplicateMode;
import com.mylosis.roster.model.ProfileGroup;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class AccountDataMergerTest
{
    private static Account account(String id, String username, String alias)
    {
        return Account.builder().id(id).username(username).alias(alias).build();
    }

    private static AccountData dataWith(Account... accounts)
    {
        AccountData data = AccountData.createEmpty();
        for (Account a : accounts)
        {
            data.addAccount(a);
        }
        return data;
    }

    @Test
    public void nonDuplicateAccountIsAdded()
    {
        AccountData existing = dataWith(account("e1", "userA", "AliasA"));
        AccountData importData = dataWith(account("i1", "userB", "AliasB"));

        ImportStats stats = new AccountDataMerger().merge(existing, importData, ImportDuplicateMode.SKIP);

        assertEquals(1, stats.getAccountsAdded());
        assertEquals(2, existing.getAccounts().size());
    }

    @Test
    public void duplicateDetectedBySameId()
    {
        AccountData existing = dataWith(account("dup1", "userA", "AliasA"));
        AccountData importData = dataWith(account("dup1", "userDifferent", "AliasDifferent"));

        ImportStats stats = new AccountDataMerger().merge(existing, importData, ImportDuplicateMode.SKIP);

        assertEquals(0, stats.getAccountsAdded());
        assertEquals(1, stats.getAccountsSkipped());
    }

    @Test
    public void duplicateDetectedBySameUsernameAndAliasCaseInsensitive()
    {
        AccountData existing = dataWith(account("e1", "UserA", "AliasA"));
        AccountData importData = dataWith(account("i1", "usera", "aliasa"));

        ImportStats stats = new AccountDataMerger().merge(existing, importData, ImportDuplicateMode.SKIP);

        assertEquals(0, stats.getAccountsAdded());
        assertEquals(1, stats.getAccountsSkipped());
    }

    @Test
    public void sameUsernameDifferentAliasIsNotADuplicate()
    {
        AccountData existing = dataWith(account("e1", "userA", "AliasA"));
        AccountData importData = dataWith(account("i1", "userA", "AliasB"));

        ImportStats stats = new AccountDataMerger().merge(existing, importData, ImportDuplicateMode.SKIP);

        assertEquals(1, stats.getAccountsAdded());
        assertEquals(0, stats.getAccountsSkipped());
        assertEquals(2, existing.getAccounts().size());
    }

    @Test
    public void skipModeLeavesExistingUntouched()
    {
        Account existingAccount = account("dup1", "userA", "AliasA");
        AccountData existing = dataWith(existingAccount);
        AccountData importData = dataWith(account("dup1", "userA", "AliasA"));

        ImportStats stats = new AccountDataMerger().merge(existing, importData, ImportDuplicateMode.SKIP);

        assertEquals(1, stats.getAccountsSkipped());
        assertEquals(1, existing.getAccounts().size());
        assertTrue(existing.getAccounts().get(0) == existingAccount);
    }

    @Test
    public void updateModeReplacesExistingButKeepsExistingId()
    {
        // Duplicate detection keys on username+alias, so the incoming account
        // must keep that pair unchanged; the update is observed via a
        // different field (characterName) that differs from the existing record.
        AccountData existing = dataWith(account("existingId", "userA", "AliasA"));
        Account incoming = account("incomingId", "userA", "AliasA");
        incoming.setCharacterName("UpdatedCharacter");
        AccountData importData = dataWith(incoming);

        ImportStats stats = new AccountDataMerger().merge(existing, importData, ImportDuplicateMode.UPDATE);

        assertEquals(1, stats.getAccountsUpdated());
        assertEquals(1, existing.getAccounts().size());
        Account result = existing.getAccounts().get(0);
        assertEquals("existingId", result.getId());
        assertEquals("UpdatedCharacter", result.getCharacterName());
    }

    @Test
    public void addWithSuffixGivesFreshUniqueAliasAndNewId()
    {
        AccountData existing = dataWith(account("existingId", "userA", "SameAlias"));
        Account incoming = account("incomingId", "userA", "SameAlias");
        AccountData importData = dataWith(incoming);

        ImportStats stats = new AccountDataMerger().merge(existing, importData, ImportDuplicateMode.ADD_WITH_SUFFIX);

        assertEquals(1, stats.getAccountsAdded());
        assertEquals(2, existing.getAccounts().size());
        Account added = existing.getAccounts().get(1);
        assertEquals("SameAlias (2)", added.getAlias());
        assertNotEquals("incomingId", added.getId());
        assertNotNull(added.getId());
    }

    @Test
    public void addWithSuffixIsCaseInsensitiveAndIncrementsOnRepeat()
    {
        // Duplicate detection keys on username+alias, so both incoming accounts
        // must match the existing username (case-insensitively) to be flagged
        // as duplicates of the same original entry.
        AccountData existing = dataWith(account("existingId", "UserA", "SameAlias"));
        List<Account> incomingAccounts = new ArrayList<>();
        incomingAccounts.add(account("i1", "usera", "sameAlias"));
        incomingAccounts.add(account("i2", "USERA", "SameAlias"));
        AccountData importData = AccountData.createEmpty();
        for (Account a : incomingAccounts)
        {
            importData.addAccount(a);
        }

        ImportStats stats = new AccountDataMerger().merge(existing, importData, ImportDuplicateMode.ADD_WITH_SUFFIX);

        assertEquals(2, stats.getAccountsAdded());
        assertEquals(3, existing.getAccounts().size());
        // The suffix base is the incoming account's own alias casing, not the
        // matched existing account's casing.
        assertEquals("sameAlias (2)", existing.getAccounts().get(1).getAlias());
        assertEquals("SameAlias (3)", existing.getAccounts().get(2).getAlias());
    }

    @Test
    public void groupsAreAddedOrSkippedWithCorrectStats()
    {
        AccountData existing = AccountData.createEmpty();
        existing.addGroup(ProfileGroup.builder().id("existingGroup").name("Existing").build());

        AccountData importData = AccountData.createEmpty();
        importData.addGroup(ProfileGroup.builder().id("existingGroup").name("Existing Renamed").build());
        importData.addGroup(ProfileGroup.builder().id("newGroup").name("New").build());

        ImportStats stats = new AccountDataMerger().merge(existing, importData, ImportDuplicateMode.SKIP);

        assertEquals(1, stats.getGroupsAdded());
        assertEquals(1, stats.getGroupsSkipped());
        assertEquals(2, existing.getGroups().size());
    }

    private static Account ordered(String id, String username, String groupId, int sortOrder)
    {
        Account account = account(id, username, null);
        account.setGroupId(groupId);
        account.setMetadata(AccountMetadata.builder().sortOrder(sortOrder).build());
        return account;
    }

    @Test
    public void importedAccountsAppendAfterExistingOnesInTheirOwnOrder()
    {
        AccountData existing = dataWith(ordered("e0", "a", null, 0), ordered("e1", "b", null, 1));
        // Exported in list order [i1, i0] but sortOrder says i0 comes first.
        AccountData importData = dataWith(ordered("i1", "d", null, 1), ordered("i0", "c", null, 0));

        new AccountDataMerger().merge(existing, importData, ImportDuplicateMode.SKIP);

        assertEquals(2, existing.findAccountById("i0").getMetadata().getSortOrder());
        assertEquals(3, existing.findAccountById("i1").getMetadata().getSortOrder());
    }

    @Test
    public void importedCategoriesAppendAfterExistingOnes()
    {
        AccountData existing = AccountData.createEmpty();
        existing.addGroup(ProfileGroup.builder().id("g0").sortOrder(0).build());
        AccountData importData = AccountData.createEmpty();
        importData.addGroup(ProfileGroup.builder().id("g1").sortOrder(0).build());

        new AccountDataMerger().merge(existing, importData, ImportDuplicateMode.SKIP);

        assertEquals(1, existing.findGroupById("g1").getSortOrder());
    }

    @Test
    public void updateKeepsTheExistingPositionAndListSlot()
    {
        AccountData existing = dataWith(ordered("e0", "a", null, 0), ordered("e1", "b", null, 1));
        AccountData importData = dataWith(ordered("e0", "a", null, 9));

        new AccountDataMerger().merge(existing, importData, ImportDuplicateMode.UPDATE);

        assertEquals("e0", existing.getAccounts().get(0).getId());
        assertEquals(0, existing.findAccountById("e0").getMetadata().getSortOrder());
    }

    @Test
    public void detailedMessageSummarizesTheImport()
    {
        ImportResult result = ImportResult.success(new ImportStats(2, 3, 1, 1, 0));

        assertEquals("Added 2, updated 1, skipped 3 duplicates, 1 category", result.getDetailedMessage());
        assertTrue(result.hasChanges());
        assertEquals("All accounts already exist",
            ImportResult.success(new ImportStats(0, 0, 0, 0, 1)).getDetailedMessage());
    }
}

package com.mylosis.roster.storage;

import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountData;
import com.mylosis.roster.model.AccountMetadata;
import com.mylosis.roster.model.AccountType;
import com.mylosis.roster.model.ProfileGroup;
import org.junit.Test;

import java.util.ArrayList;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class ImportExportServiceValidationTest
{
    private static AccountData validData()
    {
        AccountData data = AccountData.createEmpty();
        data.addAccount(Account.builder().id("a1").username("userA").build());
        return data;
    }

    @Test
    public void validDataReturnsNull()
    {
        assertNull(ImportExportService.validateImportData(validData()));
    }

    @Test
    public void versionNewerThanCurrentReturnsError()
    {
        AccountData data = validData();
        data.setVersion(AccountData.CURRENT_VERSION + 1);

        assertNotNull(ImportExportService.validateImportData(data));
    }

    @Test
    public void accountWithNullIdReturnsError()
    {
        AccountData data = AccountData.createEmpty();
        data.addAccount(Account.builder().id(null).username("userA").build());

        assertNotNull(ImportExportService.validateImportData(data));
    }

    @Test
    public void accountWithEmptyIdReturnsError()
    {
        AccountData data = AccountData.createEmpty();
        data.addAccount(Account.builder().id("").username("userA").build());

        assertNotNull(ImportExportService.validateImportData(data));
    }

    @Test
    public void accountWithNullUsernameReturnsError()
    {
        AccountData data = AccountData.createEmpty();
        data.addAccount(Account.builder().id("a1").username(null).build());

        assertNotNull(ImportExportService.validateImportData(data));
    }

    @Test
    public void accountWithEmptyUsernameReturnsError()
    {
        AccountData data = AccountData.createEmpty();
        data.addAccount(Account.builder().id("a1").username("").build());

        assertNotNull(ImportExportService.validateImportData(data));
    }

    @Test
    public void groupWithNullIdReturnsError()
    {
        AccountData data = AccountData.createEmpty();
        data.addGroup(ProfileGroup.builder().id(null).name("Group").build());

        assertNotNull(ImportExportService.validateImportData(data));
    }

    @Test
    public void groupWithEmptyIdReturnsError()
    {
        AccountData data = AccountData.createEmpty();
        data.addGroup(ProfileGroup.builder().id("").name("Group").build());

        assertNotNull(ImportExportService.validateImportData(data));
    }

    @Test
    public void nullAccountsAndGroupsListsAreTolerated()
    {
        AccountData data = AccountData.builder()
            .version(AccountData.CURRENT_VERSION)
            .accounts(null)
            .groups(null)
            .build();

        assertNull(ImportExportService.validateImportData(data));
    }

    @Test
    public void accountWithNullMetadataGetsDefaultMetadata()
    {
        AccountData data = AccountData.createEmpty();
        Account account = Account.builder().id("a1").username("userA").metadata(null).build();
        data.addAccount(account);

        ImportExportService.normalizeImportData(data);

        assertNotNull(account.getMetadata());
        assertEquals(AccountType.MAIN, account.getMetadata().getAccountType());
    }

    @Test
    public void accountWithMetadataButNullAccountTypeGetsMainBackfilled()
    {
        AccountData data = AccountData.createEmpty();
        Account account = Account.builder().id("a1").username("userA")
            .metadata(AccountMetadata.builder().accountType(null).build())
            .build();
        data.addAccount(account);

        ImportExportService.normalizeImportData(data);

        assertEquals(AccountType.MAIN, account.getMetadata().getAccountType());
    }

    @Test
    public void normalizeToleratesNullAccountsList()
    {
        AccountData data = AccountData.builder()
            .version(AccountData.CURRENT_VERSION)
            .accounts(null)
            .groups(new ArrayList<>())
            .build();

        ImportExportService.normalizeImportData(data);
        // No exception thrown means success; nothing else to assert.
    }
}

package com.mylosis.roster.ui.components;

import org.junit.Test;

import javax.swing.JLabel;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class SafeTextTest
{
    private static final String HOSTILE = "<html><img src='http://example.invalid/x'>";

    @Test
    public void ordinaryTextPassesThrough()
    {
        assertEquals("Iron Bob", SafeText.htmlSafe("Iron Bob"));
    }

    @Test
    public void htmlTextIsEscapedSoItRendersLiterally()
    {
        String safe = SafeText.htmlSafe(HOSTILE);

        assertTrue(safe.startsWith("<html>"));
        assertFalse(safe.contains("<img"));
        assertTrue(safe.contains("&lt;img"));
    }

    @Test
    public void categoryComboItemsAreHtmlSafe()
    {
        assertFalse(new GroupComboItem("id", HOSTILE).toString().contains("<img"));
        assertEquals("Mains", new GroupComboItem("id", "Mains").toString());
    }

    @Test
    public void plainDisablesTheHtmlRenderer()
    {
        JLabel label = SafeText.plain(new JLabel(HOSTILE));

        assertEquals(Boolean.TRUE, label.getClientProperty("html.disable"));
    }

    @Test
    public void singleLineFlattensNewlines()
    {
        assertEquals("a <html>b", SafeText.singleLine("a\n<html>b"));
    }
}

package com.mylosis.roster.ui.components;

import org.junit.Test;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class ThemeVersionTest
{
    /** The version shown in the panel header must be bumped with the build version. */
    @Test
    public void headerVersionMatchesBuildGradle() throws Exception
    {
        // Gradle runs tests from the project directory.
        String build = new String(Files.readAllBytes(Paths.get("build.gradle")), StandardCharsets.UTF_8);
        Matcher matcher = Pattern.compile("(?m)^version\\s*=\\s*'([^']+)'").matcher(build);

        assertTrue("version line not found in build.gradle", matcher.find());
        assertEquals(matcher.group(1), Theme.VERSION);
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountMetadata;
import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class DropExecutorRenumberTest
{
    private static Account accountWithOrder(String id, int sortOrder)
    {
        return Account.builder()
            .id(id)
            .metadata(AccountMetadata.builder().sortOrder(sortOrder).build())
            .build();
    }

    @Test
    public void insertsInMiddleAndRenumbersSequentially()
    {
        List<Account> siblings = new ArrayList<>();
        siblings.add(accountWithOrder("a", 0));
        siblings.add(accountWithOrder("b", 1));
        Account moved = accountWithOrder("moved", 99);

        List<Account> changed = DropExecutor.renumberWithInsert(siblings, moved, 1);

        assertEquals(3, changed.size());
        assertEquals("a", changed.get(0).getId());
        assertEquals("moved", changed.get(1).getId());
        assertEquals("b", changed.get(2).getId());
        assertEquals(0, changed.get(0).getMetadata().getSortOrder());
        assertEquals(1, changed.get(1).getMetadata().getSortOrder());
        assertEquals(2, changed.get(2).getMetadata().getSortOrder());
    }

    @Test
    public void insertsAtStart()
    {
        List<Account> siblings = new ArrayList<>();
        siblings.add(accountWithOrder("a", 0));
        siblings.add(accountWithOrder("b", 1));
        Account moved = accountWithOrder("moved", 99);

        List<Account> changed = DropExecutor.renumberWithInsert(siblings, moved, 0);

        assertEquals("moved", changed.get(0).getId());
        assertEquals("a", changed.get(1).getId());
        assertEquals("b", changed.get(2).getId());
        assertEquals(0, changed.get(0).getMetadata().getSortOrder());
        assertEquals(1, changed.get(1).getMetadata().getSortOrder());
        assertEquals(2, changed.get(2).getMetadata().getSortOrder());
    }

    @Test
    public void negativeIndexAppends()
    {
        List<Account> siblings = new ArrayList<>();
        siblings.add(accountWithOrder("a", 0));
        siblings.add(accountWithOrder("b", 1));
        Account moved = accountWithOrder("moved", 99);

        List<Account> changed = DropExecutor.renumberWithInsert(siblings, moved, -1);

        assertEquals("a", changed.get(0).getId());
        assertEquals("b", changed.get(1).getId());
        assertEquals("moved", changed.get(2).getId());
        assertEquals(2, changed.get(2).getMetadata().getSortOrder());
    }

    @Test
    public void indexBeyondSizeClampsToAppend()
    {
        List<Account> siblings = new ArrayList<>();
        siblings.add(accountWithOrder("a", 0));
        siblings.add(accountWithOrder("b", 1));
        Account moved = accountWithOrder("moved", 99);

        List<Account> changed = DropExecutor.renumberWithInsert(siblings, moved, 50);

        assertEquals("a", changed.get(0).getId());
        assertEquals("b", changed.get(1).getId());
        assertEquals("moved", changed.get(2).getId());
        assertEquals(2, changed.get(2).getMetadata().getSortOrder());
    }

    @Test
    public void returnedListContainsMovedPlusAllSiblingsWithMetadata()
    {
        List<Account> siblings = new ArrayList<>();
        siblings.add(accountWithOrder("a", 0));
        siblings.add(accountWithOrder("b", 1));
        siblings.add(accountWithOrder("c", 2));
        Account moved = accountWithOrder("moved", 99);

        List<Account> changed = DropExecutor.renumberWithInsert(siblings, moved, 2);

        assertEquals(4, changed.size());
        assertTrue(changed.stream().anyMatch(a -> a.getId().equals("moved")));
        assertTrue(changed.stream().anyMatch(a -> a.getId().equals("a")));
        assertTrue(changed.stream().anyMatch(a -> a.getId().equals("b")));
        assertTrue(changed.stream().anyMatch(a -> a.getId().equals("c")));
    }

    @Test
    public void siblingWithNullMetadataGetsMetadataAndIsRenumbered()
    {
        List<Account> siblings = new ArrayList<>();
        siblings.add(accountWithOrder("a", 0));
        Account noMeta = Account.builder().id("noMeta").build();
        siblings.add(noMeta);
        Account moved = accountWithOrder("moved", 99);

        List<Account> changed = DropExecutor.renumberWithInsert(siblings, moved, 2);

        assertEquals(3, changed.size());
        assertNotNull(noMeta.getMetadata());
        assertEquals(1, noMeta.getMetadata().getSortOrder());
        assertEquals(2, moved.getMetadata().getSortOrder());
    }

    // resolveInsertIndex: visible neighbours -> index in the stored order

    @Test
    public void insertsInFrontOfBeforeNeighbour()
    {
        assertEquals(1, DropExecutor.resolveInsertIndex(Arrays.asList("a", "b", "c"), "b", "a"));
    }

    @Test
    public void fallsBackToAfterNeighbourAtTheEnd()
    {
        assertEquals(3, DropExecutor.resolveInsertIndex(Arrays.asList("a", "b", "c"), null, "c"));
    }

    @Test
    public void emptyTargetAppends()
    {
        assertEquals(0, DropExecutor.resolveInsertIndex(Collections.emptyList(), null, null));
    }

    @Test
    public void downwardMoveInSameCategoryLandsBetweenTheNeighbours()
    {
        // Stored [A, B, C]; A dragged to between B and C. The visible
        // neighbours are B (after) and C (before); siblings exclude A.
        int index = DropExecutor.resolveInsertIndex(Arrays.asList("b", "c"), "c", "b");
        List<Account> changed = DropExecutor.renumberWithInsert(
            new ArrayList<>(Arrays.asList(accountWithOrder("b", 1), accountWithOrder("c", 2))),
            accountWithOrder("a", 0), index);

        assertEquals("b", changed.get(0).getId());
        assertEquals("a", changed.get(1).getId());
        assertEquals("c", changed.get(2).getId());
    }

    @Test
    public void neighboursHiddenBySearchStillResolveAgainstStoredOrder()
    {
        // Stored [a, x, b] with x filtered out of view; dropping between the
        // visible a and b lands in front of b in the stored order.
        assertEquals(2, DropExecutor.resolveInsertIndex(Arrays.asList("a", "x", "b"), "b", "a"));
    }
}

package com.mylosis.roster.ui.dnd;

import org.junit.Test;

import java.awt.Point;
import java.awt.Rectangle;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class DropTargetFinderInsertTest
{
    private static final Rectangle ZONE = new Rectangle(0, 0, 200, 400);

    // Three stacked list cards, 50px tall with 4px gaps.
    private static final List<Rectangle> LIST = Arrays.asList(
        new Rectangle(0, 0, 200, 50),
        new Rectangle(0, 54, 200, 50),
        new Rectangle(0, 108, 200, 50));

    // 2-column grid, row-major: [0 1] [2 3] [4]
    private static final List<Rectangle> GRID = Arrays.asList(
        new Rectangle(0, 0, 98, 56),
        new Rectangle(102, 0, 98, 56),
        new Rectangle(0, 60, 98, 56),
        new Rectangle(102, 60, 98, 56),
        new Rectangle(0, 120, 98, 56));

    @Test
    public void listInsertsBeforeFirstCardBelowPointerMidpoint()
    {
        assertEquals(0, DropTargetFinder.listInsertPoint(LIST, new Point(10, 10), ZONE).index);
        assertEquals(1, DropTargetFinder.listInsertPoint(LIST, new Point(10, 40), ZONE).index);
        assertEquals(2, DropTargetFinder.listInsertPoint(LIST, new Point(10, 100), ZONE).index);
    }

    @Test
    public void listPastLastCardAppendsWithLineAtItsBottom()
    {
        DropTargetFinder.InsertPoint insert = DropTargetFinder.listInsertPoint(LIST, new Point(10, 300), ZONE);

        assertEquals(3, insert.index);
        assertEquals(158, insert.indicator.y);
        assertEquals(0, insert.indicator.height);
    }

    @Test
    public void emptyListHasNoIndicator()
    {
        DropTargetFinder.InsertPoint insert = DropTargetFinder.listInsertPoint(Collections.emptyList(), new Point(10, 10), ZONE);

        assertEquals(0, insert.index);
        assertNull(insert.indicator);
    }

    @Test
    public void gridUsesColumnWithinARow()
    {
        // Left half of card 1 (top-right): before card 1.
        assertEquals(1, DropTargetFinder.gridInsertPoint(GRID, new Point(110, 20)).index);
        // Right half of card 1: after it, i.e. before card 2.
        assertEquals(2, DropTargetFinder.gridInsertPoint(GRID, new Point(190, 20)).index);
        // Left half of card 3.
        assertEquals(3, DropTargetFinder.gridInsertPoint(GRID, new Point(110, 70)).index);
    }

    @Test
    public void gridIndicatorIsVerticalBesideTheNeighbourOnThePointersRow()
    {
        // Right half of card 1: line to the right of card 1, not left of card 2 (next row).
        DropTargetFinder.InsertPoint insert = DropTargetFinder.gridInsertPoint(GRID, new Point(190, 20));

        assertEquals(0, insert.indicator.width);
        assertEquals(0, insert.indicator.y);
        assertEquals(201, insert.indicator.x);
    }

    @Test
    public void gridBelowLastRowAppends()
    {
        assertEquals(5, DropTargetFinder.gridInsertPoint(GRID, new Point(150, 300)).index);
    }
}

