package com.mylosis.roster.storage;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountData;
import com.mylosis.roster.model.AccountMetadata;
import com.mylosis.roster.model.AccountType;
import com.mylosis.roster.model.ImportDuplicateMode;
import com.mylosis.roster.model.ProfileGroup;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.Toolkit;
import java.awt.datatransfer.Clipboard;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.awt.datatransfer.Transferable;
import java.util.ArrayList;
import java.util.Collections;

/**
 * Clipboard import and export of the roster as pretty-printed JSON.
 */
@Slf4j
@Singleton
public class ImportExportService
{
    /**
     * Upper bound on accepted import JSON. Anything this size is not a roster
     * (2 MB is thousands of accounts); without the cap, an oversized clipboard
     * blob gets parsed, stored, and pushed through ConfigManager's cloud sync
     * on every subsequent save.
     */
    private static final int MAX_IMPORT_CHARS = 2_000_000;

    private final AccountStorage accountStorage;
    private final Gson gson;

    @Inject
    public ImportExportService(AccountStorage accountStorage, Gson gson)
    {
        this.accountStorage = accountStorage;
        this.gson = gson.newBuilder()
            .setPrettyPrinting()
            .create();
    }

    /** Copies the whole roster to the clipboard. */
    public ExportResult exportToClipboard()
    {
        AccountData data = accountStorage.exportSnapshot();
        return export(data, data.getAccounts().size(), data.getGroups().size());
    }

    /**
     * Copies one account to the clipboard, wrapped in the same envelope as a
     * full export so either can be imported the same way.
     */
    public ExportResult exportAccountToClipboard(Account account)
    {
        AccountData wrapper = AccountData.builder()
            .version(AccountData.CURRENT_VERSION)
            .accounts(Collections.singletonList(account))
            .groups(new ArrayList<>())
            .build();
        return export(wrapper, 1, 0);
    }

    private ExportResult export(AccountData data, int accountCount, int groupCount)
    {
        try
        {
            copyToClipboard(gson.toJson(data));
            log.debug("Exported {} accounts and {} categories to clipboard", accountCount, groupCount);
            return ExportResult.success(accountCount, groupCount);
        }
        catch (Exception e)
        {
            log.error("Failed to export to clipboard", e);
            return ExportResult.failure("Failed to copy to clipboard: " + e.getMessage());
        }
    }

    /** Puts plain text on the system clipboard. */
    public void copyToClipboard(String text)
    {
        Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
    }

    public ImportResult importFromClipboard(ImportDuplicateMode duplicateMode)
    {
        try
        {
            Clipboard clipboard = Toolkit.getDefaultToolkit().getSystemClipboard();
            Transferable contents = clipboard.getContents(null);
            if (contents == null || !contents.isDataFlavorSupported(DataFlavor.stringFlavor))
            {
                return ImportResult.failure("Clipboard doesn't contain text");
            }

            String json = (String) contents.getTransferData(DataFlavor.stringFlavor);
            if (json == null || json.trim().isEmpty())
            {
                return ImportResult.failure("Clipboard is empty");
            }
            if (json.length() > MAX_IMPORT_CHARS)
            {
                return ImportResult.failure("Clipboard data too large to be account data");
            }

            return importFromJson(json, duplicateMode);
        }
        catch (JsonSyntaxException e)
        {
            log.warn("Invalid JSON format in clipboard", e);
            return ImportResult.failure("Clipboard doesn't contain valid account data");
        }
        catch (Exception e)
        {
            log.error("Failed to import from clipboard", e);
            return ImportResult.failure("Failed to read clipboard: " + e.getMessage());
        }
    }

    private ImportResult importFromJson(String json, ImportDuplicateMode duplicateMode)
    {
        AccountData importData = gson.fromJson(json, AccountData.class);
        if (importData == null)
        {
            return ImportResult.failure("Invalid data format");
        }

        // Detect single-account JSON (backwards compat with pre-1.1 single exports)
        if (importData.getAccounts() == null && importData.getGroups() == null)
        {
            Account singleAccount = gson.fromJson(json, Account.class);
            if (singleAccount == null || singleAccount.getId() == null || singleAccount.getUsername() == null)
            {
                return ImportResult.failure("Invalid data format");
            }
            importData = AccountData.builder()
                .version(AccountData.CURRENT_VERSION)
                .accounts(new ArrayList<>(Collections.singletonList(singleAccount)))
                .groups(new ArrayList<>())
                .build();
            log.debug("Detected single-account import, wrapped in AccountData");
        }

        String validationError = validateImportData(importData);
        if (validationError != null)
        {
            return ImportResult.failure(validationError);
        }

        normalizeImportData(importData);

        ImportStats stats = accountStorage.importData(importData, duplicateMode);
        log.debug("Imported accounts: {}", stats);
        return ImportResult.success(stats);
    }

    /**
     * Foreign JSON can carry {@code metadata: null} or an unrecognized
     * {@code accountType} (Gson maps unknown enum constants to null). Backfill
     * defaults so downstream UI code never NPEs on imported accounts.
     * Static (stateless) so tests can exercise it without a ConfigManager.
     */
    static void normalizeImportData(AccountData data)
    {
        if (data.getAccounts() == null)
        {
            return;
        }
        for (Account profile : data.getAccounts())
        {
            if (profile.getMetadata() == null)
            {
                profile.setMetadata(AccountMetadata.createDefault());
            }
            else if (profile.getMetadata().getAccountType() == null)
            {
                profile.getMetadata().setAccountType(AccountType.MAIN);
            }
        }
    }

    /** Returns a user-facing error, or null if the data is importable.
     *  Static (stateless) so tests can exercise it without a ConfigManager. */
    static String validateImportData(AccountData data)
    {
        if (data.getVersion() > AccountData.CURRENT_VERSION)
        {
            return "File version " + data.getVersion() + " is newer than supported version " + AccountData.CURRENT_VERSION;
        }

        if (data.getAccounts() != null)
        {
            for (Account profile : data.getAccounts())
            {
                if (profile == null)
                {
                    return "Account entry is empty";
                }
                if (profile.getId() == null || profile.getId().isEmpty())
                {
                    return "Account missing required ID field";
                }
                if (profile.getUsername() == null || profile.getUsername().isEmpty())
                {
                    return "Account '" + profile.getAlias() + "' missing username";
                }
            }
        }

        if (data.getGroups() != null)
        {
            for (ProfileGroup group : data.getGroups())
            {
                if (group == null)
                {
                    return "Category entry is empty";
                }
                if (group.getId() == null || group.getId().isEmpty())
                {
                    return "Group missing required ID field";
                }
            }
        }

        return null;
    }
}

package com.mylosis.roster.storage;

import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountData;
import com.mylosis.roster.model.ImportDuplicateMode;
import com.mylosis.roster.model.ProfileGroup;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

/**
 * Merges imported data into existing data, with duplicate detection and
 * resolution. Duplicate lookups are served from indexes built once per merge
 * and maintained as accounts are added, so large imports stay linear.
 *
 * <p>Imported categories and accounts are appended after the existing ones
 * (keeping their relative order from the export) instead of keeping their
 * exported {@code sortOrder}, which would interleave them with existing
 * entries that happen to share the same numbers.
 *
 * <p>Single use: create a fresh instance for each merge.
 */
public class AccountDataMerger
{
    /** id -> existing account. */
    private final Map<String, Account> byId = new HashMap<>();
    /** lowercase {@code username + '\0' + alias} -> existing account. */
    private final Map<String, Account> byUsernameAlias = new HashMap<>();
    /** lowercase aliases currently in use. */
    private final Set<String> aliases = new HashSet<>();
    /** existing account -> its index in the accounts list, for in-place updates. */
    private final Map<Account, Integer> positions = new IdentityHashMap<>();
    /** effective category id (null key = Uncategorized) -> next free sortOrder. */
    private final Map<String, Integer> nextSortOrder = new HashMap<>();

    private int accountsAdded;
    private int accountsSkipped;
    private int accountsUpdated;
    private int groupsAdded;
    private int groupsSkipped;

    /**
     * Merge imported data into existing data with duplicate handling.
     * Returns import statistics.
     */
    public ImportStats merge(AccountData existing, AccountData importData, ImportDuplicateMode duplicateMode)
    {
        // Categories first: whether an imported account lands in a category or
        // in Uncategorized depends on that category existing after the merge.
        if (importData.getGroups() != null)
        {
            mergeGroups(existing, importData.getGroups());
        }
        if (importData.getAccounts() != null)
        {
            buildIndexes(existing);
            mergeAccounts(existing, importData.getAccounts(), duplicateMode);
        }
        return new ImportStats(accountsAdded, accountsSkipped, accountsUpdated, groupsAdded, groupsSkipped);
    }

    private void mergeGroups(AccountData existing, List<ProfileGroup> imported)
    {
        List<ProfileGroup> ordered = new ArrayList<>(imported);
        ordered.sort(Comparator.comparingInt(ProfileGroup::getSortOrder));
        int next = existing.nextGroupSortOrder();
        for (ProfileGroup group : ordered)
        {
            if (existing.findGroupById(group.getId()) == null)
            {
                group.setSortOrder(next++);
                existing.addGroup(group);
                groupsAdded++;
            }
            else
            {
                groupsSkipped++;
            }
        }
    }

    private void buildIndexes(AccountData existing)
    {
        List<Account> accounts = existing.getAccounts();
        for (int i = 0; i < accounts.size(); i++)
        {
            Account account = accounts.get(i);
            indexAccount(account);
            positions.put(account, i);
            String group = existing.effectiveGroupId(account);
            int order = account.getMetadata() != null ? account.getMetadata().getSortOrder() : 0;
            nextSortOrder.merge(group, order + 1, Math::max);
        }
    }

    private void indexAccount(Account p)
    {
        if (p.getId() != null)
        {
            byId.put(p.getId(), p);
        }
        String pairKey = usernameAliasKey(p);
        if (pairKey != null)
        {
            byUsernameAlias.put(pairKey, p);
        }
        if (p.getAlias() != null)
        {
            aliases.add(p.getAlias().toLowerCase(Locale.ROOT));
        }
    }

    private void unindexAccount(Account p)
    {
        if (p.getId() != null)
        {
            byId.remove(p.getId(), p);
        }
        String pairKey = usernameAliasKey(p);
        if (pairKey != null)
        {
            byUsernameAlias.remove(pairKey, p);
        }
        // Aliases are not removed: another account may share the alias, and
        // keeping it only makes suffix generation more conservative.
    }

    private static String usernameAliasKey(Account p)
    {
        if (p.getUsername() == null)
        {
            return null;
        }
        String alias = p.getAlias() != null ? p.getAlias() : "";
        return p.getUsername().toLowerCase(Locale.ROOT) + '\0' + alias.toLowerCase(Locale.ROOT);
    }

    private void mergeAccounts(AccountData existing, List<Account> imported, ImportDuplicateMode mode)
    {
        List<Account> ordered = new ArrayList<>(imported);
        ordered.sort(AccountData.SORT_ORDER_COMPARATOR);
        for (Account profile : ordered)
        {
            Account duplicate = findDuplicate(profile);
            if (duplicate == null)
            {
                append(existing, profile);
                accountsAdded++;
            }
            else
            {
                handleDuplicate(existing, profile, duplicate, mode);
            }
        }
    }

    private void handleDuplicate(AccountData existing, Account profile, Account duplicate, ImportDuplicateMode mode)
    {
        switch (mode)
        {
            case ADD_WITH_SUFFIX:
                profile.setAlias(generateUniqueAlias(profile.getAlias()));
                profile.setId(UUID.randomUUID().toString());
                append(existing, profile);
                accountsAdded++;
                break;

            case UPDATE:
                replace(existing, duplicate, profile);
                accountsUpdated++;
                break;

            case SKIP:
            default:
                accountsSkipped++;
                break;
        }
    }

    /** Adds {@code profile} at the end of the category it will be shown in. */
    private void append(AccountData existing, Account profile)
    {
        String group = existing.effectiveGroupId(profile);
        int order = nextSortOrder.getOrDefault(group, 0);
        profile.ensureMetadata().setSortOrder(order);
        nextSortOrder.put(group, order + 1);
        existing.addAccount(profile);
        positions.put(profile, existing.getAccounts().size() - 1);
        indexAccount(profile);
    }

    /**
     * Swaps {@code profile} into {@code duplicate}'s list slot and id. It keeps
     * the duplicate's position when it stays in the same category, and is
     * appended to its new category otherwise.
     */
    private void replace(AccountData existing, Account duplicate, Account profile)
    {
        int index = positions.remove(duplicate);
        unindexAccount(duplicate);
        profile.setId(duplicate.getId());

        String oldGroup = existing.effectiveGroupId(duplicate);
        String newGroup = existing.effectiveGroupId(profile);
        boolean sameGroup = oldGroup == null ? newGroup == null : oldGroup.equals(newGroup);
        if (sameGroup && duplicate.getMetadata() != null)
        {
            profile.ensureMetadata().setSortOrder(duplicate.getMetadata().getSortOrder());
        }
        else
        {
            int order = nextSortOrder.getOrDefault(newGroup, 0);
            profile.ensureMetadata().setSortOrder(order);
            nextSortOrder.put(newGroup, order + 1);
        }

        existing.replaceAccount(index, profile);
        positions.put(profile, index);
        indexAccount(profile);
    }

    private Account findDuplicate(Account importAccount)
    {
        // Match by ID first (exact same entry)
        if (importAccount.getId() != null)
        {
            Account byIdMatch = byId.get(importAccount.getId());
            if (byIdMatch != null)
            {
                return byIdMatch;
            }
        }

        // Match by username AND alias: same login with a different alias is intentional
        String pairKey = usernameAliasKey(importAccount);
        return pairKey != null ? byUsernameAlias.get(pairKey) : null;
    }

    private String generateUniqueAlias(String baseAlias)
    {
        if (baseAlias == null || baseAlias.isEmpty()) baseAlias = "Account";

        String alias = baseAlias;
        int suffix = 2;

        while (aliases.contains(alias.toLowerCase(Locale.ROOT)))
        {
            alias = baseAlias + " (" + suffix + ")";
            suffix++;
        }
        return alias;
    }
}

package com.mylosis.roster.storage;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Value;

/**
 * Result of an account import: either the merge statistics or a user-facing error.
 */
@Value
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public class ImportResult
{
    boolean success;
    /** User-facing failure reason; null on success. */
    String error;
    /** Merge statistics; null on failure. */
    ImportStats stats;

    public static ImportResult success(ImportStats stats)
    {
        return new ImportResult(true, null, stats);
    }

    public static ImportResult failure(String error)
    {
        return new ImportResult(false, error, null);
    }

    public boolean hasChanges()
    {
        return stats != null
            && (stats.getAccountsAdded() > 0 || stats.getAccountsUpdated() > 0 || stats.getGroupsAdded() > 0);
    }

    public String getDetailedMessage()
    {
        if (!success) return error;

        StringBuilder sb = new StringBuilder();
        appendPart(sb, stats.getAccountsAdded(), "Added " + stats.getAccountsAdded());
        appendPart(sb, stats.getAccountsUpdated(), "updated " + stats.getAccountsUpdated());
        int skipped = stats.getAccountsSkipped();
        appendPart(sb, skipped, "skipped " + skipped + " duplicate" + (skipped == 1 ? "" : "s"));
        int groups = stats.getGroupsAdded();
        appendPart(sb, groups, groups + (groups == 1 ? " category" : " categories"));

        return sb.length() == 0 ? "All accounts already exist" : sb.toString();
    }

    private static void appendPart(StringBuilder sb, int count, String text)
    {
        if (count <= 0) return;
        if (sb.length() > 0) sb.append(", ");
        sb.append(text);
    }
}

package com.mylosis.roster.storage;

import com.google.gson.Gson;
import com.mylosis.roster.model.AccountData;
import lombok.extern.slf4j.Slf4j;

import java.io.BufferedReader;
import java.io.File;
import java.io.IOException;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

/**
 * The on-disk JSON mirror of the roster: {@code roster.json} plus a rotating
 * {@code roster.backup.json}, both in the RuneLite directory.
 *
 * <p>Every save lands here as well as in ConfigManager, so the file is a
 * permanent second copy that {@link AccountStorage#load()} can re-seed from
 * when ConfigManager comes back empty (e.g. the client was killed before
 * ConfigManager's debounced flush reached disk).
 *
 * <p>Writes are coalesced on RuneLite's shared scheduled executor: a burst of
 * saves (a drag renumbering a whole category) produces one disk write at the
 * tail of the burst. The JSON is serialized by the caller before it gets here,
 * so the writer never walks the live object graph.
 */
@Slf4j
class RosterFileMirror
{
    private static final String DATA_FILE_NAME = "roster.json";
    private static final String BACKUP_FILE_NAME = "roster.backup.json";
    /** Recovery source written by v1.1.0's non-idempotent migration. */
    private static final String LEGACY_FILE_NAME = "roster.json.pre-v1.1.bak";
    private static final long COALESCE_MS = 250;

    private final Gson gson;
    private final ScheduledExecutorService executor;
    private final File dataFile;
    private final File backupFile;
    private final File legacyFile;

    /** The JSON the next flush will write, or null when nothing is pending. */
    private final AtomicReference<String> pendingJson = new AtomicReference<>();
    private final AtomicReference<ScheduledFuture<?>> pendingFlush = new AtomicReference<>();
    /**
     * Serializes flushes. The pending JSON is claimed inside this lock, so when
     * the timer flush and a shutdown flush race, the later writer always holds
     * the newer snapshot and the two never share the temp file.
     */
    private final Object writeLock = new Object();

    RosterFileMirror(Gson gson, File directory, ScheduledExecutorService executor)
    {
        this.gson = gson;
        this.executor = executor;
        this.dataFile = new File(directory, DATA_FILE_NAME);
        this.backupFile = new File(directory, BACKUP_FILE_NAME);
        this.legacyFile = new File(directory, LEGACY_FILE_NAME);
    }

    /**
     * Returns the first candidate file that parses, newest first:
     * {@code roster.json}, then {@code roster.backup.json}, then the legacy
     * v1.1.0 migration file. Null when none is readable.
     */
    AccountData readNewest()
    {
        for (File file : new File[]{dataFile, backupFile, legacyFile})
        {
            if (!file.exists())
            {
                continue;
            }
            AccountData data = read(file);
            if (data != null)
            {
                if (file != dataFile)
                {
                    log.warn("roster.json missing or unreadable; recovered from {}", file.getName());
                }
                return data;
            }
        }
        return null;
    }

    private AccountData read(File file)
    {
        try (BufferedReader reader = Files.newBufferedReader(file.toPath(), StandardCharsets.UTF_8))
        {
            AccountData data = gson.fromJson(reader, AccountData.class);
            if (data != null)
            {
                log.debug("Loaded {} accounts from {}",
                    data.getAccounts() != null ? data.getAccounts().size() : 0, file.getName());
            }
            return data;
        }
        catch (Exception e)
        {
            log.error("Failed to read {}", file.getName(), e);
            preserveCorruptFile(file);
            return null;
        }
    }

    /**
     * A file that exists but won't parse may still be the user's last good
     * backup. Set it aside before the normal save path rotates it over
     * {@code roster.backup.json}; without this, two saves after a bad load
     * every recovery source is gone.
     */
    private static void preserveCorruptFile(File file)
    {
        try
        {
            Path quarantine = file.toPath().resolveSibling(file.getName() + ".corrupt");
            Files.copy(file.toPath(), quarantine, StandardCopyOption.REPLACE_EXISTING);
            log.warn("Preserved unparseable {} as {}", file.getName(), quarantine.getFileName());
        }
        catch (Exception e)
        {
            log.warn("Could not preserve corrupt file {}", file.getName(), e);
        }
    }

    /** Queues {@code json} for writing; a newer call before the delay replaces it. */
    void scheduleWrite(String json)
    {
        pendingJson.set(json);
        ScheduledFuture<?> previous = pendingFlush.getAndSet(
            executor.schedule(this::flushPending, COALESCE_MS, TimeUnit.MILLISECONDS));
        if (previous != null)
        {
            previous.cancel(false);
        }
    }

    /** Writes any pending JSON now, on the calling thread. */
    void flushNow()
    {
        ScheduledFuture<?> scheduled = pendingFlush.getAndSet(null);
        if (scheduled != null)
        {
            scheduled.cancel(false);
        }
        flushPending();
    }

    private void flushPending()
    {
        synchronized (writeLock)
        {
            String json = pendingJson.getAndSet(null);
            if (json == null)
            {
                return;
            }
            try
            {
                write(json);
            }
            catch (Exception e)
            {
                // Exceptions inside a ScheduledFuture are swallowed unless
                // someone calls get(); log them or the mirror fails invisibly.
                // The next save retries naturally.
                log.error("Failed to write {}", dataFile.getAbsolutePath(), e);
            }
        }
    }

    private void write(String json) throws IOException
    {
        if (dataFile.exists())
        {
            Files.copy(dataFile.toPath(), backupFile.toPath(), StandardCopyOption.REPLACE_EXISTING);
        }

        // Write a temp file, then move it over the real one, so a failure
        // mid-write can never leave a torn roster.json behind.
        Path target = dataFile.toPath();
        Path tmp = target.resolveSibling(DATA_FILE_NAME + ".tmp");
        try (Writer writer = Files.newBufferedWriter(tmp, StandardCharsets.UTF_8))
        {
            writer.write(json);
        }
        try
        {
            Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
        }
        catch (AtomicMoveNotSupportedException e)
        {
            Files.move(tmp, target, StandardCopyOption.REPLACE_EXISTING);
        }
    }
}

