package com.mylosis.roster.storage;

import com.google.gson.Gson;
import com.mylosis.roster.RosterConfig;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountData;
import com.mylosis.roster.model.ImportDuplicateMode;
import com.mylosis.roster.model.ProfileGroup;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * Two-layer persistence for {@link AccountData}.
 *
 * <ul>
 *   <li><b>Primary:</b> RuneLite {@link ConfigManager} under group {@code roster}, key {@code data}.
 *       Cloud-syncs with the user's RuneLite account when sync is enabled on the active profile.</li>
 *   <li><b>Backup:</b> {@link RosterFileMirror}, written on every {@link #save()}. When
 *       ConfigManager comes back empty, {@link #load()} re-seeds it from the newest readable file.
 *       The files are never renamed away, so that recovery stays available.</li>
 * </ul>
 *
 * <p>Confined to the Swing EDT: every reader and writer is UI code, and
 * {@link com.mylosis.roster.RosterPlugin} marshals game and config events onto
 * the EDT before touching it.
 */
@Slf4j
@Singleton
public class AccountStorage
{
    /** Visible so {@link com.mylosis.roster.RosterPlugin#onConfigChanged} can tell our own
     *  data writes apart from external ones (profile switches, synced config). */
    public static final String CONFIG_KEY_DATA = "data";

    private final Gson gson;
    private final Supplier<String> configReader;
    private final Consumer<String> configWriter;
    private final RosterFileMirror fileMirror;

    private AccountData cachedData;

    /** Sorted-by-sortOrder view of the groups, rebuilt lazily after a mutation. */
    private List<ProfileGroup> sortedGroupsCache;

    /**
     * The JSON most recently written to ConfigManager. A {@code data} change
     * carrying any other value came from outside this class (RuneLite switched
     * profile or loaded a synced copy), so the cache no longer matches it.
     */
    private volatile String lastWrittenJson;

    @Inject
    public AccountStorage(Gson gson, ConfigManager configManager, ScheduledExecutorService executor)
    {
        // The executor is RuneLite's shared scheduler, never ours to stop. This
        // class is a Guice singleton and RuneLite re-enables plugins on the
        // same instance, so saves keep working after a plugin toggle.
        this(gson,
            () -> configManager.getConfiguration(RosterConfig.CONFIG_GROUP, CONFIG_KEY_DATA),
            json -> configManager.setConfiguration(RosterConfig.CONFIG_GROUP, CONFIG_KEY_DATA, json),
            new RosterFileMirror(gson, RuneLite.RUNELITE_DIR, executor));
    }

    AccountStorage(Gson gson, Supplier<String> configReader, Consumer<String> configWriter, RosterFileMirror fileMirror)
    {
        this.gson = gson;
        this.configReader = configReader;
        this.configWriter = configWriter;
        this.fileMirror = fileMirror;
    }

    public AccountData load()
    {
        if (cachedData != null)
        {
            return cachedData;
        }

        AccountData fromConfig = loadFromConfigManager();
        if (fromConfig != null)
        {
            cachedData = fromConfig.normalize();
            log.info("Loaded {} accounts and {} groups from ConfigManager",
                cachedData.getAccounts().size(), cachedData.getGroups().size());
            return cachedData;
        }

        AccountData fromFile = fileMirror.readNewest();
        if (fromFile != null)
        {
            cachedData = fromFile.normalize();
            log.info("Re-seeding ConfigManager with {} accounts from the file backup", cachedData.getAccounts().size());
            writeToConfigManager(gson.toJson(cachedData));
            return cachedData;
        }

        cachedData = AccountData.createEmpty();
        log.info("No existing Roster data; starting fresh");
        return cachedData;
    }

    /**
     * Reads the primary copy from ConfigManager; null if absent or unreadable.
     *
     * <p>Stored as an explicit JSON string: ConfigManager's typed accessors only
     * round-trip {@code @ConfigSerializer} types. Values that fail to parse (the
     * pre-v1.1.3 toString() format) fall through to the file recovery path, and
     * the next save writes proper JSON.
     */
    private AccountData loadFromConfigManager()
    {
        try
        {
            String json = configReader.get();
            if (json == null || json.trim().isEmpty())
            {
                return null;
            }
            return gson.fromJson(json, AccountData.class);
        }
        catch (Exception e)
        {
            log.warn("Failed to read AccountData from ConfigManager (will try file backup)", e);
            return null;
        }
    }

    /** True when {@code value} is exactly what this class last wrote to ConfigManager. */
    public boolean isOwnWrite(String value)
    {
        String last = lastWrittenJson;
        return value != null && (value == last || value.equals(last));
    }

    /**
     * Reloads from ConfigManager if its {@code data} value differs from what
     * this class last wrote, e.g. after RuneLite switched to another profile.
     * Without this the stale cache would be written over the new data on the
     * next save.
     *
     * @return true if the cache was replaced and the UI needs a rebuild
     */
    public boolean reloadIfChangedExternally()
    {
        if (cachedData == null || Objects.equals(configReader.get(), lastWrittenJson))
        {
            return false;
        }
        log.info("Roster data changed outside the plugin; reloading");
        // Finish the old copy's pending file write first, so the file backup
        // stays in step with what the cascade in load() might read back.
        fileMirror.flushNow();
        invalidateCache();
        load();
        return true;
    }

    public void save()
    {
        if (cachedData == null)
        {
            log.warn("save() called but cachedData is null");
            return;
        }

        // Any save is preceded by a mutation; drop derived caches.
        sortedGroupsCache = null;
        cachedData.invalidateIndexes();

        // One serialization feeds both layers. Doing it here, on the mutating
        // thread, keeps the snapshot consistent however late the file write runs.
        String json = gson.toJson(cachedData);
        writeToConfigManager(json);
        fileMirror.scheduleWrite(json);
    }

    private void writeToConfigManager(String json)
    {
        // Recorded before the write: ConfigManager posts ConfigChanged
        // synchronously, and the listener must recognize this value as ours.
        lastWrittenJson = json;
        try
        {
            configWriter.accept(json);
        }
        catch (Exception e)
        {
            log.error("Failed to save AccountData to ConfigManager", e);
        }
    }

    /**
     * Flushes the pending file write and drops the cache, so the next start
     * reloads from ConfigManager (which may have changed while disabled).
     */
    public void shutdown()
    {
        fileMirror.flushNow();
        invalidateCache();
    }

    private void invalidateCache()
    {
        cachedData = null;
        sortedGroupsCache = null;
    }

    // Account operations

    public List<Account> getAccounts()
    {
        return new ArrayList<>(load().getAccounts());
    }

    public Account getAccount(String id)
    {
        return load().findAccountById(id);
    }

    public void saveAccount(Account account)
    {
        load().upsertAccount(account);
        save();
    }

    /**
     * Updates several accounts with a single {@link #save()}, so a drag that
     * renumbers a whole category serializes the roster once, not once per account.
     */
    public void saveAccounts(Collection<Account> accounts)
    {
        if (accounts.isEmpty())
        {
            return;
        }
        AccountData data = load();
        for (Account account : accounts)
        {
            data.upsertAccount(account);
        }
        save();
    }

    /** The sortOrder that places an account last in {@code groupId} (null = Uncategorized). */
    public int nextAccountSortOrder(String groupId)
    {
        AccountData data = load();
        return data.nextAccountSortOrder(data.findGroupById(groupId) != null ? groupId : null);
    }

    public void deleteAccount(String id)
    {
        load().removeAccount(id);
        save();
    }

    // Group operations

    public List<ProfileGroup> getGroups()
    {
        List<ProfileGroup> cached = sortedGroupsCache;
        if (cached == null)
        {
            cached = new ArrayList<>(load().getGroups());
            cached.sort(Comparator.comparingInt(ProfileGroup::getSortOrder));
            sortedGroupsCache = cached;
        }
        return new ArrayList<>(cached);
    }

    public ProfileGroup getGroup(String id)
    {
        return load().findGroupById(id);
    }

    public void saveGroup(ProfileGroup group)
    {
        load().upsertGroup(group);
        save();
    }

    /** Updates several groups with a single {@link #save()}. */
    public void saveGroups(Collection<ProfileGroup> groups)
    {
        if (groups.isEmpty())
        {
            return;
        }
        AccountData data = load();
        for (ProfileGroup group : groups)
        {
            data.upsertGroup(group);
        }
        save();
    }

    public void deleteGroup(String id)
    {
        load().removeGroup(id);
        save();
    }

    /**
     * Clears accounts, categories, or both, with a single save. Clearing only
     * the categories moves every account to Uncategorized: each category's
     * accounts are appended in category order, keeping their order within it.
     */
    public void clear(boolean accounts, boolean groups)
    {
        AccountData data = load();
        if (accounts)
        {
            data.getAccounts().clear();
        }
        if (groups)
        {
            for (ProfileGroup group : getGroups())
            {
                data.removeGroup(group.getId());
            }
        }
        data.invalidateIndexes();
        save();
    }

    // Import / export

    /** The live data, for serialization by {@link ImportExportService} on the EDT. */
    AccountData exportSnapshot()
    {
        return load();
    }

    /** Merges {@code importData} into the roster and saves once. */
    ImportStats importData(AccountData importData, ImportDuplicateMode duplicateMode)
    {
        ImportStats stats = new AccountDataMerger().merge(load(), importData, duplicateMode);
        save();
        return stats;
    }
}

package com.mylosis.roster;

import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountMetadata;
import com.mylosis.roster.storage.AccountStorage;
import lombok.extern.slf4j.Slf4j;

import java.util.LinkedHashSet;
import java.util.Set;

/**
 * Links in-game logins to roster accounts: records which character is online,
 * learns each account's character name, and stamps {@code lastOnlineAt}.
 *
 * <p>{@link #setLoggedInName} and {@link #armSelectionLink} may be called from
 * the client thread; everything that touches {@link AccountStorage} is EDT only.
 */
@Slf4j
class LoginTracker
{
    /**
     * lastOnlineAt write throttle, per account. At 10 minutes, world hops within
     * a play session collapse to a single write. The card's "5m ago" label has
     * minute granularity anyway, so this is invisible to users.
     */
    static final long LAST_ONLINE_THROTTLE_MS = 10L * 60_000L;

    private final AccountStorage storage;

    private volatile String loggedInName;

    /**
     * One-shot link between a login-screen card selection and the next
     * completed login. Consumed (and cleared) by the first login that follows,
     * so a later, unrelated manual login is never mis-attributed to a stale
     * selection. Lets us learn the account's real character name even when it
     * matches neither alias nor login email.
     */
    private volatile String pendingLinkAccountId;

    LoginTracker(AccountStorage storage)
    {
        this.storage = storage;
    }

    /** The logged-in character's name, or null when logged out. */
    String getLoggedInName()
    {
        return loggedInName;
    }

    /** Records the current character (null on logout); returns the previous one. */
    String setLoggedInName(String name)
    {
        String previous = loggedInName;
        loggedInName = name;
        return previous;
    }

    void armSelectionLink(String accountId)
    {
        pendingLinkAccountId = accountId;
    }

    void reset()
    {
        loggedInName = null;
        pendingLinkAccountId = null;
    }

    /**
     * Handles a completed login (EDT only) and returns the ids of the accounts
     * whose cards need refreshing: the newly online one and the previously
     * online one, when they are in the roster.
     */
    Set<String> recordLogin(String characterName, String previousName)
    {
        Set<String> changed = new LinkedHashSet<>();
        if (previousName != null && !previousName.equalsIgnoreCase(characterName))
        {
            addIfPresent(changed, findAccountIdByName(previousName));
        }
        addIfPresent(changed, stampLastOnline(characterName));
        return changed;
    }

    /**
     * Returns the roster account matching an in-game character name: an exact
     * {@code characterName} match wins, else the first display-name match
     * (alias if set, otherwise login name). Case-insensitive. EDT only.
     */
    Account findAccountByName(String name)
    {
        if (name == null) return null;
        Account displayMatch = null;
        for (Account a : storage.getAccounts())
        {
            if (name.equalsIgnoreCase(a.getCharacterName()))
            {
                return a;
            }
            if (displayMatch == null && name.equalsIgnoreCase(a.getDisplayName()))
            {
                displayMatch = a;
            }
        }
        return displayMatch;
    }

    String findAccountIdByName(String name)
    {
        Account a = findAccountByName(name);
        return a != null ? a.getId() : null;
    }

    /**
     * Records that {@code characterName} was just seen logged in: stamps
     * {@code lastOnlineAt} (throttled) and learns the account's
     * {@code characterName}. The account is resolved by name, then by the
     * one-shot selection link, which is consumed here unconditionally.
     *
     * @return the matched account's id, or null if this character isn't in the roster
     */
    private String stampLastOnline(String characterName)
    {
        Account matched = findAccountByName(characterName);
        String pendingLink = pendingLinkAccountId;
        pendingLinkAccountId = null;
        if (matched == null && pendingLink != null)
        {
            matched = storage.getAccount(pendingLink);
            if (matched != null)
            {
                log.debug("Linked login to selected account {}", matched.getId());
            }
        }
        if (matched == null)
        {
            return null;
        }

        boolean dirty = false;
        if (!characterName.equalsIgnoreCase(matched.getCharacterName()))
        {
            matched.setCharacterName(characterName);
            dirty = true;
        }
        AccountMetadata meta = matched.ensureMetadata();
        long now = System.currentTimeMillis();
        Long previous = meta.getLastOnlineAt();
        if (previous == null || (now - previous) >= LAST_ONLINE_THROTTLE_MS)
        {
            meta.setLastOnlineAt(now);
            dirty = true;
        }
        if (dirty)
        {
            storage.saveAccount(matched);
        }
        return matched.getId();
    }

    private static void addIfPresent(Set<String> ids, String id)
    {
        if (id != null)
        {
            ids.add(id);
        }
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterConfig;
import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.storage.AccountStorage;
import com.mylosis.roster.storage.ExportResult;
import com.mylosis.roster.storage.ImportResult;
import com.mylosis.roster.ui.components.IconButton;
import com.mylosis.roster.ui.components.Icons;
import com.mylosis.roster.ui.components.NotificationToast;
import com.mylosis.roster.ui.components.Theme;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.function.BiConsumer;

/**
 * Builds the footer of the Roster panel: account count, view toggle,
 * import/export menu, and the clear menu.
 */
@Slf4j
class PanelFooterBuilder
{
    /** What a "Clear" menu entry removes. */
    @RequiredArgsConstructor
    private enum ClearScope
    {
        ACCOUNTS("Clear All Accounts", true, false),
        CATEGORIES("Clear All Categories", false, true),
        EVERYTHING("Clear Everything", true, true);

        private final String label;
        private final boolean accounts;
        private final boolean categories;
    }

    private final RosterPlugin plugin;
    private final AccountStorage storage;
    private final JComponent dialogParent;
    private final BiConsumer<String, NotificationToast.Type> showNotification;
    private final Runnable onRebuild;

    private IconButton viewToggleButton;

    PanelFooterBuilder(RosterPlugin plugin, JComponent dialogParent,
                       BiConsumer<String, NotificationToast.Type> showNotification, Runnable onRebuild)
    {
        this.plugin = plugin;
        this.storage = plugin.getAccountStorage();
        this.dialogParent = dialogParent;
        this.showNotification = showNotification;
        this.onRebuild = onRebuild;
    }

    JPanel build(JLabel accountCountLabel)
    {
        JPanel footer = new JPanel(new BorderLayout(Theme.SPACING_SM, Theme.SPACING_SM));
        footer.setBackground(Theme.BACKGROUND);
        footer.setBorder(new EmptyBorder(Theme.SPACING_LG, 0, 0, 0));
        footer.add(accountCountLabel, BorderLayout.WEST);

        viewToggleButton = new IconButton(Icons.GRID, null);
        viewToggleButton.addActionListener(e -> plugin.getConfigManager().setConfiguration(
            RosterConfig.CONFIG_GROUP, "gridView", !plugin.getConfig().gridView()));
        refresh();

        JPanel rightPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT, Theme.SPACING_XS, 0));
        rightPanel.setOpaque(false);
        rightPanel.add(viewToggleButton);
        rightPanel.add(createImportExportButton());
        rightPanel.add(createClearButton());
        footer.add(rightPanel, BorderLayout.EAST);
        return footer;
    }

    /**
     * Syncs the view toggle with the config. Called on every rebuild, which
     * also covers the setting being changed from RuneLite's config panel.
     */
    void refresh()
    {
        boolean grid = plugin.getConfig().gridView();
        viewToggleButton.updateIcon(grid ? Icons.LIST : Icons.GRID);
        viewToggleButton.setToolTipText(grid ? "Switch to list view" : "Switch to grid view");
    }

    private IconButton createImportExportButton()
    {
        JPopupMenu menu = new JPopupMenu();
        addItem(menu, "Import from Clipboard", this::doImport);
        addItem(menu, "Export to Clipboard", this::doExport);
        return menuButton(Icons.CLIPBOARD, "Export/Import accounts", menu);
    }

    private IconButton createClearButton()
    {
        JPopupMenu menu = new JPopupMenu();
        addItem(menu, ClearScope.ACCOUNTS.label, () -> confirmClear(ClearScope.ACCOUNTS));
        addItem(menu, ClearScope.CATEGORIES.label, () -> confirmClear(ClearScope.CATEGORIES));
        menu.addSeparator();
        addItem(menu, ClearScope.EVERYTHING.label, () -> confirmClear(ClearScope.EVERYTHING))
            .setForeground(Theme.BUTTON_DANGER);
        return menuButton(Icons.DELETE, "Clear...", menu);
    }

    /** An icon button that opens {@code menu} above itself (the footer sits at the bottom). */
    private static IconButton menuButton(String icon, String tooltip, JPopupMenu menu)
    {
        IconButton button = new IconButton(icon, tooltip);
        button.addActionListener(e -> menu.show(button, 0, -menu.getPreferredSize().height));
        return button;
    }

    private static JMenuItem addItem(JPopupMenu menu, String label, Runnable action)
    {
        JMenuItem item = new JMenuItem(label);
        item.addActionListener(e -> action.run());
        menu.add(item);
        return item;
    }

    private void doExport()
    {
        ExportResult result = plugin.getImportExportService().exportToClipboard();
        if (result.isSuccess())
        {
            showNotification.accept("Copied " + result.getAccountCount() + " accounts, "
                + result.getGroupCount() + " categories", NotificationToast.Type.SUCCESS);
        }
        else
        {
            showNotification.accept("Copy failed: " + result.getError(), NotificationToast.Type.ERROR);
        }
    }

    private void doImport()
    {
        ImportResult result = plugin.getImportExportService().importFromClipboard(plugin.getConfig().importDuplicateMode());
        log.debug("Import result: {}", result);

        if (!result.isSuccess())
        {
            showNotification.accept("Import failed: " + result.getError(), NotificationToast.Type.ERROR);
            return;
        }
        showNotification.accept(result.getDetailedMessage(),
            result.hasChanges() ? NotificationToast.Type.SUCCESS : NotificationToast.Type.WARNING);
        if (result.hasChanges())
        {
            onRebuild.run();
        }
    }

    private void confirmClear(ClearScope scope)
    {
        int accountCount = storage.getAccounts().size();
        int groupCount = storage.getGroups().size();
        int affectedAccounts = scope.accounts ? accountCount : 0;
        int affectedGroups = scope.categories ? groupCount : 0;
        if (affectedAccounts == 0 && affectedGroups == 0)
        {
            showNotification.accept("Nothing to clear", NotificationToast.Type.INFO);
            return;
        }

        String message;
        switch (scope)
        {
            case ACCOUNTS:
                message = "Delete all " + accountCount + " accounts?\n\nThis cannot be undone.";
                break;
            case CATEGORIES:
                message = "Delete all " + groupCount + " categories?\nAccounts will be moved to Uncategorized.";
                break;
            case EVERYTHING:
            default:
                message = "Delete all " + accountCount + " accounts and " + groupCount
                    + " categories?\n\nThis cannot be undone.";
                break;
        }

        int result = JOptionPane.showConfirmDialog(SwingUtilities.getWindowAncestor(dialogParent),
            message, scope.label, JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
        if (result == JOptionPane.YES_OPTION)
        {
            storage.clear(scope.accounts, scope.categories);
            showNotification.accept("Cleared", NotificationToast.Type.SUCCESS);
            onRebuild.run();
        }
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountData;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.model.SortKey;
import com.mylosis.roster.storage.AccountStorage;
import com.mylosis.roster.ui.components.Icons;
import com.mylosis.roster.ui.components.Theme;
import com.mylosis.roster.ui.dnd.DragDropManager;
import com.mylosis.roster.ui.dnd.ListLayout;
import lombok.Value;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Builds the scrollable list: categories in order, then Uncategorized, with
 * search filtering, per-category sorting, and the empty states. Records the
 * drop zones it creates in a {@link ListLayout}.
 */
class AccountListBuilder
{
    /** Visible and total account counts for the footer label. */
    @Value
    static class Counts
    {
        int visible;
        int total;
    }

    private static final Comparator<Account> NAME_ASC =
        Comparator.comparing(Account::getDisplayName, Comparator.nullsLast(String.CASE_INSENSITIVE_ORDER));
    // Recent first; never-seen accounts sink to the bottom
    private static final Comparator<Account> LAST_ONLINE =
        Comparator.comparingLong((Account a) -> timestamp(a.getMetadata() != null ? a.getMetadata().getLastOnlineAt() : null)).reversed();
    // Newest first; accounts without createdAt (pre-v1.1) sink to the bottom
    private static final Comparator<Account> DATE_ADDED =
        Comparator.comparingLong((Account a) -> timestamp(a.getMetadata() != null ? a.getMetadata().getCreatedAt() : null)).reversed();

    private final RosterPlugin plugin;
    private final AccountStorage storage;
    private final RosterPanel panel;
    private final DragDropManager dragDropManager;

    AccountListBuilder(RosterPlugin plugin, RosterPanel panel, DragDropManager dragDropManager)
    {
        this.plugin = plugin;
        this.storage = plugin.getAccountStorage();
        this.panel = panel;
        this.dragDropManager = dragDropManager;
    }

    /**
     * Fills {@code target} with the list for the given (lowercase) search filter.
     */
    Counts build(JPanel target, String searchFilter, ListLayout layout)
    {
        boolean searching = !searchFilter.isEmpty();
        List<Account> all = storage.getAccounts();
        List<ProfileGroup> groups = storage.getGroups();
        Map<String, List<Account>> byGroup = new HashMap<>(groups.size() * 2);
        for (ProfileGroup group : groups)
        {
            byGroup.put(group.getId(), new ArrayList<>());
        }

        // Accounts whose category doesn't exist (deleted, or never imported)
        // are shown under Uncategorized.
        List<Account> uncategorized = new ArrayList<>();
        int visible = 0;
        for (Account account : all)
        {
            if (searching && !account.getSearchHaystack().contains(searchFilter))
            {
                continue;
            }
            visible++;
            byGroup.getOrDefault(account.getGroupId(), uncategorized).add(account);
        }

        Comparator<Account> order = comparatorFor(plugin.getConfig().sortKey());
        for (ProfileGroup group : groups)
        {
            List<Account> accounts = byGroup.get(group.getId());
            // While searching, categories without matches are hidden.
            if (searching && accounts.isEmpty())
            {
                continue;
            }
            accounts.sort(order);
            CategoryPanel category = new CategoryPanel(plugin, panel, group, accounts, dragDropManager);
            layout.addCategory(category, category.getCards());
            target.add(category);
            target.add(Box.createVerticalStrut(Theme.SPACING_LG));
        }

        uncategorized.sort(order);
        addUncategorized(target, uncategorized, !groups.isEmpty() && !(searching && uncategorized.isEmpty()), layout);

        if (visible == 0 && (searching || groups.isEmpty()))
        {
            target.add(createEmptyState(searching));
        }
        return new Counts(visible, all.size());
    }

    private void addUncategorized(JPanel target, List<Account> accounts, boolean showHeader, ListLayout layout)
    {
        if (showHeader)
        {
            JPanel header = createUncategorizedHeader();
            layout.addUncategorizedZone(header);
            target.add(header);
            target.add(Box.createVerticalStrut(Theme.SPACING_SM));
        }
        if (accounts.isEmpty())
        {
            return;
        }
        List<AccountCardPanel> cards = new ArrayList<>();
        JPanel container = CardListBuilder.build(plugin, panel, dragDropManager, accounts, null, null, cards);
        layout.addUncategorizedZone(container);
        layout.setUncategorizedCards(cards);
        target.add(container);
        target.add(Box.createVerticalStrut(Theme.SPACING_SM));
    }

    /**
     * MANUAL uses the stored drag order. Other keys sort a copy at render time
     * and never touch {@code sortOrder}, so switching back to MANUAL restores
     * the hand-arranged order.
     */
    private static Comparator<Account> comparatorFor(SortKey key)
    {
        switch (key)
        {
            case NAME_ASC:
                return NAME_ASC;
            case NAME_DESC:
                return NAME_ASC.reversed();
            case LAST_ONLINE:
                return LAST_ONLINE;
            case DATE_ADDED:
                return DATE_ADDED;
            case MANUAL:
            default:
                return AccountData.SORT_ORDER_COMPARATOR;
        }
    }

    private static long timestamp(Long millis)
    {
        return millis != null ? millis : Long.MIN_VALUE;
    }

    private static JPanel createEmptyState(boolean searching)
    {
        JPanel emptyState = new JPanel();
        emptyState.setLayout(new BoxLayout(emptyState, BoxLayout.Y_AXIS));
        emptyState.setBackground(Theme.BACKGROUND);
        emptyState.setBorder(new EmptyBorder(40, Theme.SPACING_LG, 40, Theme.SPACING_LG));

        JLabel iconLabel = new JLabel(Icons.get(Icons.USER, 48));
        iconLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        emptyState.add(iconLabel);
        emptyState.add(Box.createVerticalStrut(Theme.SPACING_LG));

        JLabel message = new JLabel(searching ? "No matching accounts" : "No accounts yet");
        message.setForeground(Theme.TEXT_SECONDARY);
        message.setFont(Theme.fontRegular(message.getFont(), Theme.FONT_SIZE_HEADING));
        message.setAlignmentX(Component.CENTER_ALIGNMENT);
        emptyState.add(message);

        if (!searching)
        {
            emptyState.add(Box.createVerticalStrut(Theme.SPACING_SM));
            JLabel hint = new JLabel("Click + to add your first account");
            hint.setForeground(Theme.TEXT_SECONDARY);
            hint.setFont(Theme.fontRegular(hint.getFont(), Theme.FONT_SIZE_BODY));
            hint.setAlignmentX(Component.CENTER_ALIGNMENT);
            emptyState.add(hint);
        }
        return emptyState;
    }

    private JPanel createUncategorizedHeader()
    {
        JPanel header = new JPanel(new BorderLayout(Theme.SPACING_MD, 0));
        header.setBackground(Theme.GROUP_HEADER);
        header.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 0, 1, 0, Theme.CARD_BORDER),
            new EmptyBorder(Theme.SPACING_SM, Theme.SPACING_MD, Theme.SPACING_SM, Theme.SPACING_MD)
        ));

        JLabel label = new JLabel("Uncategorized");
        label.setForeground(Theme.TEXT_SECONDARY);
        label.setFont(Theme.fontBold(label.getFont(), Theme.FONT_SIZE_BODY));
        header.add(label, BorderLayout.CENTER);

        header.add(CategoryPanel.createHeaderAddButton("Add account",
            () -> panel.getFormManager().toggleAddAccountForm(panel::collapseExpandedCard)), BorderLayout.EAST);
        return header;
    }
}

package com.mylosis.roster.ui.components;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;

/**
 * A temporary in-panel notification toast that fades in, then fades out and
 * removes itself.
 */
public class NotificationToast extends JPanel
{
    public enum Type { SUCCESS, ERROR, INFO, WARNING }

    private static final int MAX_WIDTH = 220;
    private static final int ICON_SIZE = 12;
    private static final int FRAME_MS = 16;
    private static final float FADE_STEP = 0.1f;

    private final Timer dismissTimer;
    private final Timer fadeTimer;
    private float opacity = 0f;
    private boolean fadingIn = true;

    public NotificationToast(String message, Type type, int durationMs)
    {
        setLayout(new BorderLayout());
        setOpaque(false);

        Color background = backgroundColor(type);
        JPanel inner = new JPanel(new BorderLayout(Theme.SPACING_SM, 0))
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, opacity));
                g2.setColor(background);
                g2.fillRoundRect(0, 0, getWidth(), getHeight(), Theme.BORDER_RADIUS_MD, Theme.BORDER_RADIUS_MD);
                g2.dispose();
                super.paintComponent(g);
            }
        };
        inner.setOpaque(false);
        inner.setBorder(new EmptyBorder(Theme.SPACING_MD, Theme.SPACING_MD, Theme.SPACING_MD, Theme.SPACING_MD));

        JLabel iconLabel = new JLabel(dotIcon(iconColor(type)));
        iconLabel.setHorizontalAlignment(SwingConstants.CENTER);

        // HTML for word wrapping; the message is escaped because it can carry
        // user-controlled text (account names).
        String htmlMessage = "<html><div style='width: " + (MAX_WIDTH - 50) + "px; text-align: center;'>"
            + SafeText.escapeHtml(message) + "</div></html>";
        JLabel messageLabel = new JLabel(htmlMessage)
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, opacity));
                super.paintComponent(g2);
                g2.dispose();
            }
        };
        messageLabel.setForeground(Theme.TEXT_PRIMARY);
        messageLabel.setFont(Theme.fontRegular(messageLabel.getFont(), Theme.FONT_SIZE_SMALL));
        messageLabel.setHorizontalAlignment(SwingConstants.CENTER);

        JPanel contentPanel = new JPanel();
        contentPanel.setLayout(new BoxLayout(contentPanel, BoxLayout.Y_AXIS));
        contentPanel.setOpaque(false);
        iconLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        messageLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        contentPanel.add(iconLabel);
        contentPanel.add(Box.createVerticalStrut(Theme.SPACING_XS));
        contentPanel.add(messageLabel);

        inner.add(contentPanel, BorderLayout.CENTER);
        add(inner, BorderLayout.CENTER);

        fadeTimer = new Timer(FRAME_MS, e -> stepFade());
        dismissTimer = new Timer(durationMs, e -> {
            fadingIn = false;
            fadeTimer.start();
        });
        dismissTimer.setRepeats(false);

        fadeTimer.start();
        dismissTimer.start();
    }

    private void stepFade()
    {
        if (fadingIn)
        {
            opacity = Math.min(1f, opacity + FADE_STEP);
            if (opacity >= 1f)
            {
                fadingIn = false;
                fadeTimer.stop();
            }
        }
        else
        {
            opacity = Math.max(0f, opacity - FADE_STEP);
            if (opacity <= 0f)
            {
                fadeTimer.stop();
                Container parent = getParent();
                if (parent != null)
                {
                    parent.remove(this);
                    parent.revalidate();
                    parent.repaint();
                }
            }
        }
        repaint();
    }

    /**
     * Hard-stops both timers. Called when the toast is replaced by a newer
     * one; otherwise the orphaned fade timer keeps repainting a parentless
     * component until it finishes.
     */
    public void stopTimers()
    {
        dismissTimer.stop();
        fadeTimer.stop();
    }

    private static Color backgroundColor(Type type)
    {
        switch (type)
        {
            case SUCCESS:
                return new Color(40, 120, 60, 230);
            case WARNING:
                return new Color(160, 130, 30, 230);
            case ERROR:
                return new Color(150, 50, 50, 230);
            case INFO:
            default:
                return new Color(60, 60, 60, 230);
        }
    }

    private static Color iconColor(Type type)
    {
        switch (type)
        {
            case SUCCESS:
                return new Color(100, 220, 120);
            case WARNING:
                return new Color(255, 210, 70);
            case ERROR:
                return new Color(255, 100, 100);
            case INFO:
            default:
                return Theme.TEXT_SECONDARY;
        }
    }

    /** A small colored dot that fades with the toast. */
    private Icon dotIcon(Color color)
    {
        return new Icon()
        {
            @Override
            public void paintIcon(Component c, Graphics g, int x, int y)
            {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, opacity));
                g2.setColor(color);
                g2.fillOval(x, y, ICON_SIZE, ICON_SIZE);
                g2.dispose();
            }

            @Override
            public int getIconWidth() { return ICON_SIZE; }

            @Override
            public int getIconHeight() { return ICON_SIZE; }
        };
    }
}

package com.mylosis.roster.ui.components;

import com.mylosis.roster.model.AccountType;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.ImageUtil;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;

/**
 * Small clickable badge representing an {@link AccountType}, rendered with
 * OSRS sprites:
 *
 * <ul>
 *   <li>The five Ironman variants (Ironman, HCIM, UIM, GIM, UGIM) use the
 *       official in-game chat badges.</li>
 *   <li>Main, Skiller, and Pure are not official in-game account types, so
 *       they use recognisable item/skill icons.</li>
 * </ul>
 *
 * Clicking opens a {@link JPopupMenu} listing all types with their matching
 * sprites. Selecting one invokes the supplied callback.
 *
 * Resources live under {@code /com/mylosis/roster/badges/}. EDT only.
 */
@Slf4j
public class AccountTypeBadge extends JComponent
{
    public static final int DEFAULT_SIZE = 20;

    private static final String RESOURCE_BASE = "/com/mylosis/roster/badges/";

    private static final Map<AccountType, String> RESOURCE = new EnumMap<>(AccountType.class);
    static
    {
        RESOURCE.put(AccountType.MAIN,                   "main.png");
        RESOURCE.put(AccountType.IRONMAN,                "ironman.png");
        RESOURCE.put(AccountType.HARDCORE_IRONMAN,       "hcim.png");
        RESOURCE.put(AccountType.ULTIMATE_IRONMAN,       "uim.png");
        RESOURCE.put(AccountType.GROUP_IRONMAN,          "gim.png");
        RESOURCE.put(AccountType.UNRANKED_GROUP_IRONMAN, "ugim.png");
        RESOURCE.put(AccountType.SKILLER,                "skiller.png");
        RESOURCE.put(AccountType.PURE,                   "pure.png");
    }

    /** Sentinel for "load failed", so a missing resource is not retried on every paint. */
    private static final BufferedImage MISSING = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);

    /** Source sprites, loaded once. */
    private static final Map<AccountType, BufferedImage> SOURCE_CACHE = new EnumMap<>(AccountType.class);
    /** Sprites pre-scaled per display size, so painting is a plain blit. */
    private static final Map<String, BufferedImage> SCALED_CACHE = new HashMap<>();

    private AccountType type;
    private final int size;
    private final Consumer<AccountType> onChange;

    public AccountTypeBadge(AccountType type, int size, Consumer<AccountType> onChange)
    {
        this.type = type != null ? type : AccountType.MAIN;
        this.size = size;
        this.onChange = onChange;

        Dimension dim = new Dimension(size, size);
        setPreferredSize(dim);
        setMaximumSize(dim);
        setMinimumSize(dim);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        updateTooltip();
        setOpaque(false);

        addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                if (e.getButton() == MouseEvent.BUTTON1)
                {
                    showPicker();
                    e.consume();
                }
            }
        });
    }

    private void setType(AccountType newType)
    {
        this.type = newType != null ? newType : AccountType.MAIN;
        updateTooltip();
        repaint();
    }

    private void updateTooltip()
    {
        setToolTipText(type.getDisplayName() + " (click to change)");
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        if (!drawSprite(g, type, 0, 0, size))
        {
            // Fallback if the resource failed to load: a dim grey dot, so the
            // click target is still visible.
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(new Color(110, 110, 110));
            g2.fillOval(0, 0, size - 1, size - 1);
            g2.dispose();
        }
    }

    /**
     * Draws the sprite centered in a {@code box x box} square at (x, y).
     * Scaled once per device-pixel size, so painting is a plain blit that
     * stays sharp on HiDPI displays. Returns false if the sprite is unavailable.
     */
    private static boolean drawSprite(Graphics g, AccountType t, int x, int y, int box)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        double scale = g2.getTransform().getScaleX();
        if (scale <= 0)
        {
            scale = 1;
        }
        BufferedImage icon = scaledIcon(t, (int) Math.round(box * scale));
        if (icon != null)
        {
            g2.translate(x + (box - icon.getWidth() / scale) / 2, y + (box - icon.getHeight() / scale) / 2);
            g2.scale(1 / scale, 1 / scale);
            g2.drawImage(icon, 0, 0, null);
        }
        g2.dispose();
        return icon != null;
    }

    private void showPicker()
    {
        if (onChange == null)
        {
            return;
        }
        JPopupMenu menu = new JPopupMenu();
        menu.setBackground(Theme.BACKGROUND_DARKER);
        menu.setBorder(BorderFactory.createLineBorder(Theme.CARD_BORDER, 1));
        for (AccountType t : AccountType.values())
        {
            menu.add(createMenuItem(t));
        }
        menu.show(this, 0, getHeight());
    }

    private JMenuItem createMenuItem(AccountType t)
    {
        JMenuItem item = new JMenuItem(t.getDisplayName());
        item.setIcon(swatchIcon(t, 14));
        item.setIconTextGap(8);
        item.setBackground(Theme.BACKGROUND_DARKER);
        boolean active = t == type;
        item.setForeground(active ? Theme.ACCENT_ORANGE : Theme.TEXT_PRIMARY);
        item.setFont(active
            ? Theme.fontBold(item.getFont(), Theme.FONT_SIZE_SMALL)
            : Theme.fontRegular(item.getFont(), Theme.FONT_SIZE_SMALL));
        item.setBorder(new EmptyBorder(Theme.SPACING_XS, Theme.SPACING_SM, Theme.SPACING_XS, Theme.SPACING_SM));
        item.addActionListener(e ->
        {
            setType(t);
            onChange.accept(t);
        });
        return item;
    }

    /**
     * Reusable icon matching the badge rendering. Used by the type dropdown
     * (InlineAccountForm) and the picker menu so both are self-describing.
     */
    public static Icon swatchIcon(AccountType t, int size)
    {
        return new Icon()
        {
            @Override
            public void paintIcon(Component c, Graphics g, int x, int y)
            {
                drawSprite(g, t, x, y, size);
            }

            @Override
            public int getIconWidth() { return size; }

            @Override
            public int getIconHeight() { return size; }
        };
    }

    /** The sprite scaled to fit a {@code box x box} square, preserving aspect ratio; null if unavailable. */
    private static BufferedImage scaledIcon(AccountType t, int box)
    {
        BufferedImage scaled = SCALED_CACHE.computeIfAbsent(t.name() + '@' + box, k -> {
            BufferedImage source = sourceIcon(t);
            return source != null ? scale(source, box) : MISSING;
        });
        return scaled == MISSING ? null : scaled;
    }

    private static BufferedImage sourceIcon(AccountType t)
    {
        BufferedImage cached = SOURCE_CACHE.get(t);
        if (cached != null)
        {
            return cached == MISSING ? null : cached;
        }
        String resource = RESOURCE.get(t);
        try
        {
            BufferedImage img = ImageUtil.loadImageResource(AccountTypeBadge.class, RESOURCE_BASE + resource);
            SOURCE_CACHE.put(t, img);
            return img;
        }
        catch (Exception e)
        {
            SOURCE_CACHE.put(t, MISSING);
            log.warn("Failed to load badge icon {}", resource, e);
            return null;
        }
    }

    private static BufferedImage scale(BufferedImage img, int box)
    {
        int iw = img.getWidth();
        int ih = img.getHeight();
        if (iw <= 0 || ih <= 0)
        {
            return MISSING;
        }
        double s = Math.min((double) box / iw, (double) box / ih);
        int w = Math.max(1, (int) Math.round(iw * s));
        int h = Math.max(1, (int) Math.round(ih * s));
        BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2 = out.createGraphics();
        g2.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
        g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
        g2.drawImage(img, 0, 0, w, h, null);
        g2.dispose();
        return out;
    }
}

package com.mylosis.roster.ui.components;

import lombok.EqualsAndHashCode;
import lombok.RequiredArgsConstructor;
import net.runelite.client.ui.ColorScheme;

import java.awt.Color;
import java.awt.Font;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Centralized theme constants for consistent UI styling throughout the plugin.
 */
public final class Theme
{
    private Theme() {} // Prevent instantiation

    /** Plugin version shown in the panel header. Must match {@code version} in build.gradle (a unit test checks). */
    public static final String VERSION = "1.1.4";

    // Base colors
    public static final Color BACKGROUND = ColorScheme.DARK_GRAY_COLOR;
    public static final Color BACKGROUND_DARKER = ColorScheme.DARKER_GRAY_COLOR;
    public static final Color BACKGROUND_HOVER = ColorScheme.DARK_GRAY_HOVER_COLOR;

    // Card colors
    public static final Color CARD_BACKGROUND = new Color(45, 45, 45);
    public static final Color CARD_HOVER = new Color(55, 55, 55);
    public static final Color CARD_SELECTED = new Color(65, 65, 65);
    public static final Color CARD_BORDER = ColorScheme.MEDIUM_GRAY_COLOR;

    // Group header colors
    public static final Color GROUP_HEADER = new Color(35, 35, 35);
    public static final Color GROUP_HEADER_HOVER = new Color(45, 45, 45);

    // Form colors (for inline editing)
    public static final Color FORM_BACKGROUND = new Color(38, 38, 38);

    // Text colors
    public static final Color TEXT_PRIMARY = Color.WHITE;
    public static final Color TEXT_SECONDARY = ColorScheme.LIGHT_GRAY_COLOR;
    public static final Color TEXT_MUTED = ColorScheme.MEDIUM_GRAY_COLOR;

    // Button colors
    public static final Color BUTTON_PRIMARY = new Color(50, 120, 65);
    public static final Color BUTTON_PRIMARY_HOVER = new Color(65, 145, 80);
    public static final Color BUTTON_SECONDARY = ColorScheme.DARKER_GRAY_COLOR;
    public static final Color BUTTON_SECONDARY_HOVER = ColorScheme.DARK_GRAY_HOVER_COLOR;
    public static final Color BUTTON_DANGER = new Color(220, 53, 69);

    // Accent colors
    public static final Color ACCENT_ORANGE = ColorScheme.BRAND_ORANGE;
    public static final Color ACCENT_BLUE = new Color(66, 135, 245);

    // Online indicator
    public static final Color ONLINE_INDICATOR = new Color(60, 180, 75);
    public static final int ONLINE_DOT_SIZE = 8;

    // Category color palette (preset options for user selection), names paired with colors
    public static final String[] CATEGORY_COLOR_NAMES = {
        "Red", "Orange", "Yellow", "Green", "Blue", "Purple", "Pink", "Teal"
    };
    public static final Color[] CATEGORY_COLORS = {
        new Color(220, 53, 69),   // Red
        new Color(255, 140, 0),   // Orange
        new Color(220, 180, 80),  // Yellow
        new Color(60, 180, 75),   // Green
        new Color(66, 135, 245),  // Blue
        new Color(130, 80, 200),  // Purple
        new Color(200, 80, 160),  // Pink
        new Color(0, 180, 180),   // Teal
    };

