    public static final Color[] DEFAULT_CATEGORY_COLORS = {
        new Color(66, 135, 245),  // 1. Blue
        new Color(130, 80, 200),  // 2. Purple
        new Color(60, 180, 75),   // 3. Green
        new Color(220, 180, 80),  // 4. Yellow
        new Color(140, 160, 180), // 5. Slate
        new Color(255, 140, 0),   // 6. Orange
        new Color(200, 80, 160),  // 7. Pink
        new Color(0, 180, 180),   // 8. Teal
        new Color(220, 53, 69),   // 9. Red
        new Color(180, 130, 80),  // 10. Bronze
    };

    public static final int CATEGORY_BORDER_WIDTH = 3;

    // Spacing constants
    public static final int SPACING_XS = 3;
    public static final int SPACING_SM = 6;
    public static final int SPACING_MD = 10;
    public static final int SPACING_LG = 14;

    // Corner radii used when painting rounded shapes
    public static final int BORDER_RADIUS_SM = 4;
    public static final int BORDER_RADIUS_MD = 6;

    // Component sizes
    public static final int BUTTON_HEIGHT = 32;
    public static final int BUTTON_HEIGHT_SM = 26;
    public static final int ICON_SIZE = 18;
    public static final int CARD_HEIGHT = 80;
    public static final int MENU_BUTTON_SIZE = 32;

    // Font sizes
    public static final float FONT_SIZE_TITLE = 20f;
    public static final float FONT_SIZE_HEADING = 16f;
    public static final float FONT_SIZE_BODY = 14f;
    public static final float FONT_SIZE_SMALL = 13f;
    public static final float FONT_SIZE_TINY = 12f;

    /**
     * Parses a hex color string (e.g. "#FF5733") into a Color. Returns null if input is null/empty.
     */
    public static Color parseColor(String hex)
    {
        if (hex == null || hex.isEmpty())
        {
            return null;
        }
        try
        {
            return Color.decode(hex);
        }
        catch (NumberFormatException e)
        {
            return null;
        }
    }

    /**
     * Converts a Color to a hex string (e.g. "#FF5733").
     */
    public static String colorToHex(Color color)
    {
        return String.format("#%02X%02X%02X", color.getRed(), color.getGreen(), color.getBlue());
    }

    /**
     * Memoized font derivations. Each card derives several fonts from the same
     * L&F default on every rebuild; AWT fonts are immutable, so caching by
     * (base, style, size) is safe. Keyed by value, and the cache stays small in
     * practice: a handful of base fonts times a few sizes and two styles.
     */
    private static final Map<FontKey, Font> FONT_CACHE = new ConcurrentHashMap<>();

    @EqualsAndHashCode
    @RequiredArgsConstructor
    private static final class FontKey
    {
        private final Font base;
        private final int style;
        private final float size;
    }

    /**
     * Creates a font with the specified style and size, reusing a cached
     * derivation when possible.
     */
    public static Font font(Font base, int style, float size)
    {
        if (base == null) return null;
        return FONT_CACHE.computeIfAbsent(new FontKey(base, style, size), k -> base.deriveFont(style, size));
    }

    /**
     * Creates a bold font.
     */
    public static Font fontBold(Font base, float size)
    {
        return font(base, Font.BOLD, size);
    }

    /**
     * Creates a regular font.
     */
    public static Font fontRegular(Font base, float size)
    {
        return font(base, Font.PLAIN, size);
    }
}

package com.mylosis.roster.ui.components;

import javax.swing.ImageIcon;
import java.awt.BasicStroke;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;

/**
 * Icon registry for the plugin. Icons are drawn programmatically rather than
 * loaded from image resources, so they scale to any requested size. Results
 * are cached. EDT only.
 */
public final class Icons
{
    private Icons() {} // Prevent instantiation

    private static final Map<String, ImageIcon> ICON_CACHE = new HashMap<>();

    // Icon names
    public static final String DELETE = "delete";
    public static final String CLIPBOARD = "clipboard";
    public static final String USER = "user";
    public static final String GRID = "grid";
    public static final String LIST = "list";

    /**
     * Gets an icon by name at the default size. Unknown names get a generic placeholder.
     */
    public static ImageIcon get(String name)
    {
        return get(name, Theme.ICON_SIZE);
    }

    /**
     * Gets an icon by name with a specific size.
     */
    public static ImageIcon get(String name, int size)
    {
        return ICON_CACHE.computeIfAbsent(name + "_" + size, k -> new ImageIcon(drawIcon(name, size)));
    }

    private static BufferedImage drawIcon(String name, int size)
    {
        BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        switch (name)
        {
            case DELETE:
                drawDeleteIcon(g, size);
                break;
            case USER:
                drawUserIcon(g, size);
                break;
            case CLIPBOARD:
                drawClipboardIcon(g, size);
                break;
            case GRID:
                drawGridIcon(g, size);
                break;
            case LIST:
                drawListIcon(g, size);
                break;
            default:
                drawDefaultIcon(g, size);
                break;
        }

        g.dispose();
        return img;
    }

    private static void drawDeleteIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.BUTTON_DANGER);
        g.setStroke(new BasicStroke(Math.max(2, size / 6f)));
        int margin = size / 4;
        g.drawLine(margin, margin, size - margin, size - margin);
        g.drawLine(size - margin, margin, margin, size - margin);
    }

    private static void drawUserIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        int headRadius = size / 4;
        g.fillOval(size / 2 - headRadius, size / 6, headRadius * 2, headRadius * 2);
        g.fillArc(size / 6, size / 2, size * 2 / 3, size * 2 / 3, 0, 180);
    }

    private static void drawClipboardIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        int clipMargin = size / 5;
        int clipWidth = size - clipMargin * 2;
        int clipHeight = (int) (size * 0.75);
        g.fillRoundRect(clipMargin, size / 4, clipWidth, clipHeight, 3, 3);
        g.setColor(Theme.BACKGROUND);
        int clipTopWidth = clipWidth / 2;
        g.fillRoundRect(size / 2 - clipTopWidth / 2, size / 6, clipTopWidth, size / 5, 2, 2);
        g.setColor(Theme.TEXT_SECONDARY);
        g.drawRoundRect(size / 2 - clipTopWidth / 2, size / 6, clipTopWidth, size / 5, 2, 2);
    }

    private static void drawGridIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        int gs = (size - 6) / 2;
        int gap = 2;
        int off = 2;
        g.fillRect(off, off, gs, gs);
        g.fillRect(off + gs + gap, off, gs, gs);
        g.fillRect(off, off + gs + gap, gs, gs);
        g.fillRect(off + gs + gap, off + gs + gap, gs, gs);
    }

    private static void drawListIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        g.setStroke(new BasicStroke(Math.max(2, size / 6f)));
        int lm = size / 5;
        g.drawLine(lm, size / 4, size - lm, size / 4);
        g.drawLine(lm, size / 2, size - lm, size / 2);
        g.drawLine(lm, size * 3 / 4, size - lm, size * 3 / 4);
    }

    private static void drawDefaultIcon(Graphics2D g, int size)
    {
        g.setColor(Theme.TEXT_SECONDARY);
        g.fillOval(2, 2, size - 4, size - 4);
    }
}

package com.mylosis.roster.ui.components;

import javax.swing.JButton;
import javax.swing.border.EmptyBorder;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * A rounded icon button with hover and pressed tints, used in the panel footer.
 */
public class IconButton extends JButton
{
    private boolean hovered = false;
    private boolean pressed = false;

    public IconButton(String iconName, String tooltip)
    {
        setIcon(Icons.get(iconName));
        setToolTipText(tooltip);

        setContentAreaFilled(false);
        setBorderPainted(false);
        setFocusPainted(false);
        setOpaque(false);
        setForeground(Theme.TEXT_PRIMARY);
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setBorder(new EmptyBorder(Theme.SPACING_XS, Theme.SPACING_SM, Theme.SPACING_XS, Theme.SPACING_SM));
        setPreferredSize(new Dimension(Theme.BUTTON_HEIGHT + 8, Theme.BUTTON_HEIGHT));

        addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent e)
            {
                hovered = true;
                repaint();
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                hovered = false;
                pressed = false;
                repaint();
            }

            @Override
            public void mousePressed(MouseEvent e)
            {
                pressed = true;
                repaint();
            }

            @Override
            public void mouseReleased(MouseEvent e)
            {
                pressed = false;
                repaint();
            }
        });
    }

    public void updateIcon(String iconName)
    {
        setIcon(Icons.get(iconName));
        repaint();
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        Color background = pressed ? Theme.CARD_SELECTED
            : hovered ? Theme.BUTTON_SECONDARY_HOVER
            : Theme.BUTTON_SECONDARY;
        g2.setColor(background);
        g2.fillRoundRect(0, 0, getWidth(), getHeight(), Theme.BORDER_RADIUS_SM, Theme.BORDER_RADIUS_SM);

        g2.dispose();
        super.paintComponent(g);
    }
}

package com.mylosis.roster.ui.components;

import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountMetadata;
import com.mylosis.roster.model.AccountType;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.storage.AccountStorage;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.util.Objects;
import java.util.function.Consumer;

/**
 * The add/edit account form, shown inline in the panel header, a category, or
 * an expanded card. Enter moves to the next field, Ctrl+Enter saves, Esc cancels.
 */
@Slf4j
public class InlineAccountForm extends JPanel
{
    private final AccountStorage storage;
    private final Account existingAccount;
    private final String presetGroupId;

    private final JTextField usernameField = Controls.textField("Email or username");
    private final JTextField aliasField = Controls.textField("Display name");
    private final JTextField notesField = Controls.textField("Notes");
    /** Null when the form is pinned to one category (a category's own "+" form). */
    private final JComboBox<GroupComboItem> categoryCombo;
    /** Only present when creating an account; existing accounts change type via the card badge. */
    private final JComboBox<AccountType> typeCombo;

    @Setter
    private Consumer<Account> onSave;
    @Setter
    private Runnable onCancel;

    /**
     * @param existingAccount the account to edit, or null to create one
     * @param showCategoryDropdown whether the user can pick the category
     * @param presetGroupId the category to preselect (dropdown) or always use (no dropdown)
     */
    public InlineAccountForm(AccountStorage storage, Account existingAccount,
                             boolean showCategoryDropdown, String presetGroupId)
    {
        this.storage = storage;
        this.existingAccount = existingAccount;
        this.presetGroupId = presetGroupId;
        this.categoryCombo = showCategoryDropdown ? createCategoryCombo() : null;
        this.typeCombo = existingAccount == null ? createTypeCombo() : null;

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBackground(Theme.FORM_BACKGROUND);
        setBorder(new EmptyBorder(Theme.SPACING_SM, Theme.SPACING_SM, Theme.SPACING_SM, Theme.SPACING_SM));
        setAlignmentX(Component.LEFT_ALIGNMENT);

        buildForm();
        populateFields();
        setupKeyboardShortcuts();
    }

    private void buildForm()
    {
        addRow("Login *", usernameField, Theme.SPACING_XS);
        addRow("Alias", aliasField, Theme.SPACING_XS);
        if (categoryCombo != null)
        {
            addRow("Category", categoryCombo, Theme.SPACING_XS);
        }
        if (typeCombo != null)
        {
            addRow("Type", typeCombo, Theme.SPACING_XS);
        }
        addRow("Notes", notesField, Theme.SPACING_SM);
        add(Controls.formButtons(this::doCancel, this::doSave));
    }

    private void addRow(String label, JComponent field, int gapBelow)
    {
        add(Controls.fieldRow(label, field));
        add(Box.createVerticalStrut(gapBelow));
    }

    private JComboBox<GroupComboItem> createCategoryCombo()
    {
        JComboBox<GroupComboItem> combo = new JComboBox<>();
        styleCombo(combo);
        combo.addItem(GroupComboItem.UNCATEGORIZED);
        for (ProfileGroup group : storage.getGroups())
        {
            combo.addItem(new GroupComboItem(group.getId(), group.getName()));
        }
        return combo;
    }

    private static JComboBox<AccountType> createTypeCombo()
    {
        JComboBox<AccountType> combo = new JComboBox<>(AccountType.values());
        styleCombo(combo);
        combo.setRenderer(new AccountTypeComboRenderer());
        combo.setSelectedItem(AccountType.MAIN);
        return combo;
    }

    private static void styleCombo(JComboBox<?> combo)
    {
        combo.setBackground(Theme.BACKGROUND_DARKER);
        combo.setForeground(Theme.TEXT_PRIMARY);
        combo.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT));
    }

    private void selectCategory(String groupId)
    {
        for (int i = 0; i < categoryCombo.getItemCount(); i++)
        {
            if (Objects.equals(groupId, categoryCombo.getItemAt(i).getId()))
            {
                categoryCombo.setSelectedIndex(i);
                return;
            }
        }
    }

    private void populateFields()
    {
        if (existingAccount != null)
        {
            usernameField.setText(existingAccount.getUsername());
            aliasField.setText(existingAccount.getAlias());
            AccountMetadata meta = existingAccount.getMetadata();
            if (meta != null && meta.getNotes() != null) notesField.setText(meta.getNotes());
            if (categoryCombo != null) selectCategory(existingAccount.getGroupId());
        }
        else if (categoryCombo != null && presetGroupId != null)
        {
            selectCategory(presetGroupId);
        }
    }

    private void setupKeyboardShortcuts()
    {
        bindKey(KeyStroke.getKeyStroke(KeyEvent.VK_ENTER, KeyEvent.CTRL_DOWN_MASK), "save", this::doSave);
        bindKey(KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0), "cancel", this::doCancel);

        KeyAdapter enterAdapter = new KeyAdapter()
        {
            @Override
            public void keyPressed(KeyEvent e)
            {
                if (e.getKeyCode() == KeyEvent.VK_ENTER && !e.isControlDown())
                {
                    e.consume();
                    // Component-local focus hop; the global focus-manager API is
                    // disallowed on the Plugin Hub (flagged in PR #13538).
                    e.getComponent().transferFocus();
                }
            }
        };
        usernameField.addKeyListener(enterAdapter);
        aliasField.addKeyListener(enterAdapter);
        notesField.addKeyListener(enterAdapter);
    }

    private void bindKey(KeyStroke key, String name, Runnable action)
    {
        getInputMap(WHEN_ANCESTOR_OF_FOCUSED_COMPONENT).put(key, name);
        getActionMap().put(name, new AbstractAction()
        {
            @Override
            public void actionPerformed(ActionEvent e)
            {
                action.run();
            }
        });
    }

    private void doSave()
    {
        String username = usernameField.getText().trim();
        if (username.isEmpty())
        {
            Controls.setInvalid(usernameField, true);
            usernameField.requestFocusInWindow();
            return;
        }

        String alias = emptyToNull(aliasField.getText());
        Account account;
        if (existingAccount != null)
        {
            account = existingAccount;
            account.setUsername(username);
            account.setAlias(alias);
        }
        else
        {
            account = Account.createNew(alias, username);
        }
        applyGroup(account);
        applyMetadata(account);
        Controls.setInvalid(usernameField, false);

        // Log the id only: username is the login email, and debug logs end up
        // in client.log files that users paste into bug reports.
        log.debug("Inline form saving account: {}", account.getId());

        if (onSave != null)
        {
            onSave.accept(account);
        }
    }

    private void applyGroup(Account account)
    {
        String groupId = presetGroupId;
        if (categoryCombo != null)
        {
            GroupComboItem selected = (GroupComboItem) categoryCombo.getSelectedItem();
            groupId = selected != null ? selected.getId() : null;
        }
        if (existingAccount != null && !Objects.equals(groupId, account.getGroupId()))
        {
            // Moved to another category: land at its end rather than at the
            // old position number, which means nothing in the new category.
            account.ensureMetadata().setSortOrder(storage.nextAccountSortOrder(groupId));
        }
        account.setGroupId(groupId);
    }

    private void applyMetadata(Account account)
    {
        AccountMetadata meta = account.ensureMetadata();
        meta.setNotes(emptyToNull(notesField.getText()));
        // Notes were mutated through the metadata object, which bypasses
        // Account's invalidating setters; drop the cached search haystack.
        account.invalidateSearchHaystack();
        if (typeCombo != null && typeCombo.getSelectedItem() != null)
        {
            meta.setAccountType((AccountType) typeCombo.getSelectedItem());
        }
    }

    private static String emptyToNull(String text)
    {
        String trimmed = text.trim();
        return trimmed.isEmpty() ? null : trimmed;
    }

    private void doCancel()
    {
        if (onCancel != null) onCancel.run();
    }

    public void focusUsernameField()
    {
        SwingUtilities.invokeLater(usernameField::requestFocusInWindow);
    }

    public void clearFields()
    {
        usernameField.setText("");
        aliasField.setText("");
        notesField.setText("");
        if (categoryCombo != null)
        {
            categoryCombo.setSelectedIndex(0);
            if (presetGroupId != null)
            {
                selectCategory(presetGroupId);
            }
        }
        if (typeCombo != null)
        {
            typeCombo.setSelectedItem(AccountType.MAIN);
        }
        Controls.setInvalid(usernameField, false);
    }

    /**
     * Renders each AccountType in the dropdown with its badge swatch alongside the label.
     * Mirrors the popover that opens when clicking a card badge, so the visual mapping
     * is the same in both places.
     */
    private static class AccountTypeComboRenderer extends DefaultListCellRenderer
    {
        @Override
        public Component getListCellRendererComponent(JList<?> list, Object value, int index,
                                                      boolean isSelected, boolean cellHasFocus)
        {
            super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
            if (value instanceof AccountType)
            {
                AccountType t = (AccountType) value;
                setText(t.getDisplayName());
                setIcon(AccountTypeBadge.swatchIcon(t, 12));
                setIconTextGap(8);
                setBorder(new EmptyBorder(2, 4, 2, 4));
            }
            return this;
        }
    }
}

package com.mylosis.roster.ui.components;

import javax.swing.AbstractButton;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JTextField;
import javax.swing.border.Border;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Supplier;

/**
 * Factories for the plugin's recurring control styles, so every button,
 * field, and popup behaves and looks the same.
 */
public final class Controls
{
    /** Width of the label column in form rows. */
    private static final int FIELD_LABEL_WIDTH = 55;

    private Controls() {}

    /** A borderless button with a solid background that changes on hover. */
    public static JButton flatButton(String text, Color background, Color hoverBackground)
    {
        JButton button = baseButton(text, Theme.TEXT_PRIMARY);
        button.setBackground(background);
        button.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent e) { button.setBackground(hoverBackground); }

            @Override
            public void mouseExited(MouseEvent e) { button.setBackground(background); }
        });
        return button;
    }

    /**
     * A borderless button that shows its container's background (hover and
     * selection tints included) and only fills in while the pointer is on it.
     */
    public static JButton ghostButton(String text, Color foreground, Color hoverBackground, Color hoverForeground)
    {
        JButton button = baseButton(text, foreground);
        button.setContentAreaFilled(false);
        button.setOpaque(false);
        button.setBackground(hoverBackground);
        button.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent e)
            {
                button.setContentAreaFilled(true);
                button.setForeground(hoverForeground);
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                button.setContentAreaFilled(false);
                button.setForeground(foreground);
            }
        });
        return button;
    }

    private static JButton baseButton(String text, Color foreground)
    {
        JButton button = new JButton(text);
        button.setForeground(foreground);
        button.setFocusPainted(false);
        button.setBorderPainted(false);
        button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        return button;
    }

    /**
     * Opens a popup under {@code button} on click. The menu is built on first
     * use: most menus are never opened, and building them for every card on
     * every rebuild was measurable.
     */
    public static void attachLazyMenu(AbstractButton button, Supplier<JPopupMenu> menuFactory)
    {
        JPopupMenu[] menu = new JPopupMenu[1];
        button.addActionListener(e -> {
            if (menu[0] == null)
            {
                menu[0] = menuFactory.get();
            }
            menu[0].show(button, 0, button.getHeight());
        });
    }

    /** A dark single-line text field matching the panel theme. */
    public static JTextField textField(String tooltip)
    {
        JTextField field = new JTextField();
        field.setBackground(Theme.BACKGROUND_DARKER);
        field.setForeground(Theme.TEXT_PRIMARY);
        field.setCaretColor(Theme.TEXT_PRIMARY);
        field.setBorder(fieldBorder(Theme.CARD_BORDER));
        field.setFont(Theme.fontRegular(field.getFont(), Theme.FONT_SIZE_BODY));
        field.setToolTipText(tooltip);
        field.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT));
        return field;
    }

    /** Outlines a field in red (invalid) or restores its normal border. */
    public static void setInvalid(JTextField field, boolean invalid)
    {
        field.setBorder(fieldBorder(invalid ? Theme.BUTTON_DANGER : Theme.CARD_BORDER));
    }

    private static Border fieldBorder(Color outline)
    {
        return BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(outline),
            new EmptyBorder(Theme.SPACING_XS, Theme.SPACING_SM, Theme.SPACING_XS, Theme.SPACING_SM));
    }

    /** A form row: a fixed-width caption on the left, the field filling the rest. */
    public static JPanel fieldRow(String labelText, JComponent field)
    {
        JPanel row = new JPanel(new BorderLayout(Theme.SPACING_XS, 0));
        row.setOpaque(false);
        row.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT));
        row.setAlignmentX(Component.LEFT_ALIGNMENT);
        JLabel label = new JLabel(labelText);
        label.setForeground(Theme.TEXT_SECONDARY);
        label.setFont(Theme.fontRegular(label.getFont(), Theme.FONT_SIZE_SMALL));
        label.setPreferredSize(new Dimension(FIELD_LABEL_WIDTH, Theme.BUTTON_HEIGHT));
        row.add(label, BorderLayout.WEST);
        row.add(field, BorderLayout.CENTER);
        return row;
    }

    /** A Cancel / Save pair, laid out side by side like every form in the panel. */
    public static JPanel formButtons(Runnable onCancel, Runnable onSave)
    {
        JPanel panel = new JPanel(new GridLayout(1, 2, Theme.SPACING_XS, 0));
        panel.setOpaque(false);
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT_SM));
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JButton cancel = flatButton("Cancel", Theme.BUTTON_SECONDARY, Theme.BUTTON_SECONDARY_HOVER);
        cancel.setFont(Theme.fontRegular(cancel.getFont(), Theme.FONT_SIZE_HEADING));
        cancel.addActionListener(e -> onCancel.run());
        panel.add(cancel);

        JButton save = flatButton("Save", Theme.BUTTON_PRIMARY, Theme.BUTTON_PRIMARY_HOVER);
        save.setFont(Theme.fontRegular(save.getFont(), Theme.FONT_SIZE_HEADING));
        save.addActionListener(e -> onSave.run());
        panel.add(save);
        return panel;
    }
}

package com.mylosis.roster.ui.components;

import javax.swing.BorderFactory;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.Timer;
import javax.swing.border.EmptyBorder;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import java.awt.BasicStroke;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.Locale;
import java.util.function.Consumer;

/**
 * A styled search bar component with live filtering support.
 */
public class SearchBar extends JPanel
{
    private final JTextField textField;
    private final JPanel clearButton;
    private Consumer<String> onSearchChanged;
    private boolean isFocused = false;
    private boolean clearHovered = false;
    private String placeholderText = "";

    /**
     * Debounce coalesces rapid keystrokes into a single search invocation.
     * Each typed character triggers a full panel rebuild downstream, so without
     * this a 10-character query meant 10 teardown-and-rebuild cycles. 120ms is
     * imperceptible to users but eliminates the burst: restart()-on-edit means
     * we only fire once the user actually pauses.
     */
    private static final int SEARCH_DEBOUNCE_MS = 120;
    private final Timer searchDebounceTimer;

    public SearchBar()
    {
        searchDebounceTimer = new Timer(SEARCH_DEBOUNCE_MS, e -> fireSearchChanged());
        searchDebounceTimer.setRepeats(false);

        setLayout(new BorderLayout(Theme.SPACING_SM, 0));
        setBackground(Theme.BACKGROUND_DARKER);
        setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(Theme.CARD_BORDER, 1),
            new EmptyBorder(Theme.SPACING_SM, Theme.SPACING_MD, Theme.SPACING_SM, Theme.SPACING_SM)
        ));

        // Search icon
        JPanel iconPanel = new JPanel()
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                super.paintComponent(g);
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(Theme.TEXT_MUTED);

                // Draw search icon (magnifying glass)
                int size = 12;
                int x = (getWidth() - size) / 2;
                int y = (getHeight() - size) / 2;
                g2.setStroke(new BasicStroke(1.5f));
                g2.drawOval(x, y, size - 4, size - 4);
                g2.drawLine(x + size - 5, y + size - 5, x + size - 1, y + size - 1);
                g2.dispose();
            }
        };
        iconPanel.setOpaque(false);
        iconPanel.setPreferredSize(new Dimension(20, 20));
        add(iconPanel, BorderLayout.WEST);

        // Text field with placeholder painting
        textField = new JTextField()
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                super.paintComponent(g);
                if (getText().isEmpty() && !isFocused && !placeholderText.isEmpty())
                {
                    Graphics2D g2 = (Graphics2D) g.create();
                    g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
                    g2.setColor(Theme.TEXT_MUTED);
                    g2.setFont(getFont());
                    int y = (getHeight() + g2.getFontMetrics().getAscent() - g2.getFontMetrics().getDescent()) / 2;
                    g2.drawString(placeholderText, getInsets().left, y);
                    g2.dispose();
                }
            }
        };
        textField.setBorder(null);
        textField.setBackground(Theme.BACKGROUND_DARKER);
        textField.setForeground(Theme.TEXT_PRIMARY);
        textField.setCaretColor(Theme.TEXT_PRIMARY);
        textField.setOpaque(false);

        textField.getDocument().addDocumentListener(new DocumentListener()
        {
            @Override
            public void insertUpdate(DocumentEvent e)
            {
                notifySearchChanged();
            }

            @Override
            public void removeUpdate(DocumentEvent e)
            {
                notifySearchChanged();
            }

            @Override
            public void changedUpdate(DocumentEvent e)
            {
                notifySearchChanged();
            }
        });

        textField.addFocusListener(new FocusAdapter()
        {
            @Override
            public void focusGained(FocusEvent e)
            {
                isFocused = true;
                updateBorder();
                textField.repaint();
            }

            @Override
            public void focusLost(FocusEvent e)
            {
                isFocused = false;
                updateBorder();
                textField.repaint();
            }
        });

        add(textField, BorderLayout.CENTER);

        // Clear button
        clearButton = new JPanel()
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                super.paintComponent(g);
                if (textField.getText().isEmpty())
                {
                    return;
                }

                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

                // Non-opaque component: Swing skips the automatic background
                // fill, so setBackground() from the hover listener never showed.
                // Paint the hover state ourselves.
                if (clearHovered)
                {
                    g2.setColor(Theme.BACKGROUND_HOVER);
                    g2.fillRoundRect(0, 0, getWidth(), getHeight(), 6, 6);
                }
                g2.setColor(Theme.TEXT_MUTED);

                // Draw refresh/circular arrow icon
                int size = 12;
                int x = (getWidth() - size) / 2;
                int y = (getHeight() - size) / 2;
                g2.setStroke(new BasicStroke(1.5f));

                // Draw arc (270 degrees, leaving gap for arrow)
                g2.drawArc(x, y, size, size, 45, 270);

                // Draw arrowhead at the end of arc
                int arrowSize = 3;
                int arrowX = x + size - 1;
                int arrowY = y + size / 2 - 2;
                g2.drawLine(arrowX, arrowY, arrowX + arrowSize, arrowY - arrowSize);
                g2.drawLine(arrowX, arrowY, arrowX + arrowSize, arrowY + arrowSize);

                g2.dispose();
            }
        };
        clearButton.setOpaque(false);
        clearButton.setPreferredSize(new Dimension(20, 20));
        clearButton.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        clearButton.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseClicked(MouseEvent e)
            {
                clear();
            }

            @Override
            public void mouseEntered(MouseEvent e)
            {
                clearHovered = true;
                clearButton.repaint();
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                clearHovered = false;
                clearButton.repaint();
            }
        });
        add(clearButton, BorderLayout.EAST);

        setPreferredSize(new Dimension(0, 32));
    }

    private void updateBorder()
    {
        Color borderColor = isFocused ? Theme.ACCENT_BLUE : Theme.CARD_BORDER;
        setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(borderColor, 1),
            new EmptyBorder(Theme.SPACING_SM, Theme.SPACING_MD, Theme.SPACING_SM, Theme.SPACING_SM)
        ));
        repaint();
    }

    private void notifySearchChanged()
    {
        clearButton.repaint();
        // Coalesce: each keystroke restarts the timer; the callback fires only
        // after the user pauses for SEARCH_DEBOUNCE_MS. Clearing the field via
        // clear() needs an immediate fire (no pause), handled in clear().
        searchDebounceTimer.restart();
    }

    private void fireSearchChanged()
    {
        if (onSearchChanged != null)
        {
            onSearchChanged.accept(textField.getText().toLowerCase(Locale.ROOT).trim());
        }
    }

    public void setOnSearchChanged(Consumer<String> callback)
    {
        this.onSearchChanged = callback;
    }

    public void clear()
    {
        textField.setText("");
        textField.requestFocusInWindow();
        // Clear is an explicit user action: flush any pending debounce so the
        // filtered list updates immediately rather than after a brief delay.
        if (searchDebounceTimer.isRunning())
        {
            searchDebounceTimer.stop();
        }
        fireSearchChanged();
    }

    public void setPlaceholder(String placeholder)
    {
        this.placeholderText = placeholder != null ? placeholder : "";
        textField.setToolTipText(placeholder);
        textField.repaint();
    }
}

package com.mylosis.roster.ui.components;

import javax.swing.JComponent;
import javax.swing.plaf.basic.BasicHTML;

/**
 * Keeps user-controlled text (aliases, logins, notes, category names, all
 * importable from clipboard JSON) from activating Swing's HTML renderer. A
 * value starting with {@code <html>} would otherwise break rendering, and an
 * embedded {@code <img src>} fires an outbound HTTP request when it paints.
 */
public final class SafeText
{
    private SafeText() {}

    /** Disables HTML rendering on a label or other text component; returns it for chaining. */
    public static <T extends JComponent> T plain(T component)
    {
        component.putClientProperty(BasicHTML.propertyKey + ".disable", Boolean.TRUE);
        return component;
    }

    /**
     * Text for places where {@link #plain} can't be applied (tooltips, combo
     * box and dialog items). Ordinary strings pass through unchanged; strings
     * Swing would treat as HTML are escaped so they display literally.
     */
    public static String htmlSafe(String text)
    {
        if (text == null || !BasicHTML.isHTMLString(text))
        {
            return text;
        }
        return "<html>" + escapeHtml(text) + "</html>";
    }

    /**
     * For embedding user text in a JOptionPane message. The pane splits string
     * messages on newlines into separate labels, and a line starting with
     * {@code <html>} would render as HTML, so the text is flattened to one line.
     */
    public static String singleLine(String text)
    {
        return text == null ? "" : text.replace('\r', ' ').replace('\n', ' ');
    }

    /** Escapes HTML special characters, turning newlines into line breaks. */
    public static String escapeHtml(String text)
    {
        if (text == null) return "";
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
            .replace("\"", "&quot;").replace("\n", "<br>");
    }
}

package com.mylosis.roster.ui.components;

import lombok.Value;

/**
 * A category choice in a combo box or selection dialog. Wraps the id so two
 * categories with the same name stay distinguishable.
 */
@Value
public class GroupComboItem
{
    public static final GroupComboItem UNCATEGORIZED = new GroupComboItem(null, "Uncategorized");

    /** Category id; null for Uncategorized. */
    String id;
    String name;

    /**
     * Rendered by JComboBox and JOptionPane through an HTML-capable JLabel, so
     * a user-controlled category name must be made HTML-safe here.
     */
    @Override
    public String toString()
    {
        return SafeText.htmlSafe(name);
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.ui.components.Controls;
import com.mylosis.roster.ui.components.InlineAccountForm;
import com.mylosis.roster.ui.components.Theme;
import lombok.Getter;

import javax.swing.*;
import javax.swing.border.Border;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;

/**
 * One account in the list: a list-view card (details plus edit and menu
 * buttons, expanding into an inline editor) or a compact grid-view tile.
 * Transient state (selection, online status, last-online) is refreshed in
 * place by {@link #refreshDynamicState()} without rebuilding the panel.
 */
public class AccountCardPanel extends JPanel
{
    private final RosterPlugin plugin;
    private final RosterPanel panel;
    @Getter
    private final Account account;
    private final boolean gridMode;
    /** Click/drag listeners spread over the card's non-interactive subtree; re-applied when content is rebuilt. */
    private final List<MouseAdapter> treeListeners = new ArrayList<>();
    /** Spread over the whole subtree, buttons included, so leaving via a button still ends the hover. */
    private final HoverTracker hoverTracker = new HoverTracker();

    private boolean hovered = false;

    // List view
    private JPanel infoHolder;
    private CardExpansionHandler expansion;

    // Grid view
    private boolean gridEditing = false;

    /**
     * @param categoryColor the owning category's color for the left edge stripe; null for none
     */
    public AccountCardPanel(RosterPlugin plugin, RosterPanel panel, Account account, Color categoryColor)
    {
        this.plugin = plugin;
        this.panel = panel;
        this.account = account;
        this.gridMode = plugin.getConfig().gridView();

        setLayout(new BorderLayout(0, 0));
        setBorder(createBorder(categoryColor));
        if (gridMode)
        {
            showGridContent();
        }
        else
        {
            setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.CARD_HEIGHT));
            setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
            buildListCard();
        }
        updateBackground();
        AccountCardHelper.attachToTree(this, hoverTracker, false);
    }

    private static Border createBorder(Color categoryColor)
    {
        Border line = BorderFactory.createLineBorder(Theme.CARD_BORDER, 1);
        if (categoryColor == null)
        {
            return line;
        }
        return BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, Theme.CATEGORY_BORDER_WIDTH, 0, 0, categoryColor), line);
    }

    private void buildListCard()
    {
        JPanel header = new JPanel(new BorderLayout(Theme.SPACING_MD, 0));
        header.setOpaque(false);
        header.setBorder(new EmptyBorder(Theme.SPACING_MD, Theme.SPACING_LG, Theme.SPACING_MD, Theme.SPACING_LG));

        // The info column sits in a holder so refreshDynamicState() can swap
        // it without touching the buttons.
        infoHolder = new JPanel(new BorderLayout());
        infoHolder.setOpaque(false);
        infoHolder.add(ListCardBuilder.buildInfo(plugin, panel, account, getFont()), BorderLayout.CENTER);
        header.add(infoHolder, BorderLayout.CENTER);
        header.add(createActionButtons(), BorderLayout.EAST);
        add(header, BorderLayout.NORTH);

        expansion = new CardExpansionHandler(plugin, panel, this, header);
        add(expansion.getFormPanel(), BorderLayout.CENTER);
    }

    private JPanel createActionButtons()
    {
        JButton edit = cardButton("\u270E", 14f, "Edit account");
        edit.addActionListener(e -> expansion.toggleExpanded());

        JButton menu = cardButton("\u22EE", 16f, "More options");
        Controls.attachLazyMenu(menu, () -> new AccountCardActions(plugin, panel, account, this::expand).createContextMenu());

        JPanel buttons = new JPanel();
        buttons.setLayout(new BoxLayout(buttons, BoxLayout.Y_AXIS));
        buttons.setOpaque(false);
        buttons.add(edit);
        buttons.add(menu);
        return buttons;
    }

    private static JButton cardButton(String glyph, float fontSize, String tooltip)
    {
        JButton button = Controls.ghostButton(glyph, Theme.TEXT_PRIMARY, Theme.CARD_HOVER, Theme.TEXT_PRIMARY);
        button.setPreferredSize(new Dimension(Theme.MENU_BUTTON_SIZE, Theme.MENU_BUTTON_SIZE));
        button.setFont(button.getFont().deriveFont(fontSize));
        button.setToolTipText(tooltip);
        return button;
    }

    private void showGridContent()
    {
        removeAll();
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setPreferredSize(new Dimension(0, GridAccountBuilder.GRID_CARD_HEIGHT));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, GridAccountBuilder.GRID_CARD_HEIGHT));
        GridAccountBuilder.build(this, plugin, panel, account, this::expand);
        reattachTreeListeners();
    }

    /**
     * Re-renders the parts of the card that depend on transient state
     * (selection, online dot, last-online label, badge). No-op for content
     * while the card is being edited.
     */
    void refreshDynamicState()
    {
        updateBackground();
        if (isExpanded())
        {
            return;
        }
        if (gridMode)
        {
            showGridContent();
        }
        else
        {
            infoHolder.removeAll();
            infoHolder.add(ListCardBuilder.buildInfo(plugin, panel, account, getFont()), BorderLayout.CENTER);
            reattachTreeListeners();
        }
        revalidate();
        repaint();
    }

    /**
     * Spreads {@code listener} over the card and its non-interactive children
     * (so hover and drag work anywhere on it), now and after every content rebuild.
     */
    void attachTreeListener(MouseAdapter listener)
    {
        treeListeners.add(listener);
        AccountCardHelper.attachToTree(this, listener, true);
    }

    private void reattachTreeListeners()
    {
        AccountCardHelper.attachToTree(this, hoverTracker, false);
        for (MouseAdapter listener : treeListeners)
        {
            AccountCardHelper.attachToTree(this, listener, true);
        }
    }

    /** Fills the login screen with this account (the card's click action). */
    public void select()
    {
        if (!isExpanded())
        {
            plugin.selectAccount(account);
        }
    }

    public boolean isExpanded()
    {
        return gridEditing || (expansion != null && expansion.isExpanded());
    }

    public void expand()
    {
        if (gridMode) expandGridEdit();
        else expansion.expand();
    }

    void collapse()
    {
        if (gridMode) collapseGridEdit();
        else expansion.collapse();
    }

    /** Grid tiles have no room for an inline form, so editing swaps the tile's content for it. */
    private void expandGridEdit()
    {
        if (gridEditing) return;
        panel.collapseExpandedCard();
        panel.setExpandedCard(this);
        gridEditing = true;

        removeAll();
        setCursor(Cursor.getDefaultCursor());
        InlineAccountForm editForm = new InlineAccountForm(plugin.getAccountStorage(), account, true, null);
        editForm.setOnSave(saved -> {
            plugin.getAccountStorage().saveAccount(saved);
            gridEditing = false;
            panel.setExpandedCard(null);
            panel.rebuild();
        });
        editForm.setOnCancel(this::collapseGridEdit);
        add(editForm, BorderLayout.CENTER);

        // Let the form size naturally.
        setPreferredSize(null);
        setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
        updateBackground();
        editForm.focusUsernameField();
        AccountCardHelper.revalidateScrollPane(this);
    }

    private void collapseGridEdit()
    {
        if (!gridEditing) return;
        gridEditing = false;
        panel.setExpandedCard(null);
        showGridContent();
        updateBackground();
        AccountCardHelper.revalidateScrollPane(this);
    }

    private void updateBackground()
    {
        Color background;
        if (gridEditing)
        {
            background = Theme.FORM_BACKGROUND;
        }
        else if (hovered)
        {
            background = Theme.CARD_HOVER;
        }
        else
        {
            background = account.getId().equals(plugin.getSelectedAccountId()) ? Theme.CARD_SELECTED : Theme.CARD_BACKGROUND;
        }
        setBackground(background);
        repaint();
    }

    /**
     * Tracks hover across the whole card. Moving onto a child fires an exit
     * on the parent, so an exit only counts once the pointer has left the
     * card's bounds.
     */
    private final class HoverTracker extends MouseAdapter
    {
        @Override
        public void mouseEntered(MouseEvent e)
        {
            if (!hovered)
            {
                hovered = true;
                updateBackground();
            }
        }

        @Override
        public void mouseExited(MouseEvent e)
        {
            Point p = SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), AccountCardPanel.this);
            if (hovered && !contains(p))
            {
                hovered = false;
                updateBackground();
            }
        }
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.storage.AccountStorage;
import com.mylosis.roster.ui.components.Controls;
import com.mylosis.roster.ui.components.InlineAccountForm;
import com.mylosis.roster.ui.components.Theme;
import lombok.Getter;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.ActionEvent;

/**
 * The add-account and add-category forms that open below the header buttons.
 * At most one of them is visible at a time.
 */
class PanelFormManager
{
    private final AccountStorage storage;
    private final Runnable onRebuild;
    private final Runnable onRevalidate;

    /** Holds a fresh form on every open, so its category dropdown lists the current categories. */
    @Getter
    private final JPanel addAccountFormPanel;

    @Getter
    private final JPanel addCategoryFormPanel;
    private final JTextField categoryNameField = Controls.textField(null);

    PanelFormManager(AccountStorage storage, Runnable onRebuild, Runnable onRevalidate)
    {
        this.storage = storage;
        this.onRebuild = onRebuild;
        this.onRevalidate = onRevalidate;

        addAccountFormPanel = formContainer(170);

        addCategoryFormPanel = formContainer(70);
        addCategoryFormPanel.add(buildCategoryForm(), BorderLayout.CENTER);
    }

    private static JPanel formContainer(int height)
    {
        JPanel panel = new JPanel(new BorderLayout());
        panel.setBackground(Theme.FORM_BACKGROUND);
        panel.setBorder(BorderFactory.createCompoundBorder(
            new EmptyBorder(Theme.SPACING_SM, 0, 0, 0),
            BorderFactory.createLineBorder(Theme.CARD_BORDER, 1)
        ));
        panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
        panel.setPreferredSize(new Dimension(200, height));
        panel.setAlignmentX(Component.LEFT_ALIGNMENT);
        panel.setVisible(false);
        return panel;
    }

    private JPanel buildCategoryForm()
    {
        JPanel form = new JPanel();
        form.setLayout(new BoxLayout(form, BoxLayout.Y_AXIS));
        form.setBackground(Theme.FORM_BACKGROUND);
        form.setBorder(new EmptyBorder(Theme.SPACING_SM, Theme.SPACING_SM, Theme.SPACING_SM, Theme.SPACING_SM));

        categoryNameField.addActionListener(e -> saveCategory());
        categoryNameField.getInputMap().put(KeyStroke.getKeyStroke("ESCAPE"), "cancel");
        categoryNameField.getActionMap().put("cancel", new AbstractAction()
        {
            @Override
            public void actionPerformed(ActionEvent e)
            {
                cancelCategoryForm();
            }
        });

        form.add(Controls.fieldRow("Name", categoryNameField));
        form.add(Box.createVerticalStrut(Theme.SPACING_SM));
        form.add(Controls.formButtons(this::cancelCategoryForm, this::saveCategory));
        return form;
    }

    private void showAddAccountForm()
    {
        InlineAccountForm addAccountForm = new InlineAccountForm(storage, null, true, null);
        addAccountForm.setOnSave(account -> {
            storage.saveAccount(account);
            hideAddAccountForm();
            onRebuild.run();
        });
        addAccountForm.setOnCancel(() -> {
            hideAddAccountForm();
            onRevalidate.run();
        });
        addAccountFormPanel.removeAll();
        addAccountFormPanel.add(addAccountForm, BorderLayout.CENTER);
        addAccountFormPanel.setVisible(true);
        addAccountForm.focusUsernameField();
    }

    /** Hides the add-account form if it is open. */
    void hideAddAccountForm()
    {
        addAccountFormPanel.setVisible(false);
        addAccountFormPanel.removeAll();
    }

    void toggleAddAccountForm(Runnable collapseExpandedCard)
    {
        addCategoryFormPanel.setVisible(false);
        boolean show = !addAccountFormPanel.isVisible();
        if (show)
        {
            collapseExpandedCard.run();
            showAddAccountForm();
        }
        else
        {
            hideAddAccountForm();
        }
        onRevalidate.run();
    }

    void toggleAddCategoryForm(Runnable collapseExpandedCard)
    {
        hideAddAccountForm();
        collapseExpandedCard.run();

        boolean show = !addCategoryFormPanel.isVisible();
        addCategoryFormPanel.setVisible(show);
        if (show)
        {
            categoryNameField.setText("");
            SwingUtilities.invokeLater(categoryNameField::requestFocusInWindow);
        }
        onRevalidate.run();
    }

    private void saveCategory()
    {
        String name = categoryNameField.getText().trim();
        if (name.isEmpty())
        {
            return;
        }
        ProfileGroup group = ProfileGroup.createNew(name);
        // Auto-assign a default color by creation order.
        int existingCount = storage.getGroups().size();
        if (existingCount < Theme.DEFAULT_CATEGORY_COLORS.length)
        {
            group.setColor(Theme.colorToHex(Theme.DEFAULT_CATEGORY_COLORS[existingCount]));
        }
        storage.saveGroup(group);
        categoryNameField.setText("");
        addCategoryFormPanel.setVisible(false);
        onRebuild.run();
    }

    private void cancelCategoryForm()
    {
        categoryNameField.setText("");
        addCategoryFormPanel.setVisible(false);
        onRevalidate.run();
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.ui.components.Controls;
import com.mylosis.roster.ui.components.Theme;
import com.mylosis.roster.ui.dnd.CategoryDragListener;
import com.mylosis.roster.ui.dnd.DragDropManager;
import lombok.Getter;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * One category in the list: a header (collapse chevron, name, count, add and
 * menu buttons; click to collapse, drag to reorder) above its account cards.
 */
public class CategoryPanel extends JPanel
{
    private static final String CHEVRON_EXPANDED = "\u25BC";
    private static final String CHEVRON_COLLAPSED = "\u25B6";
    /** Longer names are cut so the header row never outgrows the panel. */
    private static final int NAME_MAX_CHARS = 14;

    private final RosterPlugin plugin;
    @Getter
    private final ProfileGroup group;
    private final CategoryFormHandler formHandler;

    private final JPanel headerPanel;
    private final JPanel contentWrapper;
    private final JLabel chevronLabel = new JLabel();
    /** This category's cards, in display order. */
    @Getter
    private final List<AccountCardPanel> cards;
    private boolean collapsed;

    public CategoryPanel(RosterPlugin plugin, RosterPanel panel, ProfileGroup group, List<Account> accounts,
                         DragDropManager dragDropManager)
    {
        this.plugin = plugin;
        this.group = group;
        this.collapsed = group.isCollapsed();
        this.formHandler = new CategoryFormHandler(plugin, panel, group, this);

        setLayout(new BorderLayout());
        setBackground(Theme.BACKGROUND);
        setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

        headerPanel = createHeader(accounts.size(), dragDropManager);
        add(headerPanel, BorderLayout.NORTH);

        List<AccountCardPanel> built = new ArrayList<>();
        contentWrapper = CardListBuilder.build(plugin, panel, dragDropManager, accounts,
            Theme.parseColor(group.getColor()), formHandler.getFormPanel(), built);
        contentWrapper.setBorder(new EmptyBorder(Theme.SPACING_SM, 0, 0, 0));
        cards = Collections.unmodifiableList(built);
        add(contentWrapper, BorderLayout.CENTER);

        updateCollapsedState();
    }

    /**
     * Height of the header row, or 0 if not yet laid out. Used to size the
     * category-reorder hit zone.
     */
    public int getHeaderHeight()
    {
        return headerPanel.getHeight();
    }

    boolean isCollapsed()
    {
        return collapsed;
    }

    private JPanel createHeader(int accountCount, DragDropManager dragDropManager)
    {
        JPanel header = new JPanel(new BorderLayout(Theme.SPACING_MD, 0));
        header.setBackground(Theme.GROUP_HEADER);
        header.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 0, 1, 0, Theme.CARD_BORDER),
            new EmptyBorder(Theme.SPACING_SM, Theme.SPACING_MD, Theme.SPACING_SM, Theme.SPACING_MD)
        ));
        header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

        // A single row that never wraps: anything too wide is clipped instead.
        JPanel left = new JPanel();
        left.setLayout(new BoxLayout(left, BoxLayout.X_AXIS));
        left.setOpaque(false);
        left.add(Box.createHorizontalStrut(Theme.SPACING_SM));

        Color categoryColor = Theme.parseColor(group.getColor());
        chevronLabel.setForeground(categoryColor != null ? categoryColor : Theme.TEXT_SECONDARY);
        chevronLabel.setFont(Theme.fontRegular(chevronLabel.getFont(), Theme.FONT_SIZE_TINY));
        left.add(chevronLabel);
        left.add(Box.createHorizontalStrut(Theme.SPACING_SM));

        left.add(AccountCardHelper.truncatingLabel(group.getName(), Theme.TEXT_PRIMARY,
            Theme.fontBold(chevronLabel.getFont(), Theme.FONT_SIZE_BODY), NAME_MAX_CHARS));
        left.add(Box.createHorizontalStrut(Theme.SPACING_SM));

        JLabel countLabel = new JLabel("\u2022 " + accountCount);
        countLabel.setForeground(Theme.TEXT_SECONDARY);
        countLabel.setFont(Theme.fontBold(countLabel.getFont(), Theme.FONT_SIZE_BODY));
        left.add(countLabel);
        header.add(left, BorderLayout.CENTER);

        JButton menuButton = Controls.ghostButton("\u22EE", Theme.TEXT_SECONDARY, Theme.GROUP_HEADER_HOVER, Theme.TEXT_PRIMARY);
        menuButton.setPreferredSize(new Dimension(24, Theme.BUTTON_HEIGHT_SM));
        menuButton.setToolTipText("Category options");
        Controls.attachLazyMenu(menuButton, formHandler::createContextMenu);

        JPanel right = new JPanel(new FlowLayout(FlowLayout.RIGHT, 2, 0));
        right.setOpaque(false);
        right.add(createHeaderAddButton("Add account to this category", formHandler::toggleAddForm));
        right.add(menuButton);
        header.add(right, BorderLayout.EAST);

        CategoryDragListener dragListener = new CategoryDragListener(dragDropManager, group, this::toggleCollapsed);
        header.addMouseListener(dragListener);
        header.addMouseMotionListener(dragListener);
        header.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent e) { header.setBackground(Theme.GROUP_HEADER_HOVER); }

            @Override
            public void mouseExited(MouseEvent e) { header.setBackground(Theme.GROUP_HEADER); }
        });
        return header;
    }

    /** The "+" button used in category headers and the Uncategorized header. */
    static JButton createHeaderAddButton(String tooltip, Runnable onClick)
    {
        JButton button = Controls.ghostButton("+", Theme.TEXT_SECONDARY, Theme.BUTTON_PRIMARY, Theme.TEXT_PRIMARY);
        button.setPreferredSize(new Dimension(28, Theme.BUTTON_HEIGHT_SM));
        button.setToolTipText(tooltip);
        button.setFont(button.getFont().deriveFont(Font.BOLD, 18f));
        button.addActionListener(e -> onClick.run());
        return button;
    }

    /** Collapses or expands the category and persists the state. */
    void toggleCollapsed()
    {
        collapsed = !collapsed;
        group.setCollapsed(collapsed);
        plugin.getAccountStorage().saveGroup(group);
        updateCollapsedState();
    }

    private void updateCollapsedState()
    {
        contentWrapper.setVisible(!collapsed);
        chevronLabel.setText(collapsed ? CHEVRON_COLLAPSED : CHEVRON_EXPANDED);
        revalidate();
        repaint();
    }
}

package com.mylosis.roster.ui.dnd;

import lombok.Value;

import java.awt.Rectangle;

/**
 * Where a drag would land if released now. Positions are expressed as the
 * visible neighbours of the insertion point rather than an index, so they stay
 * correct when a search filter or non-manual sort hides or reorders entries
 * relative to the stored order.
 */
@Value
public class DropTarget
{
    public enum Type
    {
        /** An account dropped into a category. */
        CATEGORY_DROP,
        /** An account dropped into the Uncategorized area. */
        UNCATEGORIZED,
        /** A category dropped onto another category's header. */
        CATEGORY_REORDER
    }

    Type type;
    /** Target category id for account drops; null for Uncategorized and category reorders. */
    String groupId;
    /** Screen bounds of the highlighted drop zone. */
    Rectangle bounds;
    /** Id of the visible entry the drop lands in front of; null at the end. */
    String beforeId;
    /** Id of the visible entry the drop lands after; null at the start. */
    String afterId;
    /**
     * Screen-space insert indicator: a horizontal line when its height is 0, a
     * vertical one when its width is 0. Null when there is nothing to point at
     * (an empty category).
     */
    Rectangle indicator;
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.ui.RosterPanel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import java.awt.AWTEvent;
import java.awt.Component;
import java.awt.Point;
import java.awt.Toolkit;
import java.awt.event.AWTEventListener;
import java.awt.event.KeyEvent;

/**
 * Drives drag and drop of accounts and categories: tracks the drag, asks
 * {@link DropTargetFinder} where it would land, and hands the drop to
 * {@link DropExecutor}. EDT only.
 */
@Slf4j
public class DragDropManager
{
    private final RosterPanel panel;
    @Getter
    private final DragOverlay overlay;
    private final DropExecutor dropExecutor;

    // Drag state; exactly one of the dragged fields is set while dragging.
    private Account draggedAccount;
    private ProfileGroup draggedCategory;
    /** The list's drop zones, captured when the drag starts. */
    private ListLayout layout;
    private DropTarget currentDropTarget;

    /**
     * ESC aborts an in-flight drag. A Toolkit-level listener (registered only
     * for the drag's duration) rather than a Swing key binding: during a drag,
     * focus may sit on the game's heavyweight canvas, where
     * WHEN_IN_FOCUSED_WINDOW bindings never fire.
     */
    private final AWTEventListener escapeListener = event -> {
        if (isDragging() && event instanceof KeyEvent)
        {
            KeyEvent ke = (KeyEvent) event;
            if (ke.getID() == KeyEvent.KEY_PRESSED && ke.getKeyCode() == KeyEvent.VK_ESCAPE)
            {
                ke.consume();
                cancelDrag();
            }
        }
    };

    public DragDropManager(RosterPlugin plugin, RosterPanel panel)
    {
        this.panel = panel;
        this.overlay = new DragOverlay(this);
        this.dropExecutor = new DropExecutor(plugin, panel);
    }

    public void startAccountDrag(Account account, Component source, Point screenPoint)
    {
        if (isDragging()) return;
        draggedAccount = account;
        begin(source, screenPoint);
        log.debug("Started dragging account: {}", account.getId());
    }

    public void startCategoryDrag(ProfileGroup category, Component source, Point screenPoint)
    {
        if (isDragging()) return;
        draggedCategory = category;
        begin(source, screenPoint);
        log.debug("Started dragging category: {}", category.getId());
    }

    private void begin(Component source, Point screenPoint)
    {
        layout = panel.getListLayout();
        overlay.setDragImage(source);
        overlay.setMouseLocation(screenPoint);
        overlay.setVisible(true);
        Toolkit.getDefaultToolkit().addAWTEventListener(escapeListener, AWTEvent.KEY_EVENT_MASK);
    }

    public void updateDrag(Point screenPoint)
    {
        if (!isDragging()) return;
        currentDropTarget = findDropTarget(screenPoint);
        // setMouseLocation also repaints the overlay.
        overlay.setMouseLocation(screenPoint);
    }

    public void endDrag(Point screenPoint)
    {
        if (!isDragging()) return;
        DropTarget target = findDropTarget(screenPoint);
        Account account = draggedAccount;
        ProfileGroup category = draggedCategory;
        reset();

        if (target != null)
        {
            if (account != null)
            {
                dropExecutor.executeAccountDrop(target, account);
            }
            else
            {
                dropExecutor.executeCategoryDrop(target, category);
            }
        }
    }

    public void cancelDrag()
    {
        reset();
    }

    public boolean isDragging()
    {
        return draggedAccount != null || draggedCategory != null;
    }

    DropTarget getCurrentDropTarget()
    {
        return currentDropTarget;
    }

    private DropTarget findDropTarget(Point screenPoint)
    {
        if (layout == null)
        {
            return null;
        }
        return draggedAccount != null
            ? DropTargetFinder.findForAccount(layout, screenPoint)
            : DropTargetFinder.findForCategory(layout, screenPoint, draggedCategory.getId());
    }

    private void reset()
    {
        // Removing a listener that was never added is a documented no-op.
        Toolkit.getDefaultToolkit().removeAWTEventListener(escapeListener);
        draggedAccount = null;
        draggedCategory = null;
        layout = null;
        currentDropTarget = null;
        overlay.clearDragImage();
        overlay.setVisible(false);
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.ui.components.Theme;

import javax.swing.JComponent;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.IllegalComponentStateException;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * Overlay that shows drag feedback: a ghost of the dragged item following the
 * pointer, the highlighted drop zone, and the insert position indicator.
 */
public class DragOverlay extends JComponent
{
    private static final int MAX_GHOST_WIDTH = 250;
    private static final int MAX_GHOST_HEIGHT = 80;
    private static final int ARROW_SIZE = 5;

    // Strokes, colors, and the ghost composite are constant; allocate once
    // rather than on every frame of a ~60Hz drag.
    private static final BasicStroke STROKE_GHOST_BORDER = new BasicStroke(2);
    private static final BasicStroke STROKE_DROP_DASHED = new BasicStroke(
        2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 0, new float[]{6, 4}, 0);
    private static final BasicStroke STROKE_INDICATOR = new BasicStroke(2);
    private static final Color GHOST_SHADOW = new Color(0, 0, 0, 30);
    private static final Color HIGHLIGHT_FILL = new Color(Theme.BUTTON_PRIMARY.getRed(),
        Theme.BUTTON_PRIMARY.getGreen(), Theme.BUTTON_PRIMARY.getBlue(), 40);
    private static final AlphaComposite GHOST_COMPOSITE =
        AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.85f);

    private final DragDropManager dragManager;

    /** Pointer position in this component's parent coordinates; null when unknown. */
    private Point mouseLocation = null;
    private BufferedImage dragImage = null;

    DragOverlay(DragDropManager dragManager)
    {
        this.dragManager = dragManager;
        setOpaque(false);
    }

    void setMouseLocation(Point screenPoint)
    {
        Point origin = parentOrigin();
        mouseLocation = screenPoint != null && origin != null
            ? new Point(screenPoint.x - origin.x, screenPoint.y - origin.y)
            : null;
        repaint();
    }

    /** Snapshots {@code source} (scaled down to fit) as the drag ghost. */
    void setDragImage(Component source)
    {
        if (source == null || source.getWidth() <= 0 || source.getHeight() <= 0)
        {
            dragImage = null;
            return;
        }
        double scale = Math.min(1.0, Math.min(
            (double) MAX_GHOST_WIDTH / source.getWidth(), (double) MAX_GHOST_HEIGHT / source.getHeight()));
        int width = Math.max(1, (int) (source.getWidth() * scale));
        int height = Math.max(1, (int) (source.getHeight() * scale));
        dragImage = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2d = dragImage.createGraphics();
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2d.scale(scale, scale);
        source.paint(g2d);
        g2d.dispose();
    }

    void clearDragImage()
    {
        dragImage = null;
        mouseLocation = null;
        repaint();
    }

    @Override
    protected void paintComponent(Graphics g)
    {
        if (!dragManager.isDragging())
        {
            return;
        }
        Point origin = parentOrigin();
        if (origin == null)
        {
            return;
        }

        Graphics2D g2d = (Graphics2D) g.create();
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        DropTarget target = dragManager.getCurrentDropTarget();
        if (target != null)
        {
            drawDropTarget(g2d, target, origin);
        }
        if (mouseLocation != null && dragImage != null)
        {
            drawGhost(g2d);
        }
        g2d.dispose();
    }

    private void drawGhost(Graphics2D g2d)
    {
        int width = dragImage.getWidth();
        int height = dragImage.getHeight();
        int x = mouseLocation.x - width / 2;
        int y = mouseLocation.y - height / 2;

        g2d.setColor(GHOST_SHADOW);
        g2d.fillRoundRect(x + 4, y + 4, width, height, 8, 8);

        g2d.setComposite(GHOST_COMPOSITE);
        g2d.drawImage(dragImage, x, y, null);

        g2d.setComposite(AlphaComposite.SrcOver);
        g2d.setColor(Theme.BUTTON_PRIMARY);
        g2d.setStroke(STROKE_GHOST_BORDER);
        g2d.drawRoundRect(x, y, width - 1, height - 1, 8, 8);
    }

    private static void drawDropTarget(Graphics2D g2d, DropTarget target, Point origin)
    {
        Rectangle zone = target.getBounds();
        int x = zone.x - origin.x;
        int y = zone.y - origin.y;

        g2d.setColor(HIGHLIGHT_FILL);
        g2d.fillRoundRect(x, y, zone.width, zone.height, 6, 6);
        g2d.setColor(Theme.BUTTON_PRIMARY);
        g2d.setStroke(STROKE_DROP_DASHED);
        g2d.drawRoundRect(x + 1, y + 1, zone.width - 2, zone.height - 2, 6, 6);

        Rectangle line = target.getIndicator();
        if (line != null)
        {
            drawIndicator(g2d, line.x - origin.x, line.y - origin.y, line.width, line.height);
        }
    }

    /** A line with inward-pointing arrowheads at both ends; horizontal when {@code h == 0}. */
    private static void drawIndicator(Graphics2D g2d, int x, int y, int w, int h)
    {
        g2d.setStroke(STROKE_INDICATOR);
        g2d.setColor(Theme.BUTTON_PRIMARY);
        g2d.drawLine(x, y, x + w, y + h);
        int a = ARROW_SIZE;
        if (h == 0)
        {
            g2d.fillPolygon(new int[]{x, x + a, x}, new int[]{y - a, y, y + a}, 3);
            g2d.fillPolygon(new int[]{x + w, x + w - a, x + w}, new int[]{y - a, y, y + a}, 3);
        }
        else
        {
            g2d.fillPolygon(new int[]{x - a, x, x + a}, new int[]{y, y + a, y}, 3);
            g2d.fillPolygon(new int[]{x - a, x, x + a}, new int[]{y + h, y + h - a, y + h}, 3);
        }
    }

    /** Screen position of this overlay's parent; null if it isn't showing (panel closed mid-drag). */
    private Point parentOrigin()
    {
        if (getParent() == null)
        {
            return null;
        }
        try
        {
            return getParent().getLocationOnScreen();
        }
        catch (IllegalComponentStateException e)
        {
            return null;
        }
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.ui.AccountCardPanel;

import javax.swing.SwingUtilities;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * The single mouse handler for a card's clicks and drags, attached to the card
 * and its non-interactive children so a drag can start anywhere on it.
 * A click selects the account, a double-click opens the editor, and moving
 * past {@link #DRAG_THRESHOLD} starts a drag.
 */
public class AccountDragListener extends MouseAdapter
{
    private static final int DRAG_THRESHOLD = 10;
    private static final int DOUBLE_CLICK_MS = 400;

    // Double-click state is static and keyed by account id: the first click's
    // selection refresh can replace the card before the second click arrives.
    private static long lastClickTime = 0;
    private static String lastClickAccountId = null;

    private final DragDropManager dragManager;
    private final AccountCardPanel card;

    private Point pressPoint = null;
    private boolean dragStarted = false;

    public AccountDragListener(DragDropManager dragManager, AccountCardPanel card)
    {
        this.dragManager = dragManager;
        this.card = card;
    }

    @Override
    public void mousePressed(MouseEvent e)
    {
        if (e.getButton() == MouseEvent.BUTTON1 && !card.isExpanded())
        {
            pressPoint = e.getLocationOnScreen();
            dragStarted = false;
        }
    }

    @Override
    public void mouseReleased(MouseEvent e)
    {
        if (e.getButton() != MouseEvent.BUTTON1)
        {
            return;
        }
        if (dragStarted)
        {
            dragManager.endDrag(e.getLocationOnScreen());
        }
        else if (pressPoint != null && !movedPastThreshold(e.getLocationOnScreen()))
        {
            onClick();
        }
        pressPoint = null;
        dragStarted = false;
    }

    private void onClick()
    {
        String id = card.getAccount().getId();
        long now = System.currentTimeMillis();
        if (id.equals(lastClickAccountId) && now - lastClickTime < DOUBLE_CLICK_MS)
        {
            lastClickTime = 0;
            lastClickAccountId = null;
            SwingUtilities.invokeLater(card::expand);
        }
        else
        {
            lastClickTime = now;
            lastClickAccountId = id;
            card.select();
        }
    }

    @Override
    public void mouseDragged(MouseEvent e)
    {
        if (pressPoint == null) return;

        Point current = e.getLocationOnScreen();
        if (!dragStarted && movedPastThreshold(current))
        {
            dragStarted = true;
            dragManager.startAccountDrag(card.getAccount(), card, pressPoint);
        }
        if (dragStarted)
        {
            dragManager.updateDrag(current);
        }
    }

    private boolean movedPastThreshold(Point current)
    {
        return Math.abs(current.x - pressPoint.x) > DRAG_THRESHOLD
            || Math.abs(current.y - pressPoint.y) > DRAG_THRESHOLD;
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountData;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.model.SortKey;
import com.mylosis.roster.storage.AccountStorage;
import com.mylosis.roster.ui.RosterPanel;
import com.mylosis.roster.ui.components.NotificationToast;
import lombok.extern.slf4j.Slf4j;

import javax.swing.SwingUtilities;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

/**
 * Applies a completed drop: moves or reorders an account, or reorders a
 * category, then saves the renumbered entries in one batch.
 */
@Slf4j
final class DropExecutor
{
    private final RosterPlugin plugin;
    private final RosterPanel panel;

    /** Whether the "switch to Manual sort" hint was already shown this session. */
    private boolean shownSortOverrideHint = false;

    DropExecutor(RosterPlugin plugin, RosterPanel panel)
    {
        this.plugin = plugin;
        this.panel = panel;
    }

    /**
     * Drops an account into a category (or Uncategorized) between the target's
     * visible neighbours.
     *
     * <p>With a non-MANUAL sort active the new {@code sortOrder} is still
     * recorded, but the visible order won't change until the user switches
     * back to MANUAL; a one-time toast explains that.
     */
    void executeAccountDrop(DropTarget target, Account dragged)
    {
        if (target.getType() == DropTarget.Type.CATEGORY_REORDER)
        {
            return;
        }
        AccountStorage storage = plugin.getAccountStorage();
        String targetGroup = target.getGroupId();
        boolean sameCategory = Objects.equals(targetGroup, effectiveGroupId(storage, dragged));
        if (sameCategory && (dragged.getId().equals(target.getBeforeId()) || dragged.getId().equals(target.getAfterId())))
        {
            // Dropped back into its own slot.
            return;
        }

        List<Account> siblings = new ArrayList<>();
        for (Account account : storage.getAccounts())
        {
            if (!account.getId().equals(dragged.getId()) && Objects.equals(targetGroup, effectiveGroupId(storage, account)))
            {
                siblings.add(account);
            }
        }
        siblings.sort(AccountData.SORT_ORDER_COMPARATOR);

        List<String> siblingIds = new ArrayList<>(siblings.size());
        siblings.forEach(a -> siblingIds.add(a.getId()));
        int index = resolveInsertIndex(siblingIds, target.getBeforeId(), target.getAfterId());

        dragged.setGroupId(targetGroup);
        storage.saveAccounts(renumberWithInsert(siblings, dragged, index));
        log.debug("Dropped account {} into category {} at position {}", dragged.getId(), targetGroup, index);

        if (sameCategory)
        {
            notifyIfSortOverridden();
        }
        SwingUtilities.invokeLater(panel::rebuild);
    }

    /** Moves a category before or after the category it was dropped on. */
    void executeCategoryDrop(DropTarget target, ProfileGroup dragged)
    {
        if (target.getType() != DropTarget.Type.CATEGORY_REORDER)
        {
            return;
        }
        AccountStorage storage = plugin.getAccountStorage();
        List<ProfileGroup> groups = storage.getGroups();
        List<String> previousOrder = idsOf(groups);

        groups.removeIf(g -> g.getId().equals(dragged.getId()));
        int index = resolveInsertIndex(idsOf(groups), target.getBeforeId(), target.getAfterId());
        groups.add(index, dragged);
        if (idsOf(groups).equals(previousOrder))
        {
            return;
        }

        for (int i = 0; i < groups.size(); i++)
        {
            groups.get(i).setSortOrder(i);
        }
        storage.saveGroups(groups);
        log.debug("Moved category {} to position {}", dragged.getId(), index);
        SwingUtilities.invokeLater(panel::rebuild);
    }

    private void notifyIfSortOverridden()
    {
        if (shownSortOverrideHint || plugin.getConfig().sortKey() == SortKey.MANUAL)
        {
            return;
        }
        shownSortOverrideHint = true;
        SwingUtilities.invokeLater(() -> panel.showNotification(
            "Drag order saved. Switch to Manual sort to see it.", NotificationToast.Type.INFO));
    }

    /** The category an account is shown in: its group if that exists, else Uncategorized (null). */
    private static String effectiveGroupId(AccountStorage storage, Account account)
    {
        String gid = account.getGroupId();
        return gid != null && storage.getGroup(gid) != null ? gid : null;
    }

    private static List<String> idsOf(List<ProfileGroup> groups)
    {
        List<String> ids = new ArrayList<>(groups.size());
        groups.forEach(g -> ids.add(g.getId()));
        return ids;
    }

    /**
     * Converts a drop's visible neighbours into an index in the stored order
     * ({@code orderedIds}, which excludes the moved entry): in front of
     * {@code beforeId}, else right after {@code afterId}, else at the end.
     */
    static int resolveInsertIndex(List<String> orderedIds, String beforeId, String afterId)
    {
        int before = beforeId != null ? orderedIds.indexOf(beforeId) : -1;
        if (before >= 0)
        {
            return before;
        }
        int after = afterId != null ? orderedIds.indexOf(afterId) : -1;
        if (after >= 0)
        {
            return after + 1;
        }
        return orderedIds.size();
    }

    /**
     * Inserts {@code moved} into {@code siblings} (sorted, not containing it) at
     * {@code insertIndex} and renumbers everyone's {@code sortOrder}
     * sequentially. Out-of-range indexes append.
     *
     * @return every renumbered account, moved one included, ready for a batched save
     */
    static List<Account> renumberWithInsert(List<Account> siblings, Account moved, int insertIndex)
    {
        int index = insertIndex < 0 || insertIndex > siblings.size() ? siblings.size() : insertIndex;
        List<Account> ordered = new ArrayList<>(siblings);
        ordered.add(index, moved);
        for (int i = 0; i < ordered.size(); i++)
        {
            ordered.get(i).ensureMetadata().setSortOrder(i);
        }
        return ordered;
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.ui.AccountCardPanel;
import com.mylosis.roster.ui.CategoryPanel;

import javax.swing.JComponent;
import java.awt.Component;
import java.awt.IllegalComponentStateException;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;

/**
 * Hit-tests a {@link ListLayout} against the pointer during a drag. Bounds
 * are read live on every event, so scrolling mid-drag stays accurate.
 */
final class DropTargetFinder
{
    /** Horizontal inset of the insert line from the drop zone's edges. */
    private static final int LINE_INSET = 20;
    /** Header height assumed before a category has been laid out. */
    private static final int FALLBACK_HEADER_HEIGHT = 45;

    private DropTargetFinder() {}

    /** The drop target for an account drag at {@code p}, or null if outside every zone. */
    static DropTarget findForAccount(ListLayout layout, Point p)
    {
        List<CategoryPanel> categories = layout.getCategories();
        for (int i = 0; i < categories.size(); i++)
        {
            CategoryPanel category = categories.get(i);
            Rectangle bounds = screenBounds(category);
            if (bounds != null && bounds.contains(p))
            {
                return accountTarget(DropTarget.Type.CATEGORY_DROP, category.getGroup().getId(),
                    bounds, layout.getCards(i), p, layout.isGridMode());
            }
        }

        Rectangle area = null;
        for (JComponent zone : layout.getUncategorizedZones())
        {
            Rectangle bounds = screenBounds(zone);
            if (bounds != null)
            {
                area = area == null ? bounds : area.union(bounds);
            }
        }
        if (area != null && area.contains(p))
        {
            return accountTarget(DropTarget.Type.UNCATEGORIZED, null, area,
                layout.getUncategorizedCards(), p, layout.isGridMode());
        }
        return null;
    }

    /**
     * The drop target for a category drag at {@code p}: another category's
     * header, split at its midpoint into "before" and "after".
     */
    static DropTarget findForCategory(ListLayout layout, Point p, String draggedId)
    {
        for (CategoryPanel category : layout.getCategories())
        {
            String id = category.getGroup().getId();
            Rectangle panel = screenBounds(category);
            if (id.equals(draggedId) || panel == null)
            {
                continue;
            }
            int headerHeight = category.getHeaderHeight() > 0 ? category.getHeaderHeight() : FALLBACK_HEADER_HEIGHT;
            Rectangle header = new Rectangle(panel.x, panel.y, panel.width, headerHeight);
            if (header.contains(p))
            {
                boolean before = p.y < header.y + header.height / 2;
                int lineY = before ? panel.y : panel.y + panel.height;
                Rectangle line = new Rectangle(panel.x + LINE_INSET, lineY, panel.width - 2 * LINE_INSET, 0);
                return new DropTarget(DropTarget.Type.CATEGORY_REORDER, null, header,
                    before ? id : null, before ? null : id, line);
            }
        }
        return null;
    }

    private static DropTarget accountTarget(DropTarget.Type type, String groupId, Rectangle zone,
                                            List<AccountCardPanel> cards, Point p, boolean gridMode)
    {
        List<AccountCardPanel> visible = new ArrayList<>(cards.size());
        List<Rectangle> rects = new ArrayList<>(cards.size());
        for (AccountCardPanel card : cards)
        {
            Rectangle bounds = screenBounds(card);
            if (bounds != null)
            {
                visible.add(card);
                rects.add(bounds);
            }
        }
        InsertPoint insert = gridMode ? gridInsertPoint(rects, p) : listInsertPoint(rects, p, zone);
        String beforeId = insert.index < visible.size() ? visible.get(insert.index).getAccount().getId() : null;
        String afterId = insert.index > 0 ? visible.get(insert.index - 1).getAccount().getId() : null;
        return new DropTarget(type, groupId, zone, beforeId, afterId, insert.indicator);
    }

    /** Where a drop lands among visible cards: before {@code index} ({@code size} = at the end). */
    static final class InsertPoint
    {
        final int index;
        final Rectangle indicator;

        InsertPoint(int index, Rectangle indicator)
        {
            this.index = index;
            this.indicator = indicator;
        }
    }

    /** Single-column list: the first card whose vertical midpoint is below the pointer. */
    static InsertPoint listInsertPoint(List<Rectangle> cards, Point p, Rectangle zone)
    {
        int lineX = zone.x + LINE_INSET;
        int lineWidth = zone.width - 2 * LINE_INSET;
        for (int i = 0; i < cards.size(); i++)
        {
            Rectangle card = cards.get(i);
            if (p.y < card.y + card.height / 2)
            {
                return new InsertPoint(i, new Rectangle(lineX, card.y, lineWidth, 0));
            }
        }
        if (cards.isEmpty())
        {
            return new InsertPoint(0, null);
        }
        Rectangle last = cards.get(cards.size() - 1);
        return new InsertPoint(cards.size(), new Rectangle(lineX, last.y + last.height, lineWidth, 0));
    }

    /**
     * Two-column grid in row-major order: the first card whose row is below the
     * pointer, or which shares the pointer's row with its center to the right.
     */
    static InsertPoint gridInsertPoint(List<Rectangle> cards, Point p)
    {
        int index = cards.size();
        for (int i = 0; i < cards.size(); i++)
        {
            Rectangle card = cards.get(i);
            boolean rowBelowPointer = p.y < card.y;
            boolean sameRowToTheRight = p.y < card.y + card.height && p.x < card.x + card.width / 2;
            if (rowBelowPointer || sameRowToTheRight)
            {
                index = i;
                break;
            }
        }
        if (cards.isEmpty())
        {
            return new InsertPoint(0, null);
        }

        // Vertical indicator: right of the previous card when the pointer is
        // on its row, otherwise left of the next card (or right of the last).
        if (index > 0)
        {
            Rectangle prev = cards.get(index - 1);
            if (index == cards.size() || (p.y >= prev.y && p.y < prev.y + prev.height))
            {
                return new InsertPoint(index, new Rectangle(prev.x + prev.width + 1, prev.y, 0, prev.height));
            }
        }
        Rectangle next = cards.get(index);
        return new InsertPoint(index, new Rectangle(next.x - 2, next.y, 0, next.height));
    }

    /** On-screen bounds of a showing component; null when it isn't showing. */
    private static Rectangle screenBounds(Component component)
    {
        if (!component.isShowing())
        {
            return null;
        }
        try
        {
            Point location = component.getLocationOnScreen();
            return new Rectangle(location.x, location.y, component.getWidth(), component.getHeight());
        }
        catch (IllegalComponentStateException e)
        {
            return null;
        }
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.model.ProfileGroup;

import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * Mouse handler for a category header: a short click toggles collapse,
 * moving past {@link #DRAG_THRESHOLD} starts a category reorder drag.
 */
public class CategoryDragListener extends MouseAdapter
{
    private static final int DRAG_THRESHOLD = 10;

    private final DragDropManager dragManager;
    private final ProfileGroup category;
    private final Runnable onClick;

    private Point pressPoint = null;
    private boolean dragStarted = false;

    public CategoryDragListener(DragDropManager dragManager, ProfileGroup category, Runnable onClick)
    {
        this.dragManager = dragManager;
        this.category = category;
        this.onClick = onClick;
    }

    @Override
    public void mousePressed(MouseEvent e)
    {
        if (e.getButton() == MouseEvent.BUTTON1)
        {
            pressPoint = e.getLocationOnScreen();
            dragStarted = false;
        }
    }

    @Override
    public void mouseReleased(MouseEvent e)
    {
        if (e.getButton() != MouseEvent.BUTTON1)
        {
            return;
        }
        if (dragStarted)
        {
            dragManager.endDrag(e.getLocationOnScreen());
        }
        else if (pressPoint != null && !movedPastThreshold(e.getLocationOnScreen()))
        {
            onClick.run();
        }
        pressPoint = null;
        dragStarted = false;
    }

    @Override
    public void mouseDragged(MouseEvent e)
    {
        if (pressPoint == null) return;

        Point current = e.getLocationOnScreen();
        if (!dragStarted && movedPastThreshold(current))
        {
            dragStarted = true;
            dragManager.startCategoryDrag(category, e.getComponent(), pressPoint);
        }
        if (dragStarted)
        {
            dragManager.updateDrag(current);
        }
    }

    private boolean movedPastThreshold(Point current)
    {
        return Math.abs(current.x - pressPoint.x) > DRAG_THRESHOLD
            || Math.abs(current.y - pressPoint.y) > DRAG_THRESHOLD;
    }
}

package com.mylosis.roster.ui.dnd;

import com.mylosis.roster.ui.AccountCardPanel;
import com.mylosis.roster.ui.CategoryPanel;
import lombok.Getter;

import javax.swing.JComponent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The drop zones of one rendered list, recorded by the list builder as it
 * creates them. Drag hit-testing reads this instead of searching the
 * component tree, and a rebuild simply replaces it.
 */
public final class ListLayout
{
    /** Whether cards are laid out in the two-column grid (row-major order). */
    @Getter
    private final boolean gridMode;
    private final List<CategoryPanel> categories = new ArrayList<>();
    private final List<List<AccountCardPanel>> categoryCards = new ArrayList<>();
    private final List<JComponent> uncategorizedZones = new ArrayList<>();
    private List<AccountCardPanel> uncategorizedCards = Collections.emptyList();

    public ListLayout(boolean gridMode)
    {
        this.gridMode = gridMode;
    }

    /** Records a category panel and its cards, in display order. */
    public void addCategory(CategoryPanel category, List<AccountCardPanel> cards)
    {
        categories.add(category);
        categoryCards.add(cards);
    }

    /** Records a component that is part of the Uncategorized drop area (its header or card list). */
    public void addUncategorizedZone(JComponent zone)
    {
        uncategorizedZones.add(zone);
    }

    public void setUncategorizedCards(List<AccountCardPanel> cards)
    {
        uncategorizedCards = cards;
    }

    List<CategoryPanel> getCategories()
    {
        return categories;
    }

    List<AccountCardPanel> getCards(int categoryIndex)
    {
        return categoryCards.get(categoryIndex);
    }

    List<JComponent> getUncategorizedZones()
    {
        return uncategorizedZones;
    }

    List<AccountCardPanel> getUncategorizedCards()
    {
        return uncategorizedCards;
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterConfig;
import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountMetadata;
import com.mylosis.roster.ui.components.Controls;
import com.mylosis.roster.ui.components.SafeText;
import com.mylosis.roster.ui.components.Theme;

import javax.swing.*;
import java.awt.*;

/**
 * Builds the body of a compact grid-view card: a centered name with its type
 * badge, one subtitle line, and a small menu button in the corner.
 */
final class GridAccountBuilder
{
    static final int GRID_CARD_HEIGHT = 56;

    private static final int NAME_MAX_CHARS = 12;
    private static final int SUBTITLE_MAX_CHARS = 14;
    private static final int BADGE_SIZE = 16;
    private static final int MENU_BUTTON_SIZE = 16;

    private GridAccountBuilder() {}

    static void build(AccountCardPanel card, RosterPlugin plugin, RosterPanel panel, Account account, Runnable onEdit)
    {
        card.setLayout(new BorderLayout(0, 0));

        JPanel inner = new JPanel();
        inner.setLayout(new BoxLayout(inner, BoxLayout.Y_AXIS));
        inner.setOpaque(false);

        String displayName = AccountCardHelper.resolveDisplayName(account, plugin.getConfig());

        // Name + clickable type badge, centered as a unit
        JPanel nameRow = new JPanel(new FlowLayout(FlowLayout.CENTER, Theme.SPACING_SM, 0));
        nameRow.setOpaque(false);
        nameRow.setAlignmentX(Component.CENTER_ALIGNMENT);
        nameRow.add(truncatedLabel(displayName, NAME_MAX_CHARS, Theme.TEXT_PRIMARY,
            Theme.fontBold(card.getFont(), Theme.FONT_SIZE_BODY)));
        nameRow.add(AccountCardHelper.createTypeBadge(plugin, panel, account, BADGE_SIZE));
        inner.add(nameRow);

        String subtitle = subtitle(plugin.getConfig(), account);
        if (subtitle != null)
        {
            inner.add(Box.createVerticalStrut(1));
            JLabel subLabel = truncatedLabel(subtitle, SUBTITLE_MAX_CHARS, Theme.TEXT_SECONDARY,
                Theme.fontRegular(card.getFont(), Theme.FONT_SIZE_SMALL));
            subLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
            subLabel.setHorizontalAlignment(SwingConstants.CENTER);
            inner.add(subLabel);
        }

        JPanel content = new JPanel(new GridBagLayout());
        content.setOpaque(false);
        content.add(inner);
        card.add(content, BorderLayout.CENTER);

        // Menu button on the right, with a matching spacer on the left so the
        // text stays centered.
        JButton menuButton = Controls.ghostButton("\u22EE", Theme.TEXT_SECONDARY, Theme.CARD_HOVER, Theme.TEXT_PRIMARY);
        menuButton.setPreferredSize(new Dimension(MENU_BUTTON_SIZE, MENU_BUTTON_SIZE));
        menuButton.setFont(menuButton.getFont().deriveFont(12f));
        menuButton.setToolTipText("More options");
        Controls.attachLazyMenu(menuButton, () -> new AccountCardActions(plugin, panel, account, onEdit).createContextMenu());

        JPanel buttonHolder = new JPanel(new GridBagLayout());
        buttonHolder.setOpaque(false);
        buttonHolder.setPreferredSize(new Dimension(MENU_BUTTON_SIZE + 4, 0));
        buttonHolder.add(menuButton);
        card.add(buttonHolder, BorderLayout.EAST);

        JPanel spacer = new JPanel();
        spacer.setOpaque(false);
        spacer.setPreferredSize(new Dimension(MENU_BUTTON_SIZE + 4, 0));
        card.add(spacer, BorderLayout.WEST);
    }

    private static JLabel truncatedLabel(String text, int maxChars, Color color, Font font)
    {
        String value = text != null ? text : "";
        boolean truncated = value.length() > maxChars;
        JLabel label = SafeText.plain(new JLabel(truncated ? value.substring(0, maxChars) + "..." : value));
        label.setForeground(color);
        label.setFont(font);
        if (truncated) label.setToolTipText(SafeText.htmlSafe(value));
        return label;
    }

    /** The most useful second line allowed by the privacy settings: notes, then login, then last online. */
    private static String subtitle(RosterConfig config, Account account)
    {
        AccountMetadata meta = account.getMetadata();
        if (!config.hideNotes() && meta != null && meta.getNotes() != null && !meta.getNotes().isEmpty())
        {
            return meta.getNotes();
        }
        // Skip the login when the name line already shows it (alias hidden or unset).
        if (!config.hideLogin() && !config.hideAlias() && account.getUsername() != null
            && !account.getUsername().equals(account.getDisplayName()))
        {
            return account.getUsername();
        }
        if (!config.hideLastOnline() && meta != null)
        {
            return AccountCardHelper.formatTimeAgo(meta.getLastOnlineAt());
        }
        return null;
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterConfig;
import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.ui.components.NotificationToast;
import com.mylosis.roster.ui.components.Theme;
import com.mylosis.roster.ui.dnd.DragDropManager;
import com.mylosis.roster.ui.dnd.DragOverlay;
import com.mylosis.roster.ui.dnd.ListLayout;
import lombok.AccessLevel;
import lombok.Getter;
import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.util.HashMap;
import java.util.Map;

/**
 * Main panel for the Roster plugin. Owns the header, forms, card list,
 * footer, and notifications, and rebuilds or refreshes the list on demand.
 * EDT only.
 */
public class RosterPanel extends PluginPanel
{
    private static final int NOTIFICATION_DURATION_MS = 3000;

    private final RosterPlugin plugin;
    private final DragDropManager dragDropManager;
    private final AccountListBuilder listBuilder;
    @Getter(AccessLevel.PACKAGE)
    private final PanelFormManager formManager;
    private final PanelFooterBuilder footer;

    private final JScrollPane scrollPane;
    private final JLayeredPane layeredPane;
    private final JPanel notificationPanel;
    private final JLabel accountCountLabel = new JLabel();

    private String searchFilter = "";
    private AccountCardPanel expandedCard;

    /**
     * Live id -> card lookup, repopulated on every rebuild, so small state
     * changes (selection, online status, badge) refresh one card in place.
     */
    private final Map<String, AccountCardPanel> cardsByAccountId = new HashMap<>();
    /** Drop zones of the current list, for drag and drop. */
    @Getter
    private ListLayout listLayout;

    public RosterPanel(RosterPlugin plugin)
    {
        // No PluginPanel scroll wrapper: the card list has its own scroll pane,
        // and a second one swallowed mouse-wheel events.
        super(false);
        this.plugin = plugin;
        this.dragDropManager = new DragDropManager(plugin, this);
        this.listBuilder = new AccountListBuilder(plugin, this, dragDropManager);
        this.formManager = new PanelFormManager(plugin.getAccountStorage(), this::rebuild, this::revalidateAndRepaint);
        this.footer = new PanelFooterBuilder(plugin, this, this::showNotification, this::rebuild);

        setLayout(new BorderLayout());
        setBackground(Theme.BACKGROUND);

        scrollPane = createScrollPane();
        notificationPanel = createNotificationPanel();

        layeredPane = new JLayeredPane();
        layeredPane.setLayout(new OverlayLayout(layeredPane));
        layeredPane.add(createContentPanel(), JLayeredPane.DEFAULT_LAYER);
        layeredPane.add(notificationPanel, JLayeredPane.POPUP_LAYER);
        DragOverlay dragOverlay = dragDropManager.getOverlay();
        dragOverlay.setVisible(false);
        layeredPane.add(dragOverlay, JLayeredPane.DRAG_LAYER);
        layeredPane.addComponentListener(new ComponentAdapter()
        {
            @Override
            public void componentResized(ComponentEvent e)
            {
                repositionNotificationPanel();
            }
        });

        add(layeredPane, BorderLayout.CENTER);
        rebuild();
    }

    private JPanel createContentPanel()
    {
        JPanel contentPanel = new JPanel(new BorderLayout());
        contentPanel.setBackground(Theme.BACKGROUND);
        contentPanel.setBorder(new EmptyBorder(Theme.SPACING_MD, Theme.SPACING_SM, Theme.SPACING_SM, Theme.SPACING_SM));

        JPanel header = PanelHeaderBuilder.build(
            this::onSearchChanged,
            () -> formManager.toggleAddAccountForm(this::collapseExpandedCardOnly),
            () -> formManager.toggleAddCategoryForm(this::collapseExpandedCardOnly),
            () -> plugin.getConfig().sortKey(),
            // Written to config; onConfigChanged triggers the rebuild.
            key -> plugin.getConfigManager().setConfiguration(RosterConfig.CONFIG_GROUP, "sortKey", key));

        JPanel headerWithForms = new JPanel();
        headerWithForms.setLayout(new BoxLayout(headerWithForms, BoxLayout.Y_AXIS));
        headerWithForms.setBackground(Theme.BACKGROUND);
        headerWithForms.add(header);
        headerWithForms.add(formManager.getAddAccountFormPanel());
        headerWithForms.add(formManager.getAddCategoryFormPanel());
        contentPanel.add(headerWithForms, BorderLayout.NORTH);

        contentPanel.add(scrollPane, BorderLayout.CENTER);

        accountCountLabel.setForeground(Theme.TEXT_SECONDARY);
        accountCountLabel.setFont(Theme.fontRegular(accountCountLabel.getFont(), Theme.FONT_SIZE_SMALL));
        contentPanel.add(footer.build(accountCountLabel), BorderLayout.SOUTH);
        return contentPanel;
    }

    private static JScrollPane createScrollPane()
    {
        JScrollPane pane = new JScrollPane();
        pane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        pane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        pane.setBorder(null);
        pane.getVerticalScrollBar().setUnitIncrement(16);
        pane.setBackground(Theme.BACKGROUND);
        pane.getViewport().setBackground(Theme.BACKGROUND);
        return pane;
    }

    private static JPanel createNotificationPanel()
    {
        JPanel panel = new JPanel(new FlowLayout(FlowLayout.CENTER, 0, 0))
        {
            @Override
            public boolean isOptimizedDrawingEnabled()
            {
                return false;
            }
        };
        panel.setOpaque(false);
        panel.setAlignmentX(0f);
        panel.setAlignmentY(0.5f);
        panel.setMaximumSize(new Dimension(0, 0));
        return panel;
    }

    private void onSearchChanged(String filter)
    {
        // The debounce can fire with unchanged text (typed then deleted).
        if (!filter.equals(searchFilter))
        {
            searchFilter = filter;
            rebuild();
            // A new result set starts at the top.
            scrollPane.getVerticalScrollBar().setValue(0);
        }
    }

    /**
     * Rebuilds the card list from storage, keeping the scroll position.
     */
    public void rebuild()
    {
        int scrollValue = scrollPane.getVerticalScrollBar().getValue();

        // A fresh list panel avoids stale BoxLayout caches; the old cards,
        // including any open editor, are discarded with it.
        JPanel list = new ListPanel();
        list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
        list.setBackground(Theme.BACKGROUND);
        cardsByAccountId.clear();
        expandedCard = null;
        listLayout = new ListLayout(plugin.getConfig().gridView());

        AccountListBuilder.Counts counts = listBuilder.build(list, searchFilter, listLayout);
        updateAccountCount(counts.getVisible(), counts.getTotal());
        footer.refresh();

        scrollPane.setViewportView(list);
        // Lay out now so the restored position is clamped against the new height.
        scrollPane.validate();
        scrollPane.getVerticalScrollBar().setValue(scrollValue);
        scrollPane.repaint();
    }

    private void updateAccountCount(int visible, int total)
    {
        accountCountLabel.setText(visible == total
            ? total + " Account" + (total != 1 ? "s" : "")
            : visible + " / " + total + " Accounts");
    }

    /**
     * Refreshes one card's transient state (selection, online status, badge)
     * in place. Falls back to a full rebuild when the card isn't shown, unless
     * it is only hidden by the search filter (a rebuild would change nothing).
     */
    public void refreshAccount(String accountId)
    {
        AccountCardPanel card = cardsByAccountId.get(accountId);
        if (card != null)
        {
            card.refreshDynamicState();
            return;
        }
        if (!searchFilter.isEmpty())
        {
            Account account = plugin.getAccountStorage().getAccount(accountId);
            if (account != null && !account.getSearchHaystack().contains(searchFilter))
            {
                return;
            }
        }
        rebuild();
    }

    /** Called by the list builders as each card is created. */
    void registerCard(String accountId, AccountCardPanel card)
    {
        cardsByAccountId.put(accountId, card);
    }

    void setExpandedCard(AccountCardPanel card)
    {
        expandedCard = card;
    }

    /** Collapses the card being edited, if any, and hides the add-account form. */
    void collapseExpandedCard()
    {
        collapseExpandedCardOnly();
        formManager.hideAddAccountForm();
    }

    private void collapseExpandedCardOnly()
    {
        if (expandedCard != null)
        {
            AccountCardPanel card = expandedCard;
            expandedCard = null;
            card.collapse();
        }
    }

    public void showNotification(String message, NotificationToast.Type type)
    {
        // Stop the replaced toast's timers, or they keep repainting a
        // parentless component until they finish.
        for (Component c : notificationPanel.getComponents())
        {
            if (c instanceof NotificationToast)
            {
                ((NotificationToast) c).stopTimers();
            }
        }
        notificationPanel.removeAll();
        notificationPanel.add(new NotificationToast(message, type, NOTIFICATION_DURATION_MS));
        notificationPanel.revalidate();
        SwingUtilities.invokeLater(this::repositionNotificationPanel);
    }

    private void repositionNotificationPanel()
    {
        if (notificationPanel.getComponentCount() == 0)
        {
            notificationPanel.setBounds(0, 0, 0, 0);
            return;
        }

        int width = layeredPane.getWidth();
        notificationPanel.setSize(width, 100);
        notificationPanel.doLayout();
        Dimension pref = notificationPanel.getPreferredSize();
        int y = layeredPane.getHeight() - pref.height - 50;
        notificationPanel.setBounds(0, y, width, pref.height + 20);
        notificationPanel.repaint();
    }

    private void revalidateAndRepaint()
    {
        revalidate();
        repaint();
    }

    /**
     * The scrolled card list. Always exactly as wide as the viewport: without
     * this, one over-wide row (a long category name) widened the whole list and
     * pushed every card's buttons out of view, since horizontal scrolling is off.
     */
    private static final class ListPanel extends JPanel implements Scrollable
    {
        private static final int SCROLL_UNIT = 16;

        @Override
        public Dimension getPreferredScrollableViewportSize()
        {
            return getPreferredSize();
        }

        @Override
        public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
        {
            return SCROLL_UNIT;
        }

        @Override
        public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
        {
            return orientation == SwingConstants.VERTICAL ? visibleRect.height : visibleRect.width;
        }

        @Override
        public boolean getScrollableTracksViewportWidth()
        {
            return true;
        }

        @Override
        public boolean getScrollableTracksViewportHeight()
        {
            return false;
        }
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.ProfileGroup;
import com.mylosis.roster.ui.components.InlineAccountForm;
import com.mylosis.roster.ui.components.SafeText;
import com.mylosis.roster.ui.components.Theme;
import lombok.Getter;
import net.runelite.client.ui.components.colorpicker.RuneliteColorPicker;

import javax.swing.*;
import java.awt.*;

/**
 * A category's add-account form and its header menu (rename, add account,
 * color, delete).
 */
class CategoryFormHandler
{
    private static final int SWATCH_SIZE = 12;

    private final RosterPlugin plugin;
    private final RosterPanel panel;
    private final ProfileGroup group;
    private final CategoryPanel categoryPanel;

    /** Hidden container for the add form, which is only built on first show. */
    @Getter
    private final JPanel formPanel;
    private InlineAccountForm addForm;

    CategoryFormHandler(RosterPlugin plugin, RosterPanel panel, ProfileGroup group, CategoryPanel categoryPanel)
    {
        this.plugin = plugin;
        this.panel = panel;
        this.group = group;
        this.categoryPanel = categoryPanel;

        formPanel = new JPanel(new BorderLayout());
        formPanel.setBackground(Theme.FORM_BACKGROUND);
        formPanel.setBorder(BorderFactory.createLineBorder(Theme.CARD_BORDER, 1));
        formPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 180));
        formPanel.setVisible(false);
    }

    /** Shows or hides the add form, expanding the category first if needed. */
    void toggleAddForm()
    {
        if (formPanel.isVisible())
        {
            hideAddForm();
            return;
        }
        if (addForm == null)
        {
            addForm = new InlineAccountForm(plugin.getAccountStorage(), null, false, group.getId());
            addForm.setOnSave(account -> {
                plugin.getAccountStorage().saveAccount(account);
                hideAddForm();
                panel.rebuild();
            });
            addForm.setOnCancel(this::hideAddForm);
            formPanel.add(addForm, BorderLayout.CENTER);
        }
        if (categoryPanel.isCollapsed())
        {
            categoryPanel.toggleCollapsed();
        }
        formPanel.setVisible(true);
        addForm.focusUsernameField();
        AccountCardHelper.revalidateScrollPane(categoryPanel);
    }

    private void hideAddForm()
    {
        addForm.clearFields();
        formPanel.setVisible(false);
        AccountCardHelper.revalidateScrollPane(categoryPanel);
    }

    JPopupMenu createContextMenu()
    {
        JPopupMenu menu = new JPopupMenu();
        addItem(menu, "Rename", this::renameCategory);
        addItem(menu, "Add Account", this::toggleAddForm);
        menu.addSeparator();
        menu.add(createColorMenu());
        menu.addSeparator();
        addItem(menu, "Delete Category", this::confirmDelete).setForeground(Theme.BUTTON_DANGER);
        return menu;
    }

    private static JMenuItem addItem(JComponent menu, String label, Runnable action)
    {
        JMenuItem item = new JMenuItem(label);
        item.addActionListener(e -> action.run());
        menu.add(item);
        return item;
    }

    private JMenu createColorMenu()
    {
        JMenu colorMenu = new JMenu("Set Color");
        for (int i = 0; i < Theme.CATEGORY_COLORS.length; i++)
        {
            Color color = Theme.CATEGORY_COLORS[i];
            JMenuItem swatch = addItem(colorMenu, Theme.CATEGORY_COLOR_NAMES[i], () -> saveColor(Theme.colorToHex(color)));
            swatch.setIcon(swatchIcon(color));
        }
        colorMenu.addSeparator();
        addItem(colorMenu, "Custom...", this::pickCustomColor);
        addItem(colorMenu, "Reset Color", () -> saveColor(null));
        return colorMenu;
    }

    private void pickCustomColor()
    {
        Color current = Theme.parseColor(group.getColor());
        RuneliteColorPicker picker = plugin.getColorPickerManager().create(
            SwingUtilities.getWindowAncestor(panel),
            current != null ? current : Theme.ACCENT_ORANGE,
            group.getName() + " Color",
            true // hide alpha slider
        );
        picker.setOnClose(chosen -> saveColor(Theme.colorToHex(chosen)));
        picker.setVisible(true);
    }

    private void saveColor(String hex)
    {
        group.setColor(hex);
        plugin.getAccountStorage().saveGroup(group);
        panel.rebuild();
    }

    private static Icon swatchIcon(Color color)
    {
        return new Icon()
        {
            @Override
            public void paintIcon(Component c, Graphics g, int x, int y)
            {
                g.setColor(color);
                g.fillRect(x, y, SWATCH_SIZE, SWATCH_SIZE);
                g.setColor(Theme.CARD_BORDER);
                g.drawRect(x, y, SWATCH_SIZE - 1, SWATCH_SIZE - 1);
            }

            @Override
            public int getIconWidth() { return SWATCH_SIZE; }

            @Override
            public int getIconHeight() { return SWATCH_SIZE; }
        };
    }

    private void renameCategory()
    {
        String newName = JOptionPane.showInputDialog(
            SwingUtilities.getWindowAncestor(panel),
            "Enter new category name:",
            group.getName()
        );
        if (newName != null && !newName.trim().isEmpty())
        {
            group.setName(newName.trim());
            plugin.getAccountStorage().saveGroup(group);
            panel.rebuild();
        }
    }

    private void confirmDelete()
    {
        int result = JOptionPane.showConfirmDialog(
            SwingUtilities.getWindowAncestor(panel),
            "Delete category \"" + SafeText.singleLine(group.getName()) + "\"?\n"
                + "Accounts in this category will be moved to Uncategorized.",
            "Confirm Delete",
            JOptionPane.YES_NO_OPTION,
            JOptionPane.WARNING_MESSAGE
        );
        if (result == JOptionPane.YES_OPTION)
        {
            plugin.getAccountStorage().deleteGroup(group.getId());
            panel.rebuild();
        }
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.ui.components.Theme;
import com.mylosis.roster.ui.dnd.AccountDragListener;
import com.mylosis.roster.ui.dnd.DragDropManager;

import javax.swing.*;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;

/**
 * Builds the card container for one category or the Uncategorized area, in
 * whichever view mode is active, and wires each card for selection and drag.
 */
final class CardListBuilder
{
    private static final int GRID_COLUMNS = 2;

    private CardListBuilder() {}

    /**
     * @param categoryColor edge stripe color for the cards; null for none
     * @param trailing      a component placed after the cards (a category's add form), or null
     * @param cardsOut      receives the created cards in display order
     */
    static JPanel build(RosterPlugin plugin, RosterPanel panel, DragDropManager dragDropManager,
                        List<Account> accounts, Color categoryColor, JComponent trailing,
                        List<AccountCardPanel> cardsOut)
    {
        List<AccountCardPanel> cards = new ArrayList<>(accounts.size());
        for (Account account : accounts)
        {
            AccountCardPanel card = new AccountCardPanel(plugin, panel, account, categoryColor);
            card.attachTreeListener(new AccountDragListener(dragDropManager, card));
            panel.registerCard(account.getId(), card);
            cards.add(card);
        }
        cardsOut.addAll(cards);

        if (plugin.getConfig().gridView())
        {
            JPanel grid = new JPanel(new GridLayout(0, GRID_COLUMNS, Theme.SPACING_XS, Theme.SPACING_XS));
            grid.setBackground(Theme.BACKGROUND);
            cards.forEach(grid::add);

            // NORTH keeps the grid rows at their preferred height.
            JPanel wrapper = new JPanel(new BorderLayout());
            wrapper.setBackground(Theme.BACKGROUND);
            wrapper.add(grid, BorderLayout.NORTH);
            if (trailing != null)
            {
                wrapper.add(trailing, BorderLayout.CENTER);
            }
            return wrapper;
        }

        JPanel list = new JPanel();
        list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
        list.setBackground(Theme.BACKGROUND);
        for (AccountCardPanel card : cards)
        {
            list.add(card);
            list.add(Box.createVerticalStrut(Theme.SPACING_XS));
        }
        if (trailing != null)
        {
            list.add(trailing);
        }
        return list;
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterConfig;
import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.model.AccountMetadata;
import com.mylosis.roster.ui.components.AccountTypeBadge;
import com.mylosis.roster.ui.components.SafeText;
import com.mylosis.roster.ui.components.Theme;

import javax.swing.*;
import java.awt.*;

/**
 * Builds the text column of a list-view card: name row (online dot, name,
 * type badge), login, notes preview, and the last-online stamp, each subject
 * to the privacy settings. Rebuilt in place when the card's state changes.
 */
final class ListCardBuilder
{
    private static final int NAME_MAX_CHARS = 15;
    /** Shorter when the online dot takes room in the name row. */
    private static final int NAME_MAX_CHARS_ONLINE = 13;
    private static final int LOGIN_MAX_CHARS = 25;
    private static final int NOTES_MAX_CHARS = 22;

    private ListCardBuilder() {}

    static JPanel buildInfo(RosterPlugin plugin, RosterPanel panel, Account account, Font baseFont)
    {
        RosterConfig config = plugin.getConfig();
        JPanel info = new JPanel(new GridBagLayout());
        info.setOpaque(false);

        GridBagConstraints gbc = new GridBagConstraints();
        gbc.gridx = 0;
        gbc.gridy = 0;
        gbc.anchor = GridBagConstraints.WEST;
        gbc.fill = GridBagConstraints.HORIZONTAL;
        gbc.weightx = 1.0;

        String displayName = AccountCardHelper.resolveDisplayName(account, config);
        boolean online = AccountCardHelper.isOnline(plugin, account);

        JPanel nameRow = new JPanel(new FlowLayout(FlowLayout.LEFT, Theme.SPACING_SM, 0));
        nameRow.setOpaque(false);
        if (online)
        {
            nameRow.add(AccountCardHelper.createOnlineDot());
        }
        nameRow.add(AccountCardHelper.truncatingLabel(displayName, Theme.TEXT_PRIMARY,
            Theme.fontBold(baseFont, Theme.FONT_SIZE_HEADING), online ? NAME_MAX_CHARS_ONLINE : NAME_MAX_CHARS));
        nameRow.add(AccountCardHelper.createTypeBadge(plugin, panel, account, AccountTypeBadge.DEFAULT_SIZE));
        info.add(nameRow, gbc);
        gbc.gridy++;

        String username = account.getUsername();
        if (!config.hideLogin() && username != null && !username.equals(displayName))
        {
            info.add(AccountCardHelper.truncatingLabel(username, Theme.TEXT_SECONDARY,
                Theme.fontRegular(baseFont, Theme.FONT_SIZE_HEADING), LOGIN_MAX_CHARS), gbc);
            gbc.gridy++;
        }

        AccountMetadata meta = account.getMetadata();
        String notes = meta != null ? meta.getNotes() : null;
        if (!config.hideNotes() && notes != null && !notes.isEmpty())
        {
            JLabel notesLabel = AccountCardHelper.truncatingLabel(notes, Theme.TEXT_SECONDARY,
                Theme.fontRegular(baseFont, Theme.FONT_SIZE_BODY), NOTES_MAX_CHARS);
            notesLabel.setToolTipText("<html><body style='width: 200px'>" + SafeText.escapeHtml(notes) + "</body></html>");
            info.add(notesLabel, gbc);
            gbc.gridy++;
        }

        // Hidden while online: the green dot already says so, and "just now"
        // would be misleading after hours of play.
        String lastOnline = meta != null ? AccountCardHelper.formatTimeAgo(meta.getLastOnlineAt()) : null;
        if (!online && !config.hideLastOnline() && lastOnline != null)
        {
            JLabel lastOnlineLabel = new JLabel(lastOnline);
            lastOnlineLabel.setForeground(Theme.TEXT_MUTED);
            lastOnlineLabel.setFont(Theme.fontRegular(baseFont, Theme.FONT_SIZE_TINY));
            lastOnlineLabel.setToolTipText("Last seen logged in on this client");
            info.add(lastOnlineLabel, gbc);
        }

        return info;
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.ui.components.InlineAccountForm;
import com.mylosis.roster.ui.components.Theme;
import lombok.Getter;

import javax.swing.*;
import java.awt.*;

/**
 * Expands a list-view card into its inline edit form and collapses it again.
 */
class CardExpansionHandler
{
    private final RosterPlugin plugin;
    private final RosterPanel panel;
    private final AccountCardPanel card;
    private final JPanel headerPanel;

    /** Hidden container for the edit form, which is only built on first expand. */
    @Getter
    private final JPanel formPanel;
    private InlineAccountForm editForm;
    @Getter
    private boolean expanded = false;

    CardExpansionHandler(RosterPlugin plugin, RosterPanel panel, AccountCardPanel card, JPanel headerPanel)
    {
        this.plugin = plugin;
        this.panel = panel;
        this.card = card;
        this.headerPanel = headerPanel;

        formPanel = new JPanel(new BorderLayout());
        formPanel.setBackground(Theme.FORM_BACKGROUND);
        formPanel.setBorder(BorderFactory.createMatteBorder(1, 0, 0, 0, Theme.CARD_BORDER));
        formPanel.setVisible(false);
    }

    private void ensureEditForm()
    {
        if (editForm != null)
        {
            return;
        }
        editForm = new InlineAccountForm(plugin.getAccountStorage(), card.getAccount(), true, null);
        editForm.setOnSave(saved -> {
            plugin.getAccountStorage().saveAccount(saved);
            collapse();
            panel.rebuild();
        });
        editForm.setOnCancel(this::collapse);
        formPanel.add(editForm, BorderLayout.CENTER);
    }

    void toggleExpanded()
    {
        if (expanded) collapse();
        else expand();
    }

    void expand()
    {
        if (expanded) return;
        panel.collapseExpandedCard();
        panel.setExpandedCard(card);
        expanded = true;
        ensureEditForm();
        formPanel.setVisible(true);

        // Size the card to exactly header + form + border.
        Insets insets = card.getInsets();
        int height = headerPanel.getPreferredSize().height + formPanel.getPreferredSize().height
            + insets.top + insets.bottom;
        card.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
        card.setPreferredSize(new Dimension(card.getWidth(), height));

        editForm.focusUsernameField();
        AccountCardHelper.revalidateScrollPane(card);
    }

    void collapse()
    {
        if (!expanded) return;
        expanded = false;
        formPanel.setVisible(false);
        card.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.CARD_HEIGHT));
        card.setPreferredSize(null);
        panel.setExpandedCard(null);
        AccountCardHelper.revalidateScrollPane(card);
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.RosterConfig;
import com.mylosis.roster.RosterPlugin;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.ui.components.AccountTypeBadge;
import com.mylosis.roster.ui.components.SafeText;
import com.mylosis.roster.ui.components.Theme;

import javax.swing.*;
import javax.swing.text.JTextComponent;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.util.Arrays;

/**
 * Shared building blocks for account cards in both list and grid view.
 */
final class AccountCardHelper
{
    private AccountCardHelper() {} // Prevent instantiation

    /**
     * Creates a small green dot indicating the account is currently logged in.
     */
    static JPanel createOnlineDot()
    {
        int size = Theme.ONLINE_DOT_SIZE;
        JPanel dot = new JPanel()
        {
            @Override
            protected void paintComponent(Graphics g)
            {
                super.paintComponent(g);
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(Theme.ONLINE_INDICATOR);
                g2.fillOval(0, 0, size, size);
                g2.dispose();
            }
        };
        dot.setOpaque(false);
        dot.setPreferredSize(new Dimension(size, size));
        dot.setMaximumSize(new Dimension(size, size));
        dot.setToolTipText("Currently logged in");
        return dot;
    }

    /**
     * A plain-text label showing at most {@code maxChars} characters, cut at a
     * word boundary where possible, with the full text as its tooltip.
     */
    static JLabel truncatingLabel(String text, Color color, Font font, int maxChars)
    {
        String display = text;
        boolean truncated = text != null && text.length() > maxChars;
        if (truncated)
        {
            String trimmed = text.substring(0, maxChars);
            int lastSpace = trimmed.lastIndexOf(' ');
            display = (lastSpace > maxChars / 2 ? trimmed.substring(0, lastSpace) : trimmed) + "...";
        }
        JLabel label = SafeText.plain(new JLabel(display));
        label.setForeground(color);
        label.setFont(font);
        if (truncated) label.setToolTipText(SafeText.htmlSafe(text));
        return label;
    }

    /**
     * Revalidates a component and repaints its enclosing scroll pane, the
     * layout boundary for everything inside the card list.
     */
    static void revalidateScrollPane(Component component)
    {
        component.revalidate();
        Container scrollPane = SwingUtilities.getAncestorOfClass(JScrollPane.class, component);
        if (scrollPane != null)
        {
            scrollPane.revalidate();
            scrollPane.repaint();
        }
        else
        {
            component.repaint();
        }
    }

    /**
     * Formats a millisecond timestamp as a coarse relative-time string
     * (e.g. "just now", "5m ago", "3h ago", "2d ago", "4mo ago", "1y ago").
     * Returns null for null or future-dated input.
     */
    static String formatTimeAgo(Long epochMillis)
    {
        if (epochMillis == null)
        {
            return null;
        }
        long diff = System.currentTimeMillis() - epochMillis;
        if (diff < 0)
        {
            return null;
        }

        long minute = 60_000L;
        long hour = 60 * minute;
        long day = 24 * hour;
        long month = 30 * day;
        long year = 365 * day;

        if (diff < 2 * minute) return "just now";
        if (diff < hour)       return (diff / minute) + "m ago";
        if (diff < day)        return (diff / hour)   + "h ago";
        if (diff < month)      return (diff / day)    + "d ago";
        if (diff < year)       return (diff / month)  + "mo ago";
        return (diff / year) + "y ago";
    }

    /**
     * The name to show on a card under the current privacy settings.
     */
    static String resolveDisplayName(Account account, RosterConfig config)
    {
        String displayName;
        if (config.hideAlias() && config.hideLogin())
        {
            displayName = "Account";
        }
        else if (config.hideAlias())
        {
            displayName = account.getUsername();
        }
        else
        {
            displayName = account.getDisplayName();
        }
        return displayName != null ? displayName : account.getUsername();
    }

    /** Whether {@code account} is the character currently logged in on this client. */
    static boolean isOnline(RosterPlugin plugin, Account account)
    {
        String loggedIn = plugin.getLoggedInName();
        // Prefer the learned in-game character name; the display name only
        // matches by coincidence when the alias equals the character name.
        String matchName = account.getCharacterName() != null
            ? account.getCharacterName()
            : account.getDisplayName();
        return loggedIn != null && loggedIn.equalsIgnoreCase(matchName);
    }

    /**
     * The clickable account-type badge. Picking a type saves it and refreshes
     * just this card.
     */
    static AccountTypeBadge createTypeBadge(RosterPlugin plugin, RosterPanel panel, Account account, int size)
    {
        return new AccountTypeBadge(account.resolveAccountType(), size, newType ->
        {
            account.ensureMetadata().setAccountType(newType);
            plugin.getAccountStorage().saveAccount(account);
            panel.refreshAccount(account.getId());
        });
    }

    /**
     * Adds {@code listener} to {@code root} and every descendant that doesn't
     * already have it, so it can be re-run after a card rebuilds its content.
     * With {@code skipControls}, buttons, badges, and fields (which handle
     * their own clicks) and their children are left out.
     */
    static void attachToTree(Component root, MouseAdapter listener, boolean skipControls)
    {
        if (!Arrays.asList(root.getMouseListeners()).contains(listener))
        {
            root.addMouseListener(listener);
            root.addMouseMotionListener(listener);
        }
        if (root instanceof Container)
        {
            for (Component child : ((Container) root).getComponents())
            {
                if (!skipControls || !isInteractive(child))
                {
                    attachToTree(child, listener, skipControls);
                }
            }
        }
    }

    private static boolean isInteractive(Component c)
    {
        return c instanceof AbstractButton || c instanceof AccountTypeBadge
            || c instanceof JTextComponent || c instanceof JComboBox;
    }
}

