    private final Runnable onEdit;

    AccountCardActions(RosterPlugin plugin, RosterPanel panel, Account account, Runnable onEdit)
    {
        this.plugin = plugin;
        this.panel = panel;
        this.account = account;
        this.onEdit = onEdit;
    }

    JPopupMenu createContextMenu()
    {
        JPopupMenu menu = new JPopupMenu();

        addItem(menu, "Edit", onEdit);
        addItem(menu, "Copy Username", () -> plugin.getImportExportService().copyToClipboard(account.getUsername()));
        addItem(menu, "Export to Clipboard", this::exportAccount);
        menu.addSeparator();
        addItem(menu, "Move to Category...", this::showMoveToCategoryDialog);
        menu.addSeparator();
        addItem(menu, "Delete", this::confirmDelete).setForeground(Theme.BUTTON_DANGER);

        return menu;
    }

    private static JMenuItem addItem(JPopupMenu menu, String label, Runnable action)
    {
        JMenuItem item = new JMenuItem(label);
        item.addActionListener(e -> action.run());
        menu.add(item);
        return item;
    }

    private void showMoveToCategoryDialog()
    {
        AccountStorage storage = plugin.getAccountStorage();
        List<ProfileGroup> groups = storage.getGroups();

        // Items wrap the id (two categories can share a name) and render the
        // name HTML-safe (the dialog shows them through a JLabel).
        GroupComboItem[] choices = new GroupComboItem[groups.size() + 1];
        choices[0] = GroupComboItem.UNCATEGORIZED;
        for (int i = 0; i < groups.size(); i++)
        {
            choices[i + 1] = new GroupComboItem(groups.get(i).getId(), groups.get(i).getName());
        }

        GroupComboItem selected = (GroupComboItem) JOptionPane.showInputDialog(
            SwingUtilities.getWindowAncestor(panel),
            "Select category:",
            "Move to Category",
            JOptionPane.PLAIN_MESSAGE,
            null,
            choices,
            choices[0]
        );

        if (selected == null || Objects.equals(selected.getId(), account.getGroupId()))
        {
            return;
        }
        // Land at the end of the new category.
        account.ensureMetadata().setSortOrder(storage.nextAccountSortOrder(selected.getId()));
        account.setGroupId(selected.getId());
        storage.saveAccount(account);
        panel.rebuild();
    }

    private void confirmDelete()
    {
        if (plugin.getConfig().confirmDelete())
        {
            int result = JOptionPane.showConfirmDialog(
                SwingUtilities.getWindowAncestor(panel),
                "Are you sure you want to delete \"" + SafeText.singleLine(account.getDisplayName()) + "\"?",
                "Confirm Delete",
                JOptionPane.YES_NO_OPTION,
                JOptionPane.WARNING_MESSAGE
            );
            if (result != JOptionPane.YES_OPTION)
            {
                return;
            }
        }

        plugin.getAccountStorage().deleteAccount(account.getId());
        panel.rebuild();
    }

    private void exportAccount()
    {
        ExportResult result = plugin.getImportExportService().exportAccountToClipboard(account);
        if (result.isSuccess())
        {
            panel.showNotification("Exported " + account.getDisplayName(), NotificationToast.Type.SUCCESS);
        }
        else
        {
            panel.showNotification("Export failed: " + result.getError(), NotificationToast.Type.ERROR);
        }
    }
}

package com.mylosis.roster.ui;

import com.mylosis.roster.model.SortKey;
import com.mylosis.roster.ui.components.Controls;
import com.mylosis.roster.ui.components.SearchBar;
import com.mylosis.roster.ui.components.Theme;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * Builds the header of the Roster panel: title and version, search bar, and
 * the + Account, + Category, and sort buttons.
 */
final class PanelHeaderBuilder
{
    private PanelHeaderBuilder() {}

    /**
     * @param onSearchChanged fired with the lowercase filter after the user pauses typing
     * @param onAddAccount    the "+ Account" button action
     * @param onAddCategory   the "+ Category" button action
     * @param currentSortKey  read each time the sort menu opens, so its check mark is current
     * @param onSortChanged   fired when the user picks a sort key
     */
    static JPanel build(Consumer<String> onSearchChanged,
                        Runnable onAddAccount,
                        Runnable onAddCategory,
                        Supplier<SortKey> currentSortKey,
                        Consumer<SortKey> onSortChanged)
    {
        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setBackground(Theme.BACKGROUND);
        header.setBorder(BorderFactory.createEmptyBorder(0, 0, Theme.SPACING_LG, 0));

        header.add(createTitleRow());
        header.add(Box.createVerticalStrut(Theme.SPACING_MD));
        header.add(createSearchBar(onSearchChanged));
        header.add(Box.createVerticalStrut(Theme.SPACING_MD));
        header.add(createActionButtonsRow(onAddAccount, onAddCategory, currentSortKey, onSortChanged));
        return header;
    }

    private static JPanel createTitleRow()
    {
        JPanel titleRow = new JPanel(new BorderLayout());
        titleRow.setBackground(Theme.BACKGROUND);
        titleRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        titleRow.setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel titleLabel = new JLabel("Roster");
        titleLabel.setForeground(Theme.TEXT_PRIMARY);
        titleLabel.setFont(Theme.fontBold(titleLabel.getFont(), Theme.FONT_SIZE_TITLE));
        titleRow.add(titleLabel, BorderLayout.WEST);

        JLabel versionLabel = new JLabel("v" + Theme.VERSION);
        versionLabel.setForeground(Theme.TEXT_MUTED);
        versionLabel.setFont(Theme.fontRegular(versionLabel.getFont(), Theme.FONT_SIZE_TINY));
        titleRow.add(versionLabel, BorderLayout.EAST);

        return titleRow;
    }

    private static SearchBar createSearchBar(Consumer<String> onSearchChanged)
    {
        SearchBar bar = new SearchBar();
        bar.setPlaceholder("Filter...");
        bar.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
        bar.setAlignmentX(Component.LEFT_ALIGNMENT);
        bar.setOnSearchChanged(onSearchChanged);
        return bar;
    }

    private static JPanel createActionButtonsRow(Runnable onAddAccount, Runnable onAddCategory,
                                                 Supplier<SortKey> currentSortKey,
                                                 Consumer<SortKey> onSortChanged)
    {
        JPanel buttonRow = new JPanel(new GridBagLayout());
        buttonRow.setBackground(Theme.BACKGROUND);
        buttonRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, Theme.BUTTON_HEIGHT + 4));
        buttonRow.setAlignmentX(Component.LEFT_ALIGNMENT);

        GridBagConstraints gbc = new GridBagConstraints();
        gbc.fill = GridBagConstraints.BOTH;
        gbc.gridy = 0;

        gbc.gridx = 0;
        gbc.weightx = 0.55;
        gbc.insets = new Insets(0, 0, 0, Theme.SPACING_XS);
        buttonRow.add(headerButton("+ Account", "Add a new account", false, onAddAccount), gbc);

        gbc.gridx = 1;
        gbc.weightx = 0.30;
        buttonRow.add(headerButton("+ Category", "Add category", false, onAddCategory), gbc);

        gbc.gridx = 2;
        gbc.weightx = 0.15;
        gbc.insets = new Insets(0, 0, 0, 0);
        JButton sortButton = headerButton("\u21F5", "Sort accounts", true, null);
        sortButton.addActionListener(e -> showSortMenu(sortButton, currentSortKey.get(), onSortChanged));
        buttonRow.add(sortButton, gbc);

        return buttonRow;
    }

    private static JButton headerButton(String text, String tooltip, boolean bold, Runnable onClick)
    {
        JButton button = Controls.flatButton(text, Theme.BUTTON_SECONDARY, Theme.BUTTON_SECONDARY_HOVER);
        button.setFont(bold
            ? Theme.fontBold(button.getFont(), Theme.FONT_SIZE_BODY)
            : Theme.fontRegular(button.getFont(), Theme.FONT_SIZE_BODY));
        button.setToolTipText(tooltip);
        if (onClick != null)
        {
            button.addActionListener(e -> onClick.run());
        }
        return button;
    }

    /** Lists every {@link SortKey}, with the active one checked and highlighted. */
    private static void showSortMenu(JButton anchor, SortKey active, Consumer<SortKey> onSortChanged)
    {
        JPopupMenu menu = new JPopupMenu();
        menu.setBackground(Theme.BACKGROUND_DARKER);
        menu.setBorder(BorderFactory.createLineBorder(Theme.CARD_BORDER, 1));

        for (SortKey key : SortKey.values())
        {
            boolean isActive = key == active;
            // A leading check glyph marks the active item as a state, not a button.
            JMenuItem item = new JMenuItem((isActive ? "\u2713 " : "    ") + key.getLabel());
            item.setBackground(Theme.BACKGROUND_DARKER);
            item.setForeground(isActive ? Theme.ACCENT_ORANGE : Theme.TEXT_PRIMARY);
            item.setFont(isActive
                ? Theme.fontBold(item.getFont(), Theme.FONT_SIZE_SMALL)
                : Theme.fontRegular(item.getFont(), Theme.FONT_SIZE_SMALL));
            item.setBorder(new EmptyBorder(Theme.SPACING_XS, Theme.SPACING_SM, Theme.SPACING_XS, Theme.SPACING_SM));
            item.addActionListener(e -> onSortChanged.accept(key));
            menu.add(item);
        }
        menu.show(anchor, 0, anchor.getHeight());
    }
}

package com.mylosis.roster;

import com.google.inject.Provides;
import com.mylosis.roster.model.Account;
import com.mylosis.roster.storage.AccountStorage;
import com.mylosis.roster.storage.ImportExportService;
import com.mylosis.roster.ui.RosterPanel;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.swing.SwingUtilities;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;

@PluginDescriptor(
    name = "Roster",
    description = "Enhanced account management for OSRS with groups, import/export, and drag-and-drop",
    tags = {"account", "roster", "login", "management", "utility"}
)
public class RosterPlugin extends Plugin
{
    private static final String ICON_PATH = "/com/mylosis/roster/icon.png";

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    @Getter
    private ColorPickerManager colorPickerManager;

    @Inject
    @Getter
    private RosterConfig config;

    @Inject
    @Getter
    private AccountStorage accountStorage;

    @Inject
    @Getter
    private ImportExportService importExportService;

    @Inject
    @Getter
    private ConfigManager configManager;

    private LoginTracker loginTracker;

    /** Written on the EDT, read from the client and config threads. Null while stopped. */
    private volatile RosterPanel panel;
    private NavigationButton navButton;

    @Getter
    private volatile String selectedAccountId;

    @Override
    protected void startUp()
    {
        loginTracker = new LoginTracker(accountStorage);
        panel = new RosterPanel(this);

        navButton = NavigationButton.builder()
            .tooltip("Roster")
            .icon(ImageUtil.loadImageResource(getClass(), ICON_PATH))
            .priority(5)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navButton);

        // Enabling the plugin mid-session gets no LOGGED_IN event; pick up the
        // current character directly so the online dot is right from the start.
        clientThread.invokeLater(() -> {
            if (client.getGameState() == GameState.LOGGED_IN)
            {
                return trackLogin();
            }
            return true;
        });
    }

    @Override
    protected void shutDown()
    {
        clientToolbar.removeNavigation(navButton);
        panel = null;
        navButton = null;
        selectedAccountId = null;
        loginTracker.reset();
        // Flushes the pending file write and drops the cache, so the next
        // start reloads whatever ConfigManager holds by then.
        accountStorage.shutdown();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        GameState state = event.getGameState();
        if (state == GameState.LOGGED_IN)
        {
            // The local player may not exist yet; retry each tick until it does.
            clientThread.invokeLater(() -> {
                if (client.getGameState() != GameState.LOGGED_IN)
                {
                    // Logged out again before the player resolved: stop
                    // retrying, or this closure would run every frame.
                    return true;
                }
                return trackLogin();
            });
        }
        else if (state == GameState.LOGIN_SCREEN || state == GameState.CONNECTION_LOST)
        {
            String previous = loginTracker.setLoggedInName(null);
            if (previous != null)
            {
                onEdt(() -> refreshCards(Collections.singleton(loginTracker.findAccountIdByName(previous))));
            }
        }
    }

    /**
     * Client thread. Records the logged-in character once the local player has
     * a name; returns false (retry next tick) until then.
     */
    private boolean trackLogin()
    {
        Player player = client.getLocalPlayer();
        String name = player != null ? player.getName() : null;
        if (name == null)
        {
            return false;
        }
        String previous = loginTracker.setLoggedInName(name);
        // AccountStorage is EDT-confined; stamping here on the client thread
        // would race UI-driven saves.
        onEdt(() -> refreshCards(loginTracker.recordLogin(name, previous)));
        return true;
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!RosterConfig.CONFIG_GROUP.equals(event.getGroup()) || event.getKey() == null)
        {
            return;
        }

        if (AccountStorage.CONFIG_KEY_DATA.equals(event.getKey()))
        {
            // Our own saves echo back here and are ignored: rebuilding on them
            // would bounce the whole panel on every badge click, drag, and
            // last-online stamp. Any other value means RuneLite replaced the
            // data (profile switch, synced config), possibly off the EDT.
            if (!accountStorage.isOwnWrite(event.getNewValue()))
            {
                onEdt(() -> {
                    if (accountStorage.reloadIfChangedExternally())
                    {
                        panel.rebuild();
                    }
                });
            }
            return;
        }

        // A user-visible setting (privacy toggles, grid view, sort key, ...).
        onEdt(() -> panel.rebuild());
    }

    /** Runs {@code task} on the EDT, skipping it if the plugin has stopped by then. */
    private void onEdt(Runnable task)
    {
        SwingUtilities.invokeLater(() -> {
            if (panel != null)
            {
                task.run();
            }
        });
    }

    private void refreshCards(Collection<String> accountIds)
    {
        for (String id : accountIds)
        {
            if (id != null)
            {
                panel.refreshAccount(id);
            }
        }
    }

    /** Fills the login screen's username field with this account's login. */
    public void selectAccount(Account account)
    {
        if (account == null)
        {
            return;
        }

        clientThread.invokeLater(() -> {
            if (client.getGameState() != GameState.LOGIN_SCREEN)
            {
                return;
            }

            client.setUsername(account.getUsername());
            String previousId = selectedAccountId;
            String newId = account.getId();
            selectedAccountId = newId;
            // Arm the one-shot link so the next completed login can learn this
            // account's character name.
            loginTracker.armSelectionLink(newId);

            if (newId.equals(previousId))
            {
                return;
            }
            // Only the two cards whose highlight changed need repainting.
            onEdt(() -> refreshCards(previousId != null ? Arrays.asList(previousId, newId)
                : Collections.singleton(newId)));
        });
    }

    /** The logged-in character's name, or null when logged out. */
    public String getLoggedInName()
    {
        return loginTracker.getLoggedInName();
    }

    @Provides
    RosterConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(RosterConfig.class);
    }
}
